Ceviri.ekle("vi","olay",{
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Hiệp ước đầu tiên với Hợp chúng quốc Hoa Kỳ", "d737516f"], "d": ["Theo hiệp ước thương mại và hàng hải ký sau nhiều năm tiếp xúc, Hoa Kỳ được hưởng quy chế tối huệ quốc trên lãnh thổ Ottoman và quyền qua lại thương mại ở các Eo biển. Một điều khoản mật riêng dự kiến Ottoman, khi muốn, được đặt đóng tàu tại các xưởng đóng tàu Mỹ và mua tàu đóng sẵn cùng gỗ; Thượng viện Hoa Kỳ phê chuẩn hiệp ước nhưng bác điều khoản mật này với tỷ số 18 phiếu chống 27. Tuy vậy, con đường đóng tàu vẫn không bị đóng: Henry Eckford bán cho Ottoman con tàu ông đưa đến năm 1831, và các thợ cả người Mỹ làm việc tại Aynalıkavak đã mang đến cho hải quân những loại tàu mới. Hiệp ước này trở thành văn kiện của mối quan hệ toàn diện đầu tiên mà Đế quốc Ottoman thiết lập với một quốc gia ngoài châu Âu.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Chấm dứt sự cai trị của người Mamluk ở Baghdad", "7e1d38a3"], "d": ["Theo đuổi chính sách tập quyền, Mahmud II tuyên bố tổng đốc Baghdad Davud Pasha, người không gửi số tiền được yêu cầu và cho giết viên quan do triều đình phái đến, là kẻ phản loạn. Lực lượng dưới quyền Ali Rıza Pasha chiếm thành phố sau chín mươi ngày vây hãm, và gần như toàn bộ người Mamluk bị thanh trừng. Như vậy chính quyền Mamluk bán độc lập kéo dài từ năm 1704 chấm dứt, và Iraq lại được gắn trực tiếp với trung ương.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Thành lập Trường Võ bị tại doanh trại Maçka", "bf31c7d9"], "d": ["Để cung cấp cho quân đội Asakir-i Mansure-i Muhammediye những sĩ quan được đào tạo theo kiểu châu Âu, Trường Khoa học Quân sự được mở tại doanh trại Maçka. Học viên được học toán, bản đồ, công sự và ngoại ngữ; chẳng bao lâu sau, đội ngũ được củng cố bằng việc gửi học viên sang Vienna và Paris. Ngôi trường này là nơi khai sinh truyền thống sĩ quan được đào tạo chính quy trong quân đội Ottoman và do đó cũng là nơi sinh ra thế hệ quân nhân – trí thức mới xuất hiện vào cuối thế kỷ 19.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Tripoli (Libya) được đặt trực thuộc trung ương — Triều đại Karamanli chấm dứt", "faabcb96"], "d": ["Trước những cuộc tranh giành ngôi trong dòng họ Karamanli và sức ép gia tăng của châu Âu sau khi Pháp chiếm Algiers năm 1830, Triều đình Cổng Cao đã trực tiếp can thiệp vào Tripoli. Hạm đội phái từ Istanbul tiến vào thành phố, vị bey Karamanli cuối cùng bị bãi chức và đưa về Istanbul, và tỉnh được giao cho một tổng đốc do trung ương bổ nhiệm. Khi thời kỳ triều đại kéo dài 124 năm kết thúc, mảnh đất cuối cùng ở Bắc Phi do Đế quốc Ottoman trực tiếp cai quản đã được củng cố.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Bãi bỏ chức defterdar và thành lập Bộ Tài chính", "89f8125e"], "d": ["Chức defterdar, đứng đầu trật tự tài chính Ottoman cổ điển, bị bãi bỏ; Bộ Tài chính, một bộ theo kiểu châu Âu, được thành lập và các ngân khố phân tán được tập trung vào một mối. Cùng năm, các cơ quan khác của Triều đình Cổng Cao cũng được tổ chức lại dưới danh nghĩa bộ (nezaret), chuyển sang cơ cấu hội đồng bộ trưởng hiện đại. Cải cách này là một trong những bước quan trọng nhất chuẩn bị nền tảng hành chính cho Sắc lệnh Tanzimat công bố một năm sau đó.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Người Anh đặt chân tại Aden", "ddbd556b"], "d": ["Dựa trên hiệp định thương mại và hữu nghị ký năm 1802 với sultan Lahej là Ahmad ibn Abd al-Karim, Anh đổ quân lên cảng Aden và kiểm soát thành phố. Hải cảng trấn giữ cửa Biển Đỏ này, với tư cách trạm tiếp than trên đường sang Ấn Độ, trở thành điểm then chốt trong chiến lược đế quốc của Anh. Tuy yêu sách của Đế quốc Ottoman đối với Yemen vẫn tồn tại trên giấy tờ, quyền thống trị thực tế của họ ở bờ biển phía nam không bao giờ trở lại sau thời điểm này.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Trở lại bờ biển Tihamah: chiếm Hodeidah, Zabid và Mocha", "353982d2"], "d": ["Trên bờ biển Yemen bị bỏ trống sau khi quân Ai Cập rút đi năm 1840, các lực lượng dưới quyền Tevfik Pasha, đặt dưới sự giám sát của sharif Mecca, đã đổ bộ và đưa các cảng Hodeidah, Zabid và Mocha vào quyền cai quản của Ottoman. Dù muốn tiến đến Sanaa, họ phải quay về Hodeidah vì sự kháng cự của dân chúng; như vậy vùng cao nguyên vẫn thuộc các imam Zaydi, và quyền thống trị của Ottoman trong hai mươi ba năm chỉ kéo dài trên dải đất Tihamah. Nội địa Yemen mãi đến năm 1872 mới được thu hồi bằng chiến dịch của Ahmed Muhtar Pasha.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Công ước Balta Liman: Ottoman và Nga cùng bảo hộ Wallachia và Moldavia", "d3bb22e9"], "d": ["Khi các cuộc cách mạng năm 1848 lan đến Wallachia và Moldavia, quân Ottoman và Nga đã cùng chiếm đóng hai công quốc. Theo công ước ký tại Balta Liman, hai bên quyết định các voyvoda không còn được bầu mà do sultan bổ nhiệm với nhiệm kỳ bảy năm, và hai nước thiết lập quyền kiểm soát chung trong vùng. Thỏa thuận giữ nguyên chủ quyền trên giấy tờ của Ottoman nhưng công nhận cho Nga quyền đồng quản trên thực tế và đẩy nhanh quá trình các công quốc sông Danube tách khỏi Ottoman.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Vấn đề người tị nạn Hungary: Kossuth và các đồng chí lánh nạn tại Ottoman", "1c7d7ef4"], "d": ["Khi cuộc cách mạng Hungary 1848–1849 bị dập tắt bởi sự can thiệp của Nga và Áo, Lajos Kossuth cùng hàng nghìn người tị nạn Hungary và Ba Lan đã lánh sang lãnh thổ Ottoman. Áo và Nga gay gắt đòi dẫn độ người tị nạn; Triều đình Cổng Cao, được Anh và Pháp ủng hộ, từ chối dẫn độ và bố trí nhóm này ở Kütahya. Nhóm thân cận của Kossuth ở đây khoảng mười tám tháng, và hàng trăm người tị nạn cải đạo sang Hồi giáo rồi vào phục vụ Ottoman. Sự kiện được coi là một trong những thắng lợi ngoại giao hiếm hoi nâng cao uy tín của Ottoman thời Tanzimat trong dư luận châu Âu.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Thành lập Hội đồng Khoa học (Encümen-i Daniş): viện hàn lâm Ottoman đầu tiên ở Istanbul", "6fda1365"], "d": ["Được lập theo quyết định của Hội đồng Giáo dục Phổ thông, Encümen-i Daniş là viện hàn lâm khoa học Ottoman đầu tiên, được tổ chức nhằm biên soạn sách khoa học và giáo khoa bằng tiếng Thổ Nhĩ Kỳ. Viện được khai mạc trọng thể ngày 18 tháng 7 năm 1851 tại tòa nhà Darülmaarif; trong số các thành viên trong và ngoài nước có cả Ahmed Cevdet Pasha. Tuy tồn tại ngắn ngủi, những tác phẩm như bộ Lịch sử (Tarih) của Cevdet Pasha và Kavaid-i Osmaniye (Quy tắc tiếng Ottoman) là sản phẩm của cơ quan này, và nó được coi là cột mốc trong việc đưa tiếng Thổ Nhĩ Kỳ thành ngôn ngữ khoa học.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Chiến thắng Oltenița: thành công đầu tiên của Ottoman trên mặt trận sông Danube", "a660ad2f"], "d": ["Trong giai đoạn mở đầu Chiến tranh Crimea, Tổng tư lệnh Ömer Lütfi Pasha đã vượt sông Danube và đẩy lui lực lượng Nga tại Oltenița, gây cho họ tổn thất nặng. Chiến thắng ngay đầu cuộc chiến đã chặn đà tiến của Nga và cho châu Âu thấy sức mạnh mà quân đội Ottoman đạt được nhờ huấn luyện sau Tanzimat. Thành công này chuẩn bị nền tảng tâm lý giúp Anh và Pháp dễ dàng quyết định tham chiến bên cạnh Ottoman.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Hiệp ước liên minh với Anh và Pháp tại Istanbul", "04809278"], "d": ["Hiệp ước liên minh ký giữa Đế quốc Ottoman với Anh và Pháp chống Nga trong Chiến tranh Crimea quy định ba nước tiến hành chiến dịch chung và các đồng minh không được giảng hòa riêng trước khi chiến tranh kết thúc. Như vậy lần đầu tiên trong lịch sử, Đế quốc Ottoman tham gia một liên minh quân sự với các cường quốc châu Âu với tư cách bên bình đẳng. Hiệp ước này cũng tạo nền tảng pháp lý cho việc Ottoman được chính thức tiếp nhận vào hệ thống các nước châu Âu tại Paris hai năm sau.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Thành lập Sở Thị chính Istanbul: tổ chức đô thị hiện đại đầu tiên", "be4af27f"], "d": ["Quân đội đồng minh đổ dồn về Istanbul trong Chiến tranh Crimea và cuộc khủng hoảng hạ tầng do dân số tăng đã phơi bày sự bất cập của nền quản lý đô thị cổ điển lấy chức kadi làm trung tâm. Với Sở Thị chính (Şehremaneti) lập theo mẫu châu Âu, việc vệ sinh, định giá, giám sát chợ búa và chỉnh trang đô thị được tập trung vào một mối; năm sau, Khu Thị chính số Sáu được lập ở Beyoğlu – Galata làm khu thí điểm. Bước đi này được coi là khởi đầu của nền quản lý đô thị hiện đại ở Ottoman.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Hiệp ước Paris: Chiến tranh Crimea kết thúc và Ottoman được tiếp nhận vào hệ thống các nước châu Âu", "4aee0e2a"], "d": ["Hiệp ước Paris chấm dứt Chiến tranh Crimea đã tuyên bố Đế quốc Ottoman là thành viên bình đẳng của công pháp châu Âu và đặt sự toàn vẹn lãnh thổ của nó dưới sự bảo đảm chung của các cường quốc. Biển Đen được trung lập hóa, yêu sách bảo hộ thần dân Chính thống giáo mà Nga giành được kể từ Küçük Kaynarca bị vô hiệu hóa, và phần phía nam Bessarabia (các kaza Kiliya, Cahul, Izmail và Bolgrad) được trao cho Moldavia. Tuy nhiên, chính hiệp ước này lại biến Sắc lệnh Cải cách thành một cam kết quốc tế, qua đó hé mở cánh cửa cho sự can thiệp vào công việc nội bộ.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Khánh thành cung Dolmabahçe: trung tâm cai trị rời khỏi Topkapı", "71ad26d0"], "d": ["Cung điện mà Abdülmecid đặt gia đình Balyan xây năm 1842 đã khánh thành sau mười bốn năm thi công, và trung tâm cai trị của đất nước chuyển từ Topkapı bốn thế kỷ tuổi sang bờ eo Bosphorus. Với phong cách châu Âu, cầu thang pha lê và Đại sảnh Nghi lễ, cung điện trở thành sự thể hiện bằng đá của tham vọng Tây phương hóa thời Tanzimat. Tuy nhiên, chi phí khổng lồ của nó trở thành một trong những khoản bị chỉ trích nhiều nhất trong những năm tài chính Ottoman lún vào vòng xoáy vay nợ nước ngoài.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Wallachia và Moldavia hợp nhất dưới quyền Cuza: Romania ra đời", "baef4da5"], "d": ["Trong các cuộc bầu cử tổ chức sau Hiệp ước Paris, cả hai công quốc đều bầu Đại tá Alexandru Ioan Cuza làm voyvoda, qua đó thực hiện sự hợp nhất trên thực tế. Dù Triều đình Cổng Cao và Áo phản đối, việc đã rồi được Pháp ủng hộ buộc phải được chấp nhận. Liên hiệp này, trên giấy tờ vẫn lệ thuộc Ottoman, sẽ lấy tên Romania năm 1862 và đơn phương tuyên bố độc lập năm 1877; đây là bước ngoặt trong quá trình tan rã quyền thống trị của Ottoman dọc sông Danube.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Vụ Kuleli: âm mưu đảo chính đầu tiên chống Abdülmecid ở Istanbul", "e3653b21"], "d": ["Một hội kín gồm cả quân nhân lẫn dân sự, phản đối chính sách Tanzimat và quyền bình đẳng mà Sắc lệnh Cải cách công nhận cho người không theo Hồi giáo, đang lên kế hoạch phế truất sultan thì bị bắt quả tang khi đang họp tại thánh đường Kılıç Ali Pasha. Vì các bị cáo bị xét xử tại doanh trại Kuleli nên vụ việc được gọi theo tên này; các án tử hình được giảm thành lưu đày. Đây được coi là mưu toan đảo chính cung đình đầu tiên trong lịch sử Ottoman do một tổ chức được thành lập trên cơ sở ý thức hệ thực hiện.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Nội chiến giữa người Druze và người Maronite ở Núi Liban và các biến loạn Damascus", "5595fdd6"], "d": ["Các cuộc đụng độ bùng phát vào tháng 5 năm 1860 sau khi hai người Druze bị giết gần Sidon đã biến thành cuộc nội chiến Druze – Maronite đẫm máu nhất trên vùng núi, đến tháng 7 lan sang Damascus và khiến hàng nghìn người Cơ Đốc giáo thiệt mạng. Khi Pháp đổ quân, Triều đình Cổng Cao phái Fuad Pasha đến vùng này với quyền hạn đặc biệt; một chiến dịch trấn áp quyết liệt được tiến hành. Các sự kiện trở thành cớ cho sự can thiệp của châu Âu và là nguyên nhân trực tiếp khiến Liban được hưởng quy chế đặc biệt.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Tercüman-ı Ahval ra mắt: tờ báo tiếng Thổ Nhĩ Kỳ tư nhân đầu tiên ở Istanbul", "24792957"], "d": ["Tercüman-ı Ahval, do Agâh Efendi xuất bản và Şinasi đảm trách biên tập, là tờ báo tiếng Thổ Nhĩ Kỳ đầu tiên phát hành không có sự hỗ trợ của nhà nước. Lời dẫn trong số đầu tiên bênh vực quyền của dân chúng được lên tiếng về công việc của chính mình; tờ báo đăng nhiều kỳ vở “Hôn sự của thi sĩ” (Şair Evlenmesi) của Şinasi, qua đó cũng hé mở cánh cửa cho văn học Thổ Nhĩ Kỳ hiện đại. Sự ra đời của khái niệm công luận và báo chí đối lập ở Ottoman được gắn với thời điểm này.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Quy chế Núi Liban: Liban được hưởng quy chế mutasarrıf đặc quyền", "bf375603"], "d": ["Quy chế được soạn thảo dưới sức ép của các cường quốc sau các cuộc thảm sát năm 1860 đã biến Núi Liban thành một đơn vị mutasarrıf đặc quyền, trực thuộc Triều đình Cổng Cao và được cai quản cùng một hội đồng hành chính lập theo thế cân bằng giữa các giáo phái. Quy chế quy định mutasarrıf phải là thần dân Ottoman theo Công giáo và việc bổ nhiệm phải được các cường quốc chấp thuận; mutasarrıf đầu tiên là Davud Pasha. Trật tự này kéo dài đến năm 1915 và tạo nên hạt nhân của nhà nước Liban hiện đại.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Abdülmecid qua đời và Sultan Abdülaziz lên ngôi", "27204d7c"], "d": ["Khi Abdülmecid, người trong hai mươi hai năm trị vì đã ký Sắc lệnh Tanzimat và Sắc lệnh Cải cách, gục ngã vì bệnh lao, người em Abdülaziz lên ngôi. Trong những năm đầu, vị sultan mới mang lại hy vọng bằng các biện pháp tiết kiệm và lối sống giản dị; ông biến hải quân thành một trong những lực lượng hàng đầu thế giới. Tuy nhiên, vào cuối triều đại, nợ nước ngoài chồng chất, vụ vỡ nợ năm 1875 và các cuộc khởi nghĩa ở Balkan tích tụ lại, tạo nền cho cuộc phế truất năm 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Các công quốc hợp nhất lấy tên Romania", "d960e3fc"], "d": ["Wallachia và Moldavia, đã hợp nhất trên thực tế khi Cuza được bầu ở cả hai nơi năm 1859, đến năm 1862 gộp nghị viện và chính phủ vào một mối tại Bucharest và chính thức lấy tên Romania. Đế quốc Ottoman tuy vẫn giữ tư cách bá chủ về mặt pháp lý và khoản cống thuế hằng năm, trên thực tế đã mất quyền kiểm soát công quốc. Mốc thời gian này tượng trưng cho sự chấm dứt ảnh hưởng suốt bốn thế kỷ của Ottoman ở phía bắc sông Danube.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Suakin, Massawa và Dahlak được sáp nhập vào Ai Cập", "a0924860"], "d": ["Massawa, nơi năm 1846 đã được Sultan Abdülmecid giao cho Muhammad Ali Pasha, người cai trị Ai Cập, cùng với Suakin dưới dạng salyane (khoán nguồn thu), đến thời khedive Ismail Pasha được đưa vào tài sản của Ai Cập cùng Dahlak và Suakin, và được tổ chức theo quy chế kaymakam (phó tỉnh). Như vậy ba hải cảng này trên bờ châu Phi của Biển Đỏ, tuy về pháp lý vẫn là lãnh thổ Ottoman, về hành chính đã chuyển từ trực thuộc Triều đình Cổng Cao sang Cairo — nhập vào cùng tầng lệ thuộc với các láng giềng Ai Cập và Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Cuộc khởi nghĩa Crete bùng nổ (1866–1869)", "3679b861"], "d": ["Cuộc nổi dậy quy mô lớn bùng phát trên đảo với sự hỗ trợ công khai của Hy Lạp đã lần đầu tiên biến yêu sách enosis (sáp nhập vào Hy Lạp) của người Hy Lạp ở Crete thành vấn đề quốc tế. Cuộc chiến tranh du kích trên núi khốc liệt kéo dài ba năm khiến quân đội Ottoman chịu tổn thất nặng và gây tiếng vang lớn trong dư luận châu Âu. Cuộc khởi nghĩa chỉ lắng xuống khi Âli Pasha đến đảo năm 1868 và cho thi hành quy chế trao nhiều đặc quyền rộng rãi.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Các đội đồn trú Ottoman cuối cùng rút khỏi Belgrade và các pháo đài Serbia", "b34217db"], "d": ["Trước sức ép của các cường quốc và yêu cầu kiên trì của Hoàng thân Mihailo, Triều đình Cổng Cao chấp nhận bỏ những căn cứ quân sự cuối cùng còn giữ ở Serbia; ngày 18 tháng 4 năm 1867, lá cờ Ottoman ở pháo đài Belgrade được hạ xuống và chìa khóa được trao cho hoàng thân. Như vậy sự hiện diện quân sự thực tế của Ottoman kéo dài từ năm 1521 chấm dứt, và trở ngại lớn cuối cùng trên con đường độc lập của Serbia được dỡ bỏ. Quyền bá chủ của sultan chỉ còn thu lại thành vấn đề mang tính tượng trưng về lá cờ và cống thuế.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Trao danh hiệu khedive cho tổng đốc Ai Cập", "09e10c12"], "d": ["Nhờ cuộc vận động ráo riết và những khoản tiền đổ vào Istanbul của Ismail Pasha, thuộc thế hệ thứ ba của triều đại người Kavala, tổng đốc Ai Cập được trao danh hiệu khedive, nhấn mạnh rằng ông cao hơn các tổng đốc khác. Trong những năm đó, thể thức thừa kế cũng được đổi thành cha truyền con nối, và Ai Cập được công nhận những quyền hạn mang tính chủ quyền như vay nợ nước ngoài, ban huân chương và duy trì lãnh sự quán. Những bước này là mắt xích đầu tiên trong chuỗi đẩy nhanh sự tách rời về pháp lý của Ai Cập khỏi Ottoman.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Quy chế Crete: trao đặc quyền hành chính rộng rãi cho hòn đảo", "12052262"], "d": ["Để chấm dứt cuộc khởi nghĩa ba năm, Đại tể tướng Âli Pasha đích thân đến đảo, và theo quy chế được công bố với sự chuẩn y của sultan, người Crete được hưởng các hội đồng hành chính hỗn hợp, tòa án địa phương, việc dùng tiếng Hy Lạp trong các thủ tục chính thức và ưu đãi thuế. Sự dàn xếp này giữ được quyền thống trị của Ottoman trên đảo thêm ba mươi năm. Tuy nhiên, các đặc quyền dành cho dân Cơ Đốc giáo đã làm suy yếu vị thế của người Crete Hồi giáo và gieo mầm cho cuộc khủng hoảng 1896–1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Khai mạc Hội đồng Nhà nước (Şura-yı Devlet): thành lập tòa án hành chính tối cao của Ottoman", "70b16497"], "d": ["Theo chiếu chỉ ngày 5 tháng 3 năm 1868, Hội đồng Tối cao về Pháp quy Tư pháp được tách làm hai: công việc hành chính – lập pháp giao cho Hội đồng Nhà nước, công việc xét xử giao cho Viện Pháp quy Tư pháp (Divan-ı Ahkâm-ı Adliyye); cơ quan này được khai mạc trọng thể tại Triều đình Cổng Cao và Midhat Pasha được cử làm chủ tịch đầu tiên. Cơ quan được giao soạn dự thảo luật, giải quyết tranh chấp hành chính và xét xử công chức. Với thành phần hỗn hợp gồm cả người Hồi giáo và không Hồi giáo, đây được coi là sự vận dụng mang tính thể chế đầu tiên của tư tưởng phân quyền ở Ottoman.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Khai thông kênh đào Suez: con đường sang Ấn Độ qua Ai Cập được rút ngắn", "377ccd04"], "d": ["Công trình khởi công năm 1859 kéo dài mười năm, và con kênh dài 163 kilômét nối Địa Trung Hải với Biển Đỏ được đưa vào sử dụng trong một buổi lễ hoành tráng. Khi đường từ châu Âu sang Ấn Độ rút ngắn hàng nghìn dặm, Ai Cập bỗng trở thành điểm then chốt của thương mại thế giới. Giá trị địa chiến lược này sẽ là nguyên nhân chính khiến Anh chiếm đóng Ai Cập mười ba năm sau khi kênh khai thông; còn món nợ mà con kênh đặt lên Ai Cập sẽ đẩy chính quyền khedive đến chỗ vỡ nợ.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Thành lập Giáo hội Exarchate Bulgaria: giáo hội Bulgaria tách khỏi Phanar", "33a8272c"], "d": ["Theo sắc lệnh firman của sultan, một giáo hội Bulgaria độc lập (exarchate) tách khỏi Tòa Thượng phụ Hy Lạp được thành lập, và việc kaza nào sẽ thuộc exarchate được để cho dân chúng bỏ phiếu quyết định. Triều đình Cổng Cao thực hiện bước này nhằm phá ảnh hưởng của người Hy Lạp, nhưng kết quả lại ngược lại: giáo hội trở thành trung tâm có tổ chức của bản sắc dân tộc Bulgaria và yêu sách của Bulgaria đối với Macedonia. Như vậy nền tảng thể chế cho cuộc cạnh tranh Bulgaria – Hy Lạp – Serbia ở Balkan và các cuộc khởi nghĩa năm 1876 đã được đặt.", "ce8f108b"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Chiến dịch Najd của Midhat Pasha: tái lập quyền thống trị của Ottoman ở al-Ahsa", "7db51461"], "d": ["Lợi dụng cuộc tranh giành ngôi trong dòng họ Saud, tổng đốc Baghdad Midhat Pasha đã điều quân đến bờ tây vịnh Basra và sáp nhập vùng al-Ahsa vào tỉnh Basra với tên sanjak Najd. Abdullah ibn Faisal được bổ nhiệm làm mutasarrıf, và quyền thống trị của Ottoman được thiết lập trên giấy tờ. Chiến dịch nhằm ngăn chặn sự lan rộng ảnh hưởng của Anh ở vùng vịnh, và ngay trong năm đó dẫn đến việc Qatar cũng rơi vào sự kiểm soát của Ottoman.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Đại tể tướng Âli Pasha qua đời: thế hệ nhân sự Tanzimat chấm dứt", "1cf0141c"], "d": ["Với cái chết của Âli Pasha, người một mình gánh vác chính sách Tanzimat sau khi Fuad Pasha mất năm 1869, thế hệ những nhà ngoại giao lão luyện điều hành chính sách đối ngoại của đất nước suốt ba mươi năm đã cạn kiệt. Sự cai trị thân Nga và tùy tiện của người kế nhiệm Mahmud Nedim Pasha đã củng cố quyền cai trị cá nhân của Abdülaziz. Trong vòng năm năm sau khi Âli Pasha qua đời, tài chính vỡ nợ, Balkan nổi dậy và việc thay đổi ngôi vua trở nên không thể tránh khỏi.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Thiết lập sự kiểm soát của Ottoman tại Qatar", "3b453165"], "d": ["Theo lời mời của Sheikh Jassim ibn Thani, người đang chịu sức ép của Anh, lực lượng Ottoman đã đổ bộ lên bán đảo Qatar, và vào mùa thu năm 1871 sự kiểm soát của Ottoman được thiết lập trong vùng. Qatar được tổ chức thành một kaza thuộc sanjak Najd, và sheikh được bổ nhiệm làm kaymakam. Bước đi này là thành quả cụ thể nhất của chính sách tiến công mà Midhat Pasha theo đuổi chống Anh ở vùng vịnh; cờ Ottoman tung bay trên bán đảo cho đến năm 1913.", "823711c3"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Chiếm Sanaa: tái lập quyền lực Ottoman ở Yemen", "978e20a0"], "d": ["Khi giá trị chiến lược của Biển Đỏ tăng lên nhờ kênh đào Suez khai thông, Triều đình Cổng Cao đã điều đến Yemen đạo quân Fırka-i İhtiyatiye dưới quyền Ahmed Muhtar Pasha. Với việc chiếm được Sanaa, quyền lực nhà nước được tái lập ở nội địa Yemen, nơi trên thực tế đã mất từ hai thế kỷ trước, và vùng này được tổ chức thành tỉnh. Tuy nhiên, cuộc đấu tranh với các imam Zaydi không bao giờ chấm dứt; các cuộc khởi nghĩa năm 1891, 1898 và 1904 tạo thành mặt trận nội bộ tốn kém nhất và kéo dài nhất của Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Sanaa, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Cuộc khởi nghĩa Herzegovina bùng nổ: Vấn đề phương Đông lại bùng cháy", "571b18ec"], "d": ["Cuộc nổi dậy của nông dân Cơ Đốc giáo quanh Nevesinje, do thuế nặng và sức ép của giới thân hào ayan, chẳng bao lâu lan ra toàn Herzegovina và được tiếp sức bởi quân tình nguyện từ Serbia và Montenegro. Cuộc khởi nghĩa, dẫn đến việc Áo và Nga áp đặt cải cách, năm sau đã châm ngòi cho các cuộc nổi dậy của người Bulgaria và các lời tuyên chiến của Serbia và Montenegro. Như vậy mắt xích đầu tiên đã bị phá vỡ trong chuỗi lớn dẫn đến Chiến tranh Nga – Ottoman 1877–78 và việc mất Balkan theo Hiệp ước Berlin.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Tài chính Ottoman vỡ nợ: giảm một nửa các khoản trả nợ nước ngoài", "2cac2fa5"], "d": ["Các khoản vay liên tiếp từ năm 1854, chi phí Chiến tranh Crimea, việc xây cung điện và nạn đói ở Anatolia năm 1873–74 đã biến thâm hụt ngân sách thành một vực thẳm vượt quá năm triệu lira. Chính phủ Mahmud Nedim Pasha tuyên bố giảm một nửa các khoản trả lãi và gốc nợ trong thời hạn năm năm, trên thực tế là tuyên bố hoãn nợ. Quyết định gây phản ứng mạnh ở các sở giao dịch chứng khoán châu Âu này đã khởi động tiến trình mà sáu năm sau kết thúc bằng Sắc lệnh Muharrem và việc thành lập Cơ quan Quản lý Nợ công (Düyun-ı Umumiye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Murad V bị phế truất và Abdülhamid II lên ngôi", "cffb2271"], "d": ["Murad V, lên ngôi sau khi Abdülaziz bị phế truất, đã không thể đảm đương nhiệm vụ vì sức khỏe tinh thần bị chấn động bởi cái chết của người bác và vụ Hasan người Circassia; trong chín mươi ba ngày trị vì, ông chỉ tỉnh táo trong bảy ngày. Ông bị phế truất theo fatwa của Sheikh al-Islam, và người em Abdülhamid II được đưa lên thay. Vị sultan mới lên ngôi sau khi hứa với Midhat Pasha sẽ ban bố nền quân chủ lập hiến; một thời đại kéo dài ba mươi ba năm bắt đầu.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Hội nghị Tersane (Xưởng hải quân): các cường quốc áp đặt cải cách ở Balkan", "b5006a2c"], "d": ["Hội nghị do các cường quốc triệu tập tại Istanbul để giải quyết khủng hoảng Balkan đã đòi chia Bulgaria thành hai tỉnh tự trị và thực hiện cải cách dưới sự giám sát quốc tế ở Bosnia-Herzegovina. Ngay ngày khai mạc hội nghị, Triều đình Cổng Cao dùng loạt đại bác loan báo việc công bố Hiến pháp (Kanun-ı Esasi), tìm cách đáp lại sự áp đặt bằng cải cách hiến pháp. Các đại biểu coi đó là kế trì hoãn và giải tán ngày 20 tháng 1 năm 1877; bốn tháng sau, Nga tuyên chiến.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Hạ viện (Meclis-i Mebusan) đầu tiên khai mạc tại Dolmabahçe", "429bb279"], "d": ["115 nghị viên được bầu theo Hiến pháp đã nhóm họp lần đầu ngày 19 tháng 3 năm 1877 trong buổi lễ tại Đại sảnh Nghi lễ của cung Dolmabahçe; như vậy thời kỳ nghị viện đại diện trong lịch sử Ottoman bắt đầu. Các nghị viên Hồi giáo và không Hồi giáo chất vấn chính phủ gay gắt, tranh luận về việc điều hành chiến tranh và trách nhiệm của các bộ trưởng. Sự đối lập táo bạo này sẽ là nguyên nhân chính rút ngắn tuổi thọ của nghị viện.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Cuộc phòng thủ Plevna bắt đầu: sự kháng cự của Gazi Osman Pasha", "0e04a878"], "d": ["Trong Chiến tranh Nga – Ottoman 1877–78, Osman Pasha hành quân từ Vidin đến Plevna nhằm chặn đường đến Istanbul của quân đội Nga đã vượt sông Danube; ông củng cố thị trấn bằng các đồn lũy và chiến hào, mở đầu cuộc phòng thủ huyền thoại kéo dài năm tháng. Ba cuộc tấn công lớn liên tiếp của Nga – Romania bị đẩy lui với tổn thất nặng, và quân đội do chính Sa hoàng Alexander II chỉ đạo buộc phải chuyển sang vây hãm. Plevna đi vào lịch sử như thành tích phòng thủ rực rỡ nhất của quân đội Ottoman trong thế kỷ 19.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Plevna thất thủ: mặt trận sông Danube sụp đổ", "185e7602"], "d": ["Hết lương thực sau năm tháng bị vây, Osman Pasha tiến hành cuộc đột phá vòng vây qua sông Vit; khi ông bị thương và bị bắt, thành phố đầu hàng. Các chỉ huy Nga trả lại thanh gươm để chào vị pasha mà họ bắt làm tù binh, và Osman Pasha được trao danh hiệu “Gazi”. Plevna thất thủ đã mở đường cho quân đội Nga; trong vòng hai tháng, Sofia, Plovdiv và Edirne thất thủ, và quân tiên phong Nga tiến đến Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Quân Nga chiếm đóng Sofia", "ef369d22"], "d": ["Quân đội Nga vượt dãy Balkan sau khi Plevna thất thủ đã tiến vào Sofia không được phòng thủ. Thành phố không bao giờ trở lại quyền cai quản của Ottoman nữa; cuối năm 1878 nó thuộc Công quốc Bulgaria tự trị, và từ năm 1879 trên thực tế là thủ đô của công quốc này. Trên bản đồ, từ thời điểm này Sofia rời quyền cai quản trực tiếp của Ottoman, chuyển sang chiếm đóng tạm thời của Nga rồi sau đó là chính quyền tự trị Bulgaria.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Hiệp định đình chiến Edirne: tiếng súng im trong Chiến tranh Nga – Ottoman 1877–78", "1f899180"], "d": ["Trước việc Sofia, Plovdiv và Edirne nối tiếp nhau thất thủ và quân đội Nga áp sát bờ biển Marmara, Triều đình Cổng Cao buộc phải xin đình chiến. Hiệp định ngừng bắn ký tại Edirne buộc Ottoman chấp nhận các điều kiện hòa bình sơ bộ như quyền tự trị cho Bulgaria, độc lập cho Montenegro, Serbia và Romania cùng khoản bồi thường chiến phí nặng nề. Một tháng sau, những điều kiện này được chuyển thành văn bản hiệp ước tại San Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Abdülhamid II đình hoạt động Hạ viện vô thời hạn", "e770b540"], "d": ["Trước sự chỉ trích gay gắt của các nghị viên quy trách nhiệm cho chính phủ và hoàng cung về kết cục thảm họa của cuộc chiến, Abdülhamid II, dựa vào quyền hạn mà Hiến pháp trao cho mình, đã đình hoạt động nghị viện vô thời hạn. Nghị viện Ottoman đầu tiên, hoạt động khoảng mười một tháng, như vậy bị đóng cửa, và thời kỳ chuyên chế kéo dài ba mươi năm bắt đầu. Nghị viện chỉ có thể nhóm họp lại sau cuộc Cách mạng năm 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Hiệp ước San Stefano: đề án Đại Bulgaria", "2c7cc611"], "d": ["Hiệp ước San Stefano chấm dứt Chiến tranh Nga – Ottoman 1877–78 đã lập ra một Bulgaria tự trị khổng lồ trải đến biển Aegea và bao gồm cả Macedonia; công nhận độc lập của Serbia, Montenegro và Romania; nhượng Kars, Ardahan, Batumi và Doğubayazıt cho Nga, đồng thời áp đặt khoản bồi thường chiến phí không thể trả nổi. Văn bản đưa Nga xuống Địa Trung Hải này vấp phải phản ứng dữ dội của Anh và Áo. Chưa kịp thi hành, trong vòng bốn tháng nó đã bị sửa đổi tại Hội nghị Berlin; dù vậy nó vẫn là văn kiện tuyên bố hồi kết của Rumelia thuộc Ottoman.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Áo-Hung chiếm đóng Bosnia-Herzegovina và Novi Pazar", "e5f901df"], "d": ["Dựa trên quyền hạn do Hiệp ước Berlin trao, quân đội Áo-Hung tiến vào Bosnia; dù chính phủ Ottoman chấp nhận không kháng cự, dân địa phương Hồi giáo và Chính thống giáo ở Sarajevo và Mostar đã cầm vũ khí và kháng cự quyết liệt suốt ba tháng. Cuộc chiếm đóng chỉ hoàn tất ngày 20 tháng 10 năm 1878. Chủ quyền pháp lý của sultan còn tồn tại trên giấy tờ đến năm 1908, nhưng xứ Bosnia thuộc Ottoman suốt bốn thế kỷ trên thực tế đã mất, và một làn sóng di cư lớn của người Hồi giáo bắt đầu. Các điểm định cư khác bị mất cùng ngày: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Sắc lệnh Muharrem và việc thành lập Cơ quan Quản lý Nợ công (Düyun-ı Umumiye)", "02b7cc03"], "d": ["Các cuộc đàm phán với đại diện các nước chủ nợ sau vụ vỡ nợ năm 1875 đã kết thúc bằng sắc lệnh ngày 28 Muharram 1299 (20 tháng 12 năm 1881): nợ gốc được giảm hơn một nửa, đổi lại các khoản thu béo bở nhất như thuế muối, thuốc lá, tơ lụa, tem và thuế cá được chuyển thẳng cho Cơ quan Quản lý Nợ công do các chủ nợ điều hành. Sử dụng hàng nghìn viên chức, cơ quan này trở thành một bộ máy tài chính riêng ngay trong lòng nhà nước. Đây được coi là thời điểm nền độc lập tài chính của Ottoman trên thực tế chấm dứt.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — hải cảng duy nhất không rơi vào tay Mahdi", "5a37b198"], "d": ["Từ tháng 2 năm 1884, trong khi toàn bộ các vùng miền đông Sudan ngoài Suakin rơi vào quyền thống trị của Muhammad Ahmad al-Mahdi, hải cảng vẫn trụ được nhờ sự bảo vệ quân sự của một lực lượng Anh gồm ba tiểu đoàn dưới quyền tướng Graham. Đây là khởi đầu của thời kỳ tình trạng thực tế và pháp lý tách rời nhau: tuy bờ biển trên thực tế nằm dưới sự kiểm soát quân sự của Anh, năm 1885 mối liên hệ hành chính của nó được lấy khỏi Ai Cập và gắn trực tiếp vào tỉnh Yemen, tức Triều đình Cổng Cao — trật tự này kéo dài cho đến khi chấm dứt năm 1888 với việc Pháp chiếm đóng Zeila.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Midhat Pasha bị giết trong ngục Taif", "f4562261"], "d": ["Midhat Pasha, kiến trúc sư của Hiến pháp và là nhân vật biểu tượng của Thời kỳ Lập hiến thứ nhất, bị tòa án Yıldız kết tội trong vụ cái chết của Abdülaziz, được giảm án tử hình thành lưu đày và đưa đến Taif. Theo ghi chép của TDV, ông bị bóp cổ chết trong phòng giam đêm 7–8 tháng 5 năm 1884, còn nguyên nhân chính thức được công bố là bệnh nhọt than (şirpençe). Cái chết của ông trở thành biểu tượng cho việc thanh trừng phe đối lập lập hiến dưới thời Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Nhượng quyền đường sắt Haydarpaşa – Ankara cho người Đức", "5705b163"], "d": ["Theo chiếu chỉ của sultan, quyền xây dựng và khai thác tuyến Haydarpaşa – Ankara được trao cho chủ ngân hàng Alfred von Kaulla, đại diện Deutsche Bank, và Công ty Đường sắt Anatolia được thành lập. Nhượng quyền này là bước ngoặt phá vỡ thế độc quyền Anh – Pháp trong giao thông và chính sách đối ngoại của Ottoman, đồng thời đặt nền ảnh hưởng của Đức. Cùng với nhượng quyền tuyến Baghdad trao cho chính công ty này mười một năm sau, giấc mơ “Berlin – Baghdad” ra đời và trở thành một trong những trục chính của cuộc cạnh tranh giữa các cường quốc trước Thế chiến thứ nhất.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Thành lập Hội Thống nhất Ottoman (İttihad-ı Osmani) ở Istanbul", "b7187939"], "d": ["Bốn sinh viên Trường Quân y đã lập Hội Thống nhất Ottoman làm tổ chức bí mật chống chế độ chuyên chế; chẳng bao lâu tổ chức này biến thành Ủy ban Liên hiệp và Tiến bộ, nơi tập hợp dưới mái nhà chung mọi phần tử đối lập của phong trào Thanh niên Thổ. Tổ chức theo mô hình chi bộ đã hợp nhất với những người lưu vong ở châu Âu và các sĩ quan ở Salonika. Chính đội ngũ xuất thân từ chi bộ sinh viên nhỏ bé này đã buộc ban bố Thời kỳ Lập hiến thứ hai năm 1908 và độc quyền cai trị đất nước sau năm 1913.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Vụ đột kích Ngân hàng Ottoman: hành động của các chiến binh Dashnak ở Galata", "08b3095f"], "d": ["Một nhóm vũ trang của tổ chức Armenia Dashnaktsutyun đã đột kích trụ sở chính Ngân hàng Ottoman ở Galata, bắt con tin và đe dọa cho nổ tòa nhà nhằm thu hút sự chú ý của châu Âu đến vấn đề Armenia. Nhờ các đại sứ can thiệp, cuộc khủng hoảng kết thúc với việc đổi lại các kẻ hành động được đưa ra khỏi nước trên một con tàu. Những sự kiện đẫm máu ở Istanbul trong những ngày sau vụ đột kích đã đóng vai trò quyết định trong việc biến vấn đề Armenia thành đòn bẩy can thiệp quốc tế.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Chiến tranh Ottoman – Hy Lạp 1897 bùng nổ: mặt trận Thessaly", "33e490ab"], "d": ["Trước việc Hy Lạp đổ hải quân và binh lính lên Crete cùng các cuộc tấn công của các toán vũ trang ở biên giới Rumelia, Đế quốc Ottoman tuyên chiến. Quân đội Ottoman, được phái đoàn cải cách Đức huấn luyện, tiến nhanh ở Thessaly và trong vòng một tháng chiếm Larissa, Farsala và Domokos; quân đội Hy Lạp tan rã. Do các cường quốc can thiệp, lãnh thổ giành được bị trả lại, nhưng cuộc chiến vẫn là chiến thắng quân sự dứt khoát duy nhất dưới thời Abdülhamid II và không ngăn được việc mất Crete trên thực tế.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Nhượng quyền tuyến Konya – Baghdad cho người Đức", "fd8b6cbd"], "d": ["Sau chuyến thăm Istanbul và Damascus năm 1898 của Hoàng đế Wilhelm II, Công ty Đường sắt Anatolia được trao nhượng quyền sơ bộ cho tuyến từ Konya đến Baghdad và Basra. Dự án đường sắt Baghdad đối với Ottoman có nghĩa là củng cố sự kiểm soát trung ương đối với các tỉnh Ả Rập, còn đối với Đức là vươn đến vịnh Basra. Bị Anh và Nga phản đối kịch liệt, dự án trở thành một trong những hồ sơ gây tranh cãi nhất của cuộc cạnh tranh đế quốc dẫn đến Thế chiến thứ nhất.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Khởi công đường sắt Hejaz tại Damascus", "62f58f68"], "d": ["Tuyến đường mà Abdülhamid II ra lệnh xây theo chiếu chỉ ngày 2 tháng 5 năm 1900 đã được khởi công bằng buổi lễ chính thức tại Damascus ngày 1 tháng 9 năm 1900. Được thực hiện hoàn toàn bằng tiền quyên góp từ thế giới Hồi giáo và công sức của các kỹ sư – binh sĩ Ottoman, dự án rút ngắn hành trình Damascus – Medina của người hành hương từ bốn mươi ngày xuống năm ngày. Đây vừa là công trình uy tín củng cố quyền uy tinh thần của chức caliph, vừa là khoản đầu tư chiến lược tăng cường kiểm soát quân sự đối với Hejaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Chương trình Mürzsteg: giám sát quốc tế cải cách ở Macedonia", "4c7464da"], "d": ["Sau cuộc khởi nghĩa Ilinden, hoàng đế Nga và hoàng đế Áo gặp nhau tại Mürzsteg và soạn một gói cải cách mới cho Macedonia. Chương trình dự kiến đặt hai ủy viên dân sự nước ngoài bên cạnh tổng thanh tra Ottoman, cho các sĩ quan châu Âu tổ chức lại hiến binh và thay đổi ranh giới hành chính theo nguyên tắc dân tộc. Triều đình Cổng Cao kháng cự với lý do quyền chủ quyền bị xâm phạm, nhưng trước sức ép chung buộc phải chấp nhận; chương trình trở thành một trong những nhân tố chính thúc đẩy việc tổ chức của phái Liên hiệp trong giới sĩ quan trẻ.", "b56ab15c"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Sanaa rơi vào tay Imam Yahya", "e7f876cb"], "d": ["Cuộc nổi dậy do imam Zaydi Yahya Hamid al-Din phát động năm 1904 kết thúc với việc Sanaa thất thủ sau cuộc vây hãm vào tháng 4 năm 1905; thành phố thoát khỏi quyền cai quản của Ottoman, và trong suốt thời gian bị vây, nạn đói và dịch bệnh bùng phát. Địa hình núi non của Yemen, đường tiếp tế dài và tính chính danh tại chỗ của chế độ imam Zaydi khiến quyền thống trị của Ottoman ở đây mong manh ngay từ khi thiết lập. Năm tháng sau, thành phố được lấy lại với tổn thất nặng nề, nhưng vấn đề Yemen mãi đến năm 1918 mới khép lại.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Vụ ám sát Yıldız: tấn công bằng bom nhằm vào Abdülhamid II", "1ee2e1a6"], "d": ["Tổ chức Dashnaktsutyun tiến hành ám sát bằng cách cho nổ một chiếc xe ngựa landau gài bom hẹn giờ nhằm vào xe của sultan khi ông rời lễ cầu nguyện thứ Sáu có nghi thức triều đình; việc Abdülhamid trò chuyện với Sheikh al-Islam nên chậm vài phút đã cứu mạng ông. Vụ nổ làm hai mươi sáu người chết và hơn năm mươi người bị thương. Sự kiện càng làm trầm trọng thêm nỗi ám ảnh an ninh của sultan và nền cai trị chuyên chế dựa trên mạng lưới mật thám; nó cũng trở thành đề tài bài thơ “Một khoảnh khắc chậm trễ” của Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Thu hồi Sanaa: dẹp cuộc nổi dậy của Imam Yahya", "dec3b8f9"], "d": ["Cuộc nổi dậy bắt đầu năm 1904 dưới sự lãnh đạo của imam Zaydi Yahya kết thúc với việc Sanaa thất thủ vào tháng 4 năm 1905, và nạn đói cùng dịch bệnh bùng phát trong thành phố. Các đạo quân tăng viện dưới quyền Ali Rıza Pasha và Ahmed Feyzi Pasha, bằng chiến dịch tiến hành từ ngày 15 tháng 7 đến ngày 1 tháng 9 năm 1905 với sự hỗ trợ của lực lượng ở Taiz, đã lấy lại thành phố với tổn thất nặng nề và dẹp tan cuộc nổi dậy. Chiến dịch Yemen gây cho quân đội Ottoman hàng chục nghìn tổn thất và gánh nặng tài chính khổng lồ; trong giới sĩ quan ở Rumelia, nỗi sợ “bị đày đi Yemen” là một trong những bất mãn hàng đầu nuôi dưỡng việc tổ chức của phái Liên hiệp.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Hạ viện đầu tiên của Thời kỳ Lập hiến thứ hai nhóm họp", "e7fd2716"], "d": ["Nghị viện hình thành qua cuộc bầu cử hai cấp tổ chức sau ba mươi năm gián đoạn đã khai mạc ngày 17 tháng 12 năm 1908 bằng diễn văn của sultan, và Ahmed Rıza Bey, lãnh tụ phong trào Thanh niên Thổ, được bầu làm chủ tịch. Nghị viện gồm các nghị viên Thổ, Ả Rập, Albania, Hy Lạp, Armenia và Do Thái là thử nghiệm lớn cuối cùng của lý tưởng chủ nghĩa Ottoman. Tuy nhiên, việc Bulgaria tuyên bố độc lập, Bosnia bị sáp nhập và Crete tuyên bố gia nhập Hy Lạp đã phủ bóng lên niềm lạc quan này trước cả khi nghị viện khai mạc.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Đạo quân Hành động và việc phế truất Abdülhamid II: Mehmed V Reşad lên ngôi", "6a65a704"], "d": ["Đạo quân Hành động khởi hành từ Salonika sau Sự biến ngày 31 tháng 3, đã tiến vào Istanbul theo bốn cánh trong đêm 22–23 tháng 4, và ngày 24 tháng 4 cung Yıldız đầu hàng. Ngày 27 tháng 4, Quốc hội Toàn thể quyết định phế truất Abdülhamid II; vị sultan bị đưa đến Salonika, và người em Mehmed V Reşad được đưa lên ngôi. Nền cai trị cá nhân ba mươi ba năm như vậy chấm dứt, nhưng được thay bằng một thời kỳ mới trong đó sultan chỉ còn là biểu tượng, còn Ủy ban Liên hiệp và Tiến bộ cai trị với sự hậu thuẫn của quân đội.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Cuộc nổi dậy Albania: kháng chiến vũ trang ở Kosovo và Shkodra", "93ed30c6"], "d": ["Chính sách thuế tập quyền, chiến dịch thu vũ khí và cuộc tranh cãi về bảng chữ cái Latinh của chính phủ phái Liên hiệp đã khiến các bộ tộc Albania, vốn trước đó được coi là thuộc số những thành phần trung thành nhất với nhà nước, nổi dậy. Quân đội dưới quyền Mahmud Şevket Pasha tuy đàn áp khởi nghĩa một cách quyết liệt, nhưng tình trạng bất an lại bùng lên vào các năm 1911 và 1912. Những cuộc nổi dậy này vừa làm hao mòn quân đội Ottoman ngay trước Chiến tranh Balkan, vừa đẩy nhanh sự ra đời của phong trào dân tộc Albania.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Hiệp ước Ouchy: nhượng Tripoli (Libya) và Benghazi cho Ý", "4ffa1fd2"], "d": ["Trước việc các nước Balkan chuẩn bị chiến tranh, Triều đình Cổng Cao không dám chấp nhận đụng độ trên hai mặt trận nên đã ký hòa ước bí mật với Ý tại thị trấn Ouchy của Thụy Sĩ và từ bỏ Tripoli và Benghazi. Đế quốc Ottoman như vậy mất mảnh đất cuối cùng ở châu Phi; bù lại, việc trả lại Rhodes và quần đảo Mười Hai Đảo do Ý chiếm đóng được hứa hẹn, nhưng lời hứa này không bao giờ được thực hiện. Khi hiệp ước được ký, Chiến tranh Balkan đã bùng nổ từ lâu. Với sự kiện này, Murzuk (Fezzan), Ghat, Sabha, Ubari, Traghan, Zawila và al-Qatrun (sanjak Fezzan thuộc tỉnh Tripoli) chuyển sang quyền cai quản của Ý.", "5896634d"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Đại tể tướng Mahmud Şevket Pasha bị ám sát tại Istanbul", "68e60e63"], "d": ["Mahmud Şevket Pasha, được đưa lên chức Đại tể tướng sau cuộc đột kích Triều đình Cổng Cao, bị bắn chết trong xe gần Çarşıkapı khi đang đến Bộ Chiến tranh. Ủy ban Liên hiệp và Tiến bộ đổ vụ ám sát cho phe đối lập, mở một làn sóng bắt bớ và hành quyết rộng rãi, và Đảng Tự do và Hòa hợp trên thực tế bị thanh trừng. Với sự kiện này, nền độc tài một đảng của phái Liên hiệp dựa trên bộ ba Enver – Talat – Cemal được thiết lập dứt khoát.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Chiến tranh Balkan lần thứ hai bùng nổ: cuộc tranh giành chia phần giữa các đồng minh", "48d088a2"], "d": ["Các đồng minh Balkan không chia nổi lãnh thổ lấy từ Ottoman theo Hiệp ước London đã quay sang đánh nhau; chiến tranh lần thứ hai bắt đầu khi Bulgaria tấn công các vị trí của Serbia và Hy Lạp. Khi Romania và Montenegro cũng tham chiến chống Bulgaria, quân đội Bulgaria sụp đổ. Đế quốc Ottoman tận dụng cơ hội này, vượt qua đường Midye – Enez do Hiệp ước London vạch ra và lấy lại miền Đông Thrace cùng với Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Hiệp ước Istanbul: hòa bình với Bulgaria và xác nhận Edirne", "c8c18b2d"], "d": ["Hiệp ước ký giữa Đế quốc Ottoman và Bulgaria sau Chiến tranh Balkan lần thứ hai đã lấy sông Maritsa làm biên giới và xác nhận về mặt pháp lý rằng Edirne, Kırklareli, Didymoteicho và miền Đông Thrace vẫn thuộc Ottoman. Alexandroupoli (Dedeağaç) được để cho Bulgaria (còn Kavala, sau khi bị Bulgaria chiếm đóng mùa thu năm 1912, đã chuyển sang Hy Lạp vào tháng 7 năm 1913 và được xác nhận thuộc Hy Lạp theo Hiệp ước Bucharest ngày 10 tháng 8 năm 1913); việc trao đổi dân cư giữa hai nước và quyền của người Hồi giáo ở Bulgaria được quy định. Văn bản này là bảo đảm cho mảnh đất duy nhất có thể lấy lại được sau thảm họa Balkan. Nơi khác được tính cùng ngày này: Komotini.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Hiệp ước Athens: hòa bình với Hy Lạp và chuyển giao Salonika – Ioannina", "8e94def7"], "d": ["Hiệp ước ký giữa Đế quốc Ottoman và Hy Lạp chính thức công nhận việc Salonika, Ioannina và miền Nam Macedonia, mất trong Chiến tranh Balkan, chuyển sang Hy Lạp, và Ottoman từ bỏ các quyền đối với Crete. Quyền tôn giáo và quyền sở hữu của người Hồi giáo còn ở lại Hy Lạp, quy chế các waqf và việc bổ nhiệm các mufti được quy định chi tiết. Quy chế của các đảo Aegea thì bị bỏ ngỏ và còn là nguồn căng thẳng thường trực giữa hai nước.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Ký hiệp ước liên minh bí mật Ottoman – Đức tại Istanbul", "0472efb3"], "d": ["Ngay khi chiến tranh bùng nổ ở châu Âu, một hiệp ước liên minh bí mật giữa Đế quốc Ottoman và Đức được ký tại dinh thự của Đại tể tướng Said Halim Pasha; văn bản quy định nếu Nga tham chiến chống Đức thì Ottoman cũng đứng về phía Đức. Hiệp ước bị giấu cả nội các, chỉ có bốn người biết. Ba tháng sau, với cuộc đột kích Biển Đen, Đế quốc Ottoman trên thực tế bị lôi vào chiến tranh, và số phận của đế quốc sẽ bị gắn chặt với văn kiện này.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Đơn phương bãi bỏ các ưu đãi cho người nước ngoài (capitulations)", "ec773d18"], "d": ["Vào lúc châu Âu đang bận tâm với chiến tranh, chính phủ Ottoman tuyên bố đơn phương bãi bỏ từ ngày 1 tháng 10 năm 1914 các capitulations, vốn dành cho người nước ngoài các đặc quyền tư pháp, tài chính và hải quan. Việc chấm dứt chế độ đặc quyền bốn thế kỷ này được đón nhận trong nước với niềm phấn khích lớn về độc lập, và Istanbul tổ chức ăn mừng. Mọi nước, kể cả đồng minh Đức, đều phản đối quyết định; các capitulations mãi đến Lausanne năm 1923 mới đi vào lịch sử một cách dứt khoát.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Cuộc đột kích Biển Đen: hạm đội Ottoman pháo kích các cảng Nga", "8ad4ef61"], "d": ["Goeben và Breslau (Yavuz và Midilli), thoát khỏi Đức và gia nhập hải quân Ottoman như thể “đã được mua”, đã ra Biển Đen dưới quyền chỉ huy của Đô đốc Souchon, nã pháo vào các cảng Nga và đánh chìm tàu. Mệnh lệnh do Enver Pasha đưa ra mà giấu nội các đã chấm dứt trên thực tế thế trung lập. Trong vòng một tuần, Nga, Anh và Pháp tuyên chiến, và Đế quốc Ottoman bước vào Thế chiến thứ nhất không thể quay lại.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Lực lượng Anh – Ấn chiếm Faw — mở mặt trận Iraq", "08663813"], "d": ["Sáng ngày hôm sau ngày các nước Entente tuyên chiến với Đế quốc Ottoman, lữ đoàn Anh – Ấn đang chờ ở Bahrain đã đổ bộ lên Faw ở cửa sông Shatt al-Arab. Đơn vị Ottoman nhỏ trong pháo đài Faw đổ nát rút lui dưới hỏa lực của tàu chiến, và trạm đường dây điện báo đi Ấn Độ rơi vào tay người Anh. Mặt trận Iraq được mở ra như vậy.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Tuyên bố Đại thánh chiến: đọc fatwa jihad tại thánh đường Fatih", "2a6174e8"], "d": ["Năm fatwa do Sheikh al-Islam Ürgüplü Hayri Efendi ban ra được đọc tại thánh đường Fatih nhân danh sultan kiêm caliph, kêu gọi toàn thể người Hồi giáo thánh chiến chống các nước phe Hiệp ước (Entente). Nước đi mà Đức đặt nhiều kỳ vọng này nhằm kích động người Hồi giáo ở các thuộc địa Anh và Pháp nổi dậy. Cuộc tổng khởi nghĩa mong đợi đã không xảy ra; ngược lại, hai năm sau, việc Sharif Hussein, emir Mecca, nổi dậy với sự hỗ trợ của Anh đã cho thấy một cách cay đắng giới hạn ảnh hưởng chính trị của chức caliph.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Qurna đầu hàng quân Anh", "621d36b0"], "d": ["Lực lượng của tổng đốc Basra Subhi Bey, rút về Qurna nơi sông Tigris và sông Euphrates hợp lưu sau khi Basra thất thủ, đã đầu hàng vào sáng ngày 9 tháng 12 năm 1914 sau các trận giao tranh ngày 4–8 tháng 12.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Chiến dịch Sarıkamış: thảm họa trên mặt trận Kavkaz", "5cbde7f0"], "d": ["Nhằm lấy lại Kars, Ardahan và Batumi bị mất năm 1878 và kích động người Thổ ở Kavkaz nổi dậy, Enver Pasha đẩy Tập đoàn quân III vào một cuộc cơ động giữa mùa đông qua dãy núi Allahuekber để bao vây lực lượng Nga. Vì quân trang mùa đông thiếu thốn, tiếp tế cạn kiệt và bão tuyết ở nhiệt độ xuống tới âm ba mươi độ, quân đội tan rã trước cả khi giao chiến; hàng chục nghìn binh sĩ chết cóng. Chiến dịch trở thành một trong những thảm họa nặng nề nhất của Ottoman trong chiến tranh và khiến mặt trận phía đông bỏ ngỏ suốt hai năm.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Chiến dịch Kênh đào lần thứ nhất: tấn công Suez qua sa mạc Sinai", "02dd72f5"], "d": ["Cemal Pasha, tư lệnh Tập đoàn quân IV, đã tổ chức cuộc tấn công vượt sa mạc Sinai nhằm giải phóng Ai Cập khỏi sự chiếm đóng của Anh và phong tỏa giao thông trên kênh đào Suez. Các đơn vị Ottoman đến được bờ đông kênh đào và một phần vượt được sang bờ bên kia, nhưng trước ưu thế của Anh và việc cuộc nổi dậy của dân Ai Cập như mong đợi không xảy ra, họ phải rút lui. Chiến dịch không đạt mục tiêu, song đã tạo tác động chiến lược gián tiếp bằng việc buộc Anh phải duy trì lực lượng lớn ở Ai Cập.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Ban hành Luật Di chuyển và Tái định cư (Tehcir)", "2f2bc22c"], "d": ["Sau cuộc nổi dậy ở Van và đà tiến của Nga, chính phủ ban hành một đạo luật tạm thời cho phép các tư lệnh quân đội di chuyển đến vùng khác những cộng đồng dân cư ở hậu phương bị đánh giá là phá hoại an ninh, và sultan phê chuẩn ngày 27 tháng 5 năm 1915. Kết quả việc thi hành là phần lớn dân Armenia ở các tỉnh phía đông và phía nam Anatolia bị áp giải về hướng Syria và Mosul; trong quá trình áp giải, do bệnh tật, đói khát và các cuộc tấn công, đã xảy ra tổn thất nhân mạng cực kỳ lớn. Quyết định này vẫn là vấn đề nặng nề nhất của những năm cuối Ottoman và đến nay vẫn gây tranh cãi nhất.", "e8af8dee"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Abdülhamid II qua đời tại cung Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, bị phế truất năm 1909, trước đưa đến Salonika, rồi khi thành phố bị mất trong Chiến tranh Balkan thì được đưa về Istanbul và bị quản thúc tại cung Beylerbeyi, đã qua đời. Trong suốt ba mươi ba năm trị vì, ông cố giữ đất nước khỏi chiến tranh để tranh thủ thời gian, nhưng cũng được nhắc đến cùng nền cai trị chuyên chế. Linh cữu ông được an táng trong lăng Mahmud I trên đại lộ Divanyolu với đám đông đông đảo; cái chết của ông trùng vào một năm chiến tranh khi trật tự do ông dựng nên đã bị xóa bỏ từ lâu.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Hiệp ước Brest-Litovsk: lấy lại Kars, Ardahan và Batumi", "da82636f"], "d": ["Hiệp ước ký giữa nước Nga, vốn rút khỏi chiến tranh sau cuộc cách mạng Bolshevik, và các nước Liên minh Trung tâm đã đóng mặt trận phía đông và trả cho Đế quốc Ottoman Kars, Ardahan và Batumi (Ba tỉnh Elviye-i Selase) đã mất theo Hiệp ước Berlin năm 1878. Đây là lần được thêm lãnh thổ duy nhất sau bốn mươi năm trong lịch sử Ottoman. Tuy nhiên, sau Hiệp định đình chiến Mudros, vùng này lại bị mất, và giải pháp dứt khoát phải đến với Hiệp ước Kars năm 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Mehmed V Reşad qua đời và Mehmed VI Vahideddin lên ngôi", "d302ba07"], "d": ["Mehmed V Reşad, người có chín năm trị vì trải qua các cuộc chiến Tripoli, Balkan và Thế chiến, qua đời vào giai đoạn then chốt nhất của chiến tranh, và người em Vahideddin lên ngôi với hiệu Mehmed VI. Vị sultan mới tìm cách thoát khỏi sự giám hộ của đội ngũ phái Liên hiệp; bốn tháng sau, khi hiệp định đình chiến được ký, ông sẽ phải điều hành việc giải thể đế quốc. Ông là sultan thứ ba mươi sáu và cuối cùng của triều đại Ottoman.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Hạm đội Entente đến trước Istanbul và thành phố bị chiếm đóng trên thực tế", "d10cb14d"], "d": ["Sau Hiệp định đình chiến Mudros, hạm đội đồng minh gồm hơn sáu mươi tàu của Anh, Pháp, Ý và Hy Lạp thả neo trước Dolmabahçe, và Istanbul trên thực tế bị chiếm đóng. Lần đầu tiên sau bốn trăm sáu mươi lăm năm, kinh đô rơi vào sự kiểm soát của binh lính nước ngoài. Câu “Họ đến thế nào thì sẽ đi thế ấy”, tương truyền do Mustafa Kemal Pasha nói ngày hôm đó khi xuống Haydarpaşa và trông thấy cảnh tượng, sẽ trở thành một trong những câu nói biểu tượng của cuộc Đấu tranh Dân tộc.", "30db4974"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Đại hội Erzurum: quyết định kháng chiến dân tộc của các tỉnh phía đông", "41ef0457"], "d": ["Đại hội do Hội Bảo vệ Quyền lợi Đông Anatolia triệu tập, sau khi bị hoãn vì sức ép của Anh, đã khai mạc với năm mươi sáu đại biểu, và Mustafa Kemal Pasha, khi đó đã từ chức khỏi quân đội, được bầu làm chủ tịch. Đại hội tuyên bố rằng trong phạm vi biên giới dân tộc, tổ quốc là một khối thống nhất, chế độ ủy trị và bảo hộ không thể được chấp nhận, và nếu chính phủ tan rã thì dân tộc sẽ tự nắm lấy vận mệnh của mình. Sáu tháng sau, những quyết nghị này sẽ trở thành hạt nhân của văn bản Hiệp ước Dân tộc (Misak-ı Milli).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Đại hội Sivas: phong trào kháng chiến dân tộc hợp nhất dưới một mái nhà", "0e9ad36b"], "d": ["Đại hội, bắt đầu làm việc ngày 4 tháng 9 năm 1919 tại trường trung học Sivas, đã hợp nhất các hội bảo vệ quyền lợi trên khắp đất nước dưới tên Hội Bảo vệ Quyền lợi Anatolia và Rumelia và bầu ra Ủy ban Đại diện. Đề nghị ủy trị của Mỹ bị bác bỏ sau những cuộc tranh luận dài. Với bản tuyên cáo công bố ngày 11 tháng 9, cuộc Đấu tranh Dân tộc trở thành một phong trào chính trị hợp pháp có một trung tâm duy nhất, và cuộc đấu quyền lực công khai với chính phủ Istanbul bắt đầu.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Nghị định thư Amasya: cuộc hội đàm giữa chính phủ Istanbul và Ủy ban Đại diện", "40e6a6ab"], "d": ["Sau khi Damat Ferid đổ và chính phủ Ali Rıza Pasha được thành lập, Bộ trưởng Hải quân Salih Pasha được cử đến Amasya để hội đàm với Ủy ban Đại diện. Theo các nghị định thư đạt được, chính phủ Istanbul trên thực tế công nhận sự tồn tại của phong trào Anatolia; hai bên chấp nhận việc Hạ viện nhóm họp, bầu cử tự do và bảo vệ biên giới dân tộc. Đây là thắng lợi chính trị chính thức đầu tiên mà cuộc Đấu tranh Dân tộc giành được trước Istanbul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Nghị viện Ottoman cuối cùng thông qua Hiệp ước Dân tộc (Misak-ı Milli)", "6322865e"], "d": ["Văn bản Lời thề Dân tộc, được 121 nghị viên Hạ viện Ottoman cuối cùng ký, đặt ra các điều kiện: sự toàn vẹn không thể chia cắt của lãnh thổ nằm trong đường ranh Mudros và có đa số dân Thổ Hồi giáo, trưng cầu dân ý ở các tỉnh Ả Rập và Tây Thrace, bãi bỏ capitulations, và độc lập hoàn toàn về chính trị – tài chính. Văn bản được nhất trí thông qua ngày 17 tháng 2 năm 1920 và công bố cho thế giới. Bản tuyên ngôn này vừa là cương lĩnh chính trị của cuộc Đấu tranh Dân tộc vừa là bản đồ các đường biên giới sẽ được bảo vệ tại Lausanne; nó trở thành nguyên nhân trực tiếp khiến các nước Entente chính thức chiếm đóng Istanbul ngày 16 tháng 3.", "576d2af5"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Hiệp ước Gyumri: hiệp ước quốc tế đầu tiên của chính phủ Đại Quốc hội Thổ Nhĩ Kỳ", "9232c690"], "d": ["Khi đạo quân mặt trận phía đông dưới quyền Kâzım Karabekir lấy lại Sarıkamış và Kars, Armenia xin giảng hòa, và theo hiệp ước ký tại Gyumri, nước này chấp nhận không công nhận Hiệp ước Sèvres và từ bỏ yêu sách lãnh thổ ở phía đông. Hiệp ước đầu tiên do chính phủ Ankara ký trở thành văn kiện quốc tế đầu tiên bác bỏ Sèvres trên thực tế và mở đường cho việc Đại Quốc hội Thổ Nhĩ Kỳ được công nhận về pháp lý. Như vậy biên giới phía đông được bảo đảm, cho phép chuyển lực lượng sang mặt trận phía tây.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Trận İnönü lần thứ nhất: chiến thắng đầu tiên của quân đội chính quy", "4add3719"], "d": ["Quân đội chính quy mới thành lập đã chặn lực lượng Hy Lạp tiến từ hướng Bursa tại các vị trí İnönü và buộc họ phải rút lui. Thành công có quy mô hạn chế về quân sự này lại rất lớn về hệ quả chính trị: chính phủ Ankara được mời dự Hội nghị London, đường đến Hiệp ước Moscow với nước Nga Xô viết được mở, và Luật Tổ chức Căn bản được thông qua. Niềm tin của công luận trong nước vào quân đội chính quy cũng được củng cố nhờ chiến thắng này.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Trận İnönü lần thứ hai: cuộc tấn công của Hy Lạp bị bẻ gãy lần thứ hai", "a974521c"], "d": ["Không đạt được kết quả tại Hội nghị London, quân đội Hy Lạp mở cuộc tấn công mới từ hướng Bursa và Uşak, nhưng lại bị chặn ở các sườn núi İnönü và buộc phải rút lui. Bức điện Mustafa Kemal Pasha gửi İsmet Pasha, “Ở đó ngài không chỉ đánh bại quân thù mà còn đánh bại cả vận mệnh bất hạnh của dân tộc”, được viết sau chiến thắng này. Trận đánh nâng cao uy tín quốc tế của cuộc Đấu tranh Dân tộc và đẩy nhanh quá trình Ý rút khỏi Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Thỏa ước Ankara: hòa bình với Pháp và đóng mặt trận phía nam", "35fc32db"], "d": ["Theo thỏa ước ký với Pháp tại Ankara sau chiến thắng Sakarya, chiến tranh trên mặt trận phía nam chấm dứt; quân Pháp rút khỏi vùng Çukurova và miền Đông Nam, kể cả Adana, Antep, Maraş và Urfa, lui về biên giới Syria. Như vậy một trong các nước Entente trên thực tế đã công nhận chính phủ Ankara, và vết nứt đầu tiên xuất hiện trên mặt trận Sèvres. Vũ khí tiếp quản ở các vùng được bỏ lại và các đơn vị được giải phóng đóng vai trò then chốt trong việc chuẩn bị cho cuộc Đại Tấn công.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Hiệp định đình chiến Mudanya: Istanbul và các Eo biển được chuyển giao không cần giao chiến", "ac0d9baf"], "d": ["Khi sau cuộc Đại Tấn công, quân đội Thổ Nhĩ Kỳ đối mặt với lực lượng Anh ở Çanakkale và İzmit, hội nghị nhóm họp tại Mudanya đã kết thúc bằng hiệp định đình chiến sau mười một ngày mặc cả gay go. Hai bên chấp nhận việc Hy Lạp rút khỏi miền Đông Thrace đến tận sông Maritsa trong mười lăm ngày và giao cho chính quyền Thổ Nhĩ Kỳ, còn Istanbul và các Eo biển sẽ được trao lại theo hiệp ước hòa bình. Như vậy giai đoạn vũ trang của cuộc Đấu tranh Dân tộc khép lại bằng thắng lợi ngoại giao giành được mà không nổ một phát súng, và cánh cửa đến Lausanne được mở ra.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Mehmed VI Vahideddin rời Istanbul và Abdülmecid Efendi được bầu làm caliph", "8ab0e847"], "d": ["Vị sultan cuối cùng Mehmed VI Vahideddin, người có địa vị trở nên gây tranh cãi sau khi chế độ sultan bị bãi bỏ, sáng thứ Sáu ngày 17 tháng 11 năm 1922 đã rời Istanbul trên thiết giáp hạm Malaya của Anh đến Malta. Hai ngày sau, ngày 19 tháng 11, Đại Quốc hội Thổ Nhĩ Kỳ bầu Abdülmecid Efendi làm caliph không có quyền lực chính trị. Quyền cai trị sáu trăm hai mươi ba năm của triều đại Ottoman như vậy trên thực tế chấm dứt; chức caliph còn tồn tại mang tính tượng trưng thêm mười lăm tháng. Vahideddin sang Malta rồi sang Ý, định cư ở Villa Nobel tại San Remo; các đơn xin được một nước Hồi giáo tiếp nhận không có kết quả, và ngày 16 tháng 5 năm 1926 ông qua đời tại đó, sau khi nhắc lại rằng ông chưa bao giờ từ bỏ quyền sultan và quyền caliph của mình.", "86831a04"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Corinth chuyển về Lãnh địa Despot Morea", "392495eb"], "d": ["Corinth, từ năm 1358 là thái ấp của dòng họ Acciajuoli người Firenze thuộc thân vương quốc Achaea, đã rơi vào tay Theodoros, despot Byzantium ở Morea, năm 1395. Từ đó cho đến khi bị Ottoman chinh phục, thành phố nằm dưới quyền cai quản của lãnh địa despot.", "1803a03a"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Chinh phục Corinth", "87a2bc59"], "d": ["Trong chiến dịch Morea của Sultan Mehmed II, Nhà Chinh phục, thành Acrocorinth bị vây ba tháng và cuối cùng đầu hàng theo thỏa ước. Eo đất Corinth, được coi là cửa ngõ của Morea, nhờ đó thuộc về Ottoman.", "b2be3a05"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Corinth được để lại cho Venice", "9a25b6b9"], "d": ["Sau khi Patras thất thủ, Corinth được giao cho người Venice theo thỏa ước và dân Hồi giáo rời thành phố. Tháng 8 năm 1687, quân đội của Morosini đang tập trung tại Corinth cho chiến dịch đánh Athens.", "d92bcf7d"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Lấy lại Corinth", "26f53e3a"], "d": ["Điểm dừng lớn đầu tiên trong chiến dịch Morea của Damad Ali Pasha là Corinth; tháng 6 năm 1715, người Ottoman lấy lại thành phố từ tay người Venice và từ đây tiến vào phần còn lại của bán đảo.", "82e2e719"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Tiểu vương quốc của dòng họ Sabah ở Kuwait đặt dưới sự bảo hộ của Ottoman", "3584dba0"], "d": ["Theo mục từ Kuwait của TDV, bến cảng này do bộ lạc Utub từ Najd đến lập ra vào đầu thế kỷ 18, còn dòng họ Sabah nắm quyền cai quản vào khoảng cuối thế kỷ. Cũng trong những năm Al-Ahsa rơi vào tay nhà Saud, trước sức ép của phái Wahhabi, tiểu vương quốc không còn lựa chọn nào khác ngoài dựa vào Basra nên đã đặt mình dưới sự bảo hộ của Ottoman. Mối liên hệ này được chính thức hóa năm 1871 qua việc Midhat Pasha tổ chức lại Basra, và Kuwait được tính là một trong ba kazâ (huyện) của sancak Basra; yêu sách lãnh thổ về sau của Iraq cũng dựa trên ghi chép này.", "c084f05f"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Cộng hòa Dubrovnik cáo chung — quân Pháp chiếm đóng", "f8e27bf1"], "d": ["Người Pháp, sau khi đặt chân lên bờ biển Dalmatia theo Hiệp ước Campo Formio (1797), đã chiếm Dubrovnik ngày 27 tháng 5 năm 1806 và xóa bỏ nước cộng hòa thương nhân nhỏ bé này. Như vậy chấm dứt quy chế chư hầu kéo dài ba thế kỷ rưỡi của Dubrovnik, quốc gia đã giữ được quyền tự trị và đặc quyền thương mại nhờ nộp cống cho Ottoman từ năm 1458; thành phố cùng đảo Mljet của nước cộng hòa chuyển sang chịu sự cai trị trực tiếp của Pháp trên bản đồ.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Mất Sukhum vào tay Nga — bờ đông Biển Đen bị khai mở", "adc96bd4"], "d": ["Trong chiến tranh Ottoman–Nga 1806-1812, hạm đội Nga hướng về bờ đông Biển Đen và chiếm Sukhumkale, chỗ dựa của quyền thống trị Ottoman tại Abkhazia. Pháo đài này là trung tâm liên lạc với các bộ lạc Kavkaz và của việc buôn bán ven biển. Mất nó, lần đầu tiên Nga đứng chân lâu dài trên bờ đông Biển Đen; ảnh hưởng của Ottoman ở Kavkaz bị dồn lại quanh Anapa và Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga được giao cho chính quyền Ottoman", "66e0cc5d"], "d": ["Parga nằm trong tay Venice từ năm 1401 và chưa bao giờ thuộc quyền cai trị của Ottoman; sau khi Venice sụp đổ, nơi này lần lượt chuyển sang Pháp rồi Anh. Mục từ Ali Pasha xứ Tepelenë của TDV tóm tắt tình hình như sau: thành phố đầu hàng người Anh và mãi đến năm 1819 mới được giao cho Ali Pasha cai quản. Cuộc chuyển giao dẫn đến việc phần lớn dân chúng di cư sang quần đảo Ionia. Như vậy nơi cuối cùng trong bộ ba Preveza–Parga–Vonitsa, vốn được để lại cho Venice theo hòa ước Passarowitz, cũng gia nhập đế quốc; Parga sẽ thuộc Ottoman thêm chín mươi tư năm.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Argos rơi vào tay quân nổi dậy Hy Lạp", "be66a696"], "d": ["Trong những tháng đầu của cuộc nổi dậy ở Morea, Argos và vùng phụ cận thoát khỏi sự cai trị của Ottoman và rơi vào tay quân nổi dậy Hy Lạp; tháng 5 năm 1821, thành phố trở thành nơi diễn ra cuộc phản công của lực lượng Ottoman.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ahmed Kihaya chiếm Argos, thành phố bị cướp phá và đốt cháy", "d6d3ac7b"], "d": ["Lực lượng của Ahmed Kihaya đánh bại người Hy Lạp tại Argos, rồi cướp phá và đốt cháy thành phố; trong một thời gian ngắn, thị trấn trở lại dưới sự kiểm soát của Ottoman.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Tại Argos, Ahmed Kihaya hợp quân với người Hồi giáo Tripolitsa rồi tiến về Tripolitsa", "9d679fd5"], "d": ["Tại Argos, Ahmed Kihaya hợp quân với người Hồi giáo Tripolitsa rồi tiến về phía Tripolitsa; Argos lại rơi vào quyền kiểm soát của quân nổi dậy Hy Lạp.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Corinth rơi vào tay quân nổi dậy Hy Lạp", "892dcdc6"], "d": ["Trong chiến tranh giành độc lập Hy Lạp, Acrocorinth rơi vào tay quân nổi dậy và chỉ huy pháo đài Kâmil Bey bị bắt làm tù binh.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Mahmud Pasha xứ Drama đặt đại bản doanh tại Argos", "c79abbfb"], "d": ["Quân đội của Mahmud Pasha xứ Drama tiến vào đồng bằng Argos và vị pasha đặt đại bản doanh tại thị trấn Argos; thị trấn lại thuộc quyền kiểm soát của Ottoman.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Mahmud Pasha xứ Drama bắt đầu rút khỏi Argos", "5e5afb74"], "d": ["Buộc phải rút lui khi chiếm đóng Argos chưa đầy hai tuần, Mahmud Pasha xứ Drama bắt đầu rút sư đoàn đầu tiên của quân đội mình về hướng Corinth; Argos lại rơi vào tay quân nổi dậy Hy Lạp.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Mất Nafplio (Nauplion) vào tay quân nổi dậy", "1a67fa50"], "d": ["Nafplio, hải cảng có hệ thống phòng thủ mạnh nhất Morea, đã đầu hàng vì đói sau hơn một năm bị phong tỏa. Từ đầu cuộc nổi dậy, pháo đài này là chỗ dựa lớn cuối cùng của quyền kiểm soát Ottoman trên bán đảo; mất nó, toàn bộ Morea rơi vào tay quân nổi dậy. Không lâu sau, thành phố trở thành thủ đô đầu tiên của nhà nước Hy Lạp mới.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Lepanto chuyển sang quyền cai quản của Hy Lạp", "c9d19d4b"], "d": ["Lepanto, trên bờ bắc vịnh Corinth, vẫn nằm trong tay Ottoman cho đến cuộc nổi dậy của người Hy Lạp, đã bị mất vào tháng 4 năm 1829 và chuyển sang quyền cai quản của Hy Lạp; tên thị trấn được đổi thành Naupaktos theo thời cổ đại. Dân Hồi giáo và Do Thái của thành phố biến mất hoàn toàn, và nơi đây trở thành một thị trấn nhỏ.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Pháp chiếm Algiers — Quân khu tự trị (ocak) ba trăm năm cáo chung", "0be8f568"], "d": ["Lấy cớ vụ chiếc quạt phát sinh từ một tranh chấp nợ nần, Pháp phong tỏa bờ biển Algeria suốt ba năm, rồi đổ quân lên Sidi Fredj. Kết thúc chiến dịch kéo dài ba tuần, Dey Hüseyin đầu hàng và Ocak Algiers của Ottoman, tồn tại từ năm 1516, chấm dứt. Cuộc chiếm đóng không chỉ dừng ở thủ phủ; Tlemcen, Cherchell và Médéa trong nội địa cũng bị mất ngay trong mùa hè ấy. Phải thêm hai mươi tư năm nữa toàn bộ bờ biển mới rơi vào quyền kiểm soát của Pháp.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Negroponte được giao cho Hy Lạp — cùng với cả hòn đảo (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, nơi diễn ra giao tranh dữ dội suốt chiến tranh giành độc lập Hy Lạp nhưng vẫn trong tay Ottoman, đã được giao cho người Hy Lạp năm 1831 sau khi hiệp ước hòa bình có hiệu lực. Dân Hồi giáo của thành phố, vốn là một căn cứ hải quân quan trọng từ năm 1470, bán hết tài sản với giá rất rẻ rồi di cư tập thể sang lãnh thổ Ottoman; thành phố bỏ trống trong thời gian dài, và năm 1842 nhà du hành người Đức Fallmerayer gọi nó là một thành phố ma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Pháp chiếm Oran", "a8415d66"], "d": ["Oran, được Tây Ban Nha chuyển giao không qua chiến tranh năm 1792, là hải cảng lớn nhất ở miền tây Algeria. Sáu tháng sau khi thủ phủ thất thủ, quân Pháp tiến vào thành phố. Chiến dịch phía tây khởi đầu từ đây chẳng bao lâu sau đã vấp phải cuộc kháng chiến kéo dài mười lăm năm của Emir Abd al-Qadir.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Chiếm đóng Annaba (Bône)", "21f37fb1"], "d": ["Annaba, hải cảng ở miền đông Algeria gần biên giới Tunisia, bị quân Pháp chiếm và biến thành căn cứ cho cuộc tiến quân vào Constantine. Thành phố đồng thời là hải cảng châu Phi gần đảo Sardinia nhất ở phía đối diện.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Athens được giao cho nhà nước Hy Lạp mới (ngày quân Bavaria tiếp nhận Acropolis)", "deee4d37"], "d": ["Athens, thuộc Ottoman từ năm 1456, đã đổi chủ nhiều lần trong chiến tranh giành độc lập Hy Lạp, và đội đồn trú tại Acropolis lại trở về dưới quyền kiểm soát của Ottoman năm 1827. Vì nằm ở phía bắc đường biên giới vạch ra theo Nghị định thư London, thành phố được giao cho vương quốc mới và đội đồn trú rút khỏi Acropolis. Ngày dùng trong atlas là ngày quân Bavaria tiếp nhận Acropolis; đội đồn trú Ottoman thực sự rời đi vài ngày sau đó (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, chương 13; Finlay, Journals and Letters, tập I, tr. 67). Năm sau, Athens được tuyên bố là thủ đô của Hy Lạp thay cho Nafplio.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Chiếm đóng Béjaïa (Bougie)", "a8927e00"], "d": ["Cảng Béjaïa, nơi dãy núi Kabylie mở ra biển, là mắt xích độc lập cuối cùng của tuyến ven biển giữa Algiers và Annaba. Cảng bị chiếm với sự yểm trợ của pháo hải quân; tuy nhiên vùng núi nội địa phía sau còn ba mươi năm nữa mới rơi vào quyền kiểm soát của Pháp. Những cuộc chiếm đóng dọc bờ biển này tạo nên quá trình Algeria thuộc Ottoman tan dần từng năm trên bản đồ.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Chiếm đóng Sétif", "2073731a"], "d": ["Một năm sau khi Constantine thất thủ, quân Pháp tiến lên cao nguyên, chiếm Sétif, thành phố La Mã cổ, và lập tại đây một đồn trú thường trực. Sétif là giao điểm của các tuyến đường lữ hành giữa bờ biển và Sahara; việc chiếm đóng nó cho thấy Pháp đã bắt đầu kiểm soát không chỉ các hải cảng mà cả mạng lưới thương mại nội địa.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Chiếm đóng Biskra — mất cửa ngõ Sahara", "d895cad0"], "d": ["Biskra, ở chân phía nam dãy Atlas, là cửa ngõ mở ra Sahara và là trung tâm các ốc đảo chà là. Khi nơi này bị chiếm vào những năm cuộc kháng chiến của Emir Abd al-Qadir bắt đầu suy sụp, quyền kiểm soát của Pháp lần đầu tiên vươn tới rìa phía bắc sa mạc. Từ đây về sau là một chiến dịch trên sa mạc tiến từng ốc đảo một.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Chiếm đóng Touggourt — mất toàn bộ Algeria", "33c056e2"], "d": ["Với việc chiếm Touggourt, thành phố ốc đảo ở phía bắc Sahara, cuộc chiếm đóng khởi đầu năm 1830 đã hoàn tất tại nửa phía bắc của Algeria ngày nay. Trong những năm này, Đế quốc Ottoman đang chiến đấu cùng phe với Pháp trong Chiến tranh Crimea; tuy không bao giờ chính thức từ bỏ yêu sách pháp lý đối với Algeria, trên thực tế họ không thể làm được một bước nào. Vùng đất duy nhất còn lại ở Bắc Phi là Tripolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["El Obeid thất thủ — Kordofan rơi vào tay lực lượng Mahdi", "58299f62"], "d": ["Phong trào do Muhammad Ahmad, người tự xưng là Mahdi, khởi xướng đã lan nhanh chống lại sự cai trị của Ai Cập tại Sudan. El Obeid, trung tâm của Kordofan, thất thủ sau bốn tháng bị vây và trở thành thủ phủ của cuộc nổi dậy; ngân khố và kho vũ khí trong thành giúp phong trào tổ chức thành quân đội. Về pháp lý, Sudan vẫn là đất của Khedive Ai Cập thuộc Ottoman, nên sự mất mát này bị trừ khỏi phần thân của đế quốc trên bản đồ.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Khartoum thất thủ — mất toàn bộ Sudan", "d4b98464"], "d": ["Sau cuộc vây hãm kéo dài mười tháng, lực lượng Mahdi tiến vào Khartoum, nơi hợp lưu của sông Nin Xanh và sông Nin Trắng; tổng đốc thành phố Gordon bị giết, và cánh quân Anh được phái đến cứu viện đã chậm hai ngày. Từ đó, toàn bộ Sudan, gồm cả Sennar, Dongola và Kordofan, nằm dưới quyền cai trị của Nhà nước Mahdi trong mười bốn năm. Phải đến năm 1899, vùng này mới chuyển sang chế độ đồng quản Anh–Ai Cập, khi mối liên hệ với Ottoman đã bị cắt đứt hoàn toàn.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Ý chiếm Massawa — mất bờ tây Biển Đỏ", "c333b95b"], "d": ["Cảng Massawa, trung tâm của tỉnh Habeş (Abyssinia), bị Ý chiếm đóng nhân lúc tình hình hỗn loạn khi cuộc nổi dậy Mahdi tràn khắp Sudan; đây là hạt nhân của xứ Eritrea thuộc Ý. Suakin ở phía bắc và quần đảo Dahlak ngoài khơi cũng bị mất trong cùng tiến trình đó. Như vậy quyền thống trị của Ottoman trên bờ tây Biển Đỏ, kéo dài từ thời Selim I \"Nghiêm Khắc\", đã chấm dứt, và giờ đây biển này trở thành vùng nước mà cả hai bờ đều thuộc ngoại bang.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Ý chiếm Rhodes", "e08662c5"], "d": ["Muốn buộc Đế quốc Ottoman ngồi vào bàn đàm phán trong chiến tranh Tripolitania, Ý đưa chiến tranh ra Địa Trung Hải và đổ quân lên Rhodes. Hòn đảo bị tiếp quản chỉ trong vài ngày. Rhodes, được Suleiman Nhà Lập pháp chiếm sau một cuộc vây hãm dài năm 1522 và giữ suốt ba trăm chín mươi năm, từ đó không còn là căn cứ đảo lớn nhất của đế quốc ở Đông Địa Trung Hải; tuy Hiệp ước Ouchy coi đây là chiếm đóng tạm thời, nó không bao giờ được lấy lại.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Ý chiếm quần đảo Dodecanese", "200aacf2"], "d": ["Trong vòng vài tuần sau khi chiếm Rhodes, hạm đội Ý chiếm luôn các đảo xung quanh; về sau quần đảo này được gọi là 'Dodecanese'. Phần lớn các đảo chỉ cách bờ biển Anatolia vài hải lý và khống chế cửa ngõ đông nam của biển Aegea. Trong Hiệp ước Ouchy, cuộc chiếm đóng được coi là tạm thời để đổi lấy việc từ bỏ Tripolitania, nhưng Ý không bao giờ rút khỏi các đảo; năm 1947 chúng được chuyển giao cho Hy Lạp.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Chiếm đóng đảo Kos", "ab246c62"], "d": ["Kos, mắt xích cuối cùng của chiến dịch Dodecanese, là hòn đảo trù phú, đông dân nằm ngay đối diện bán đảo Bodrum. Với cuộc chiếm đóng này, tất cả các đảo ở góc đông nam biển Aegea đã rơi vào quyền kiểm soát của Ý, và bờ biển tây nam Anatolia bị bao quanh suốt chiều dài bởi một chuỗi đảo của ngoại bang.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Ikaria tuyên bố độc lập", "c4452033"], "d": ["Trên hòn đảo nhỏ Ikaria nằm giữa Samos và Chios, giữa bối cảnh bất định do các cuộc chiếm đóng của Ý gây ra, dân chúng nổi dậy, trục xuất hiến binh Ottoman khỏi đảo và tuyên bố một 'nhà nước tự do' với cờ, tem và nghị viện riêng, tồn tại năm tháng. Tháng 11 năm 1912, đảo sáp nhập vào Hy Lạp. Dù hòn đảo nhỏ bé, sự kiện này là dấu hiệu rõ ràng cho thấy chính quyền trung ương ở biển Aegea đã tan rã ra sao.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Samos thoát khỏi sự cai trị của Ottoman", "3a862f2b"], "d": ["Samos là một công quốc tự trị từ năm 1832, nộp thuế cho Ottoman và do một bey được Istanbul bổ nhiệm cai quản. Lợi dụng khoảng trống do chiến tranh Tripolitania tạo ra, phong trào chủ trương hợp nhất trên đảo nắm quyền cai quản và chế độ công quốc tự trị trên thực tế chấm dứt; cũng trong năm đó, đảo tuyên bố sáp nhập vào Hy Lạp. Hòn đảo cách bờ biển Anatolia hai kilômét này là một trong những vùng đất đầu tiên bị mất ở biển Aegea.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Ioannina thất thủ — mất Epirus và Parga", "d42fce18"], "d": ["Bị vây suốt năm tháng trong chiến tranh Balkan, Ioannina đầu hàng sau khi các trận địa Bizani thất thủ; cùng với thành phố, toàn bộ Epirus chuyển sang Hy Lạp. Parga thuộc sancak Ioannina cũng bị mất vào thời điểm này, và chín mươi tư năm cai trị của Ottoman chấm dứt. Mất Ioannina đồng nghĩa với việc cánh cửa sổ cuối cùng của đế quốc nhìn ra biển Adriatic đã đóng lại.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Edirne rơi vào tay người Bulgaria", "459d2e56"], "d": ["Sau cuộc vây hãm kéo dài năm tháng rưỡi, hết đạn dược và lương thực, Edirne đầu hàng; Şükrü Pasha bị bắt làm tù binh. Việc thất thủ một thành phố thuộc Ottoman từ năm 1361 và từng là thủ đô suốt chín mươi hai năm được coi là đòn nặng nhất của chiến tranh Balkan. Bốn tháng sau, trong chiến tranh Balkan lần thứ hai, Edirne được lấy lại nhờ lợi dụng việc Bulgaria sụp đổ trên các mặt trận khác.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Mất Yanbu vào tay lực lượng của Sharif Hussein", "e291c816"], "d": ["Cuộc nổi dậy do Sharif Hussein phát động hồi tháng 6 lan ra bờ Biển Đỏ; Yanbu, hải cảng của Medina, rơi vào tay quân nổi dậy với sự yểm trợ của hải quân Anh. Cảng này trở thành cửa ngõ chính cho dòng vũ khí và tiền bạc từ bên ngoài đổ vào cuộc nổi dậy. Như vậy lực lượng của Fahreddin Pasha ở Medina bị cắt đứt liên lạc với biển, và thành phố đơn độc ở đầu mút của tuyến đường sắt Hejaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Trận Gaza lần thứ ba — mất Gaza và Khan Yunis", "c142a069"], "d": ["Sau hai lần thất bại, trong đợt tấn công thứ ba Allenby đã chọc thủng mặt trận bằng cách đánh vòng qua Beersheba, và phòng tuyến Gaza được giữ suốt sáu tháng đã sụp đổ. Gaza và Khan Yunis ở phía nam được bỏ lại ngay trong ngày. Cú đột phá này mở đầu cho sự tan rã của mặt trận Palestine; năm tuần sau Jerusalem sẽ thất thủ.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Chiếm đóng Komotini — mất Tây Thrace", "904d813c"], "d": ["Sau Hiệp định đình chiến Mudros, Tây Thrace trước hết đặt dưới quyền kiểm soát của quân Đồng minh Hiệp ước, rồi theo quyết định của hội nghị San Remo được để lại cho Hy Lạp, và quân đội Hy Lạp tiến vào Komotini. Vùng này, đã được lấy lại từ Bulgaria năm 1913, là mảnh đất cuối cùng đế quốc đánh mất ở Rumelia. Quy chế của cộng đồng người Thổ trong vùng được quy định ba năm sau tại Lausanne theo chế độ thiểu số. Với cuộc chiếm đóng này, các kazâ (huyện) Komotini, Xanthi, Alexandroupoli (Dedeağaç) và Soufli của Tây Thrace chuyển sang Hy Lạp.", "ef0aeba3"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Dịch hạch ở Istanbul và triều đình dời sang Edirne", "70c7a163"], "d": ["Theo mục từ Istanbul của Bách khoa toàn thư Hồi giáo TDV, việc định cư nhanh và dày đặc tại thành phố đã tạo điều kiện cho dịch bệnh lan truyền theo từng đợt; trong trận dịch hạch năm 1466, triều đình và các đại thần tạm thời rút về Edirne. Dân số thành phố chịu tổn thất nghiêm trọng trong những đợt dịch như vậy.", "7b20238c"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Các madrasa Sahn-ı Semân khai giảng", "021f2a83"], "d": ["Theo mục từ Sahn-ı Semân của Bách khoa toàn thư Hồi giáo TDV, tám madrasa này, được lập trong quần thể Fatih, được thiết kế làm cơ sở giáo dục bậc cao nhất đương thời và là đỉnh của hệ thống thứ bậc giới học giả (ilmiye) Ottoman. Trong các thế kỷ sau, việc làm giáo sư (müderris) và tốt nghiệp tại đây được coi là bậc thang danh giá nhất trong sự nghiệp làm kadi và giáo sư.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Hoàn thành Cung điện Topkapı (Tân Cung, Saray-ı Cedîd)", "d2db6323"], "d": ["Theo mục từ Cung điện Topkapı của Bách khoa toàn thư Hồi giáo TDV, các nguồn đương thời không thống nhất về ngày khởi công và hoàn thành; theo niên đại 883 (1478) trên bia ở cổng Bâb-ı Hümâyun, công trình, có lẽ được khởi công năm 1465 theo lệnh của Sultan Mehmed II, về cơ bản đã hoàn thành đến năm này, và cung điện thay thế trung tâm nhà nước ở cung cũ. Như vậy sultan chuyển đến nơi ở mới, nơi sẽ là trái tim hành chính và nghi lễ của nhà nước suốt ba thế kỷ.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Bayezid II lên ngôi tại Istanbul", "9b686d04"], "d": ["Theo mục từ Bayezid II của Bách khoa toàn thư Hồi giáo TDV, hoàng tử Bayezid, khi đó là sancak bey của Amasya, nghe tin cha qua đời đã vội đến Istanbul và lên ngôi; nhờ sự ủng hộ của quân Janissary, ông đi trước em trai Cem, người khởi hành từ Konya. Trong lễ đăng quang, quân Janissary được phát tiền thưởng đăng quang theo lệ. Cuộc chuyển giao ngôi vị này cũng châm ngòi cho cuộc tranh giành giữa hai anh em.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan tự xưng sultan tại Bursa", "b355168a"], "d": ["Theo mục từ Cem Sultan của Bách khoa toàn thư Hồi giáo TDV, Cem đi qua Karaman đến Bursa, chiếm thành phố, tự xưng sultan và cho đọc khutba nhân danh mình. Triều đại ngắn ngủi này chấm dứt khi lực lượng do anh trai Bayezid II phái đến đánh bại Cem tại Yenişehir. Sau thất bại, Cem buộc phải chạy sang Ai Cập.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Gedik Ahmed Pasha bị xử tử", "6d75a58c"], "d": ["Theo mục từ Gedik Ahmed Pasha của Bách khoa toàn thư Hồi giáo TDV, vị pasha nổi tiếng với chiến dịch Otranto và chức đại tể tướng đã bị xử tử tại Edirne theo lệnh của Bayezid II, do thái độ của ông trong vụ Cem Sultan và mối lo ngại về thế lực của ông. Cái chết của một trong những tướng lĩnh dày dạn nhất thời Sultan Mehmed II gây tiếng vang lớn trong triều.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Lập nhà in đầu tiên tại Istanbul", "04475930"], "d": ["Theo mục từ Matbaa (Nhà in) của Bách khoa toàn thư Hồi giáo TDV, hai anh em David và Samuel ibn Nahmias, người Do Thái di cư từ Tây Ban Nha, đã lập tại Istanbul nhà in đầu tiên in bằng chữ Hebrew. Đây được ghi nhận là nỗ lực in ấn đầu tiên hoạt động trên lãnh thổ Ottoman; còn việc in tiếng Thổ bằng chữ Ả Rập mãi sau này, vào thế kỷ XVIII, mới thực hiện được.", "118df98b"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Trận động đất 'Tiểu Tận thế' tại Istanbul", "53e3b1d6"], "d": ["Theo mục từ Istanbul của Bách khoa toàn thư Hồi giáo TDV, trận động đất dữ dội giáng xuống thành phố được dân chúng đương thời gọi là 'Tiểu Tận thế'; tường thành, thánh đường và nhiều công trình bị hư hại nặng, rất nhiều người thiệt mạng. Theo lệnh của Bayezid II, một chiến dịch sửa chữa và tái thiết quy mô lớn được khởi động trong thành phố.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Cuộc nổi dậy của Şahkulu bùng nổ", "3d9a4a90"], "d": ["Theo mục từ Şahkulu Baba Tekeli của Bách khoa toàn thư Hồi giáo TDV, Şahkulu, được nuôi dưỡng bởi tuyên truyền Safavid, đã tập hợp quanh mình đông đảo người Turkmen ở vùng Teke và phát động một cuộc nổi dậy lớn mang tính tôn giáo–xã hội. Là một trong những cuộc khủng hoảng an ninh nội bộ nghiêm trọng nhất đương thời, cuộc nổi dậy làm lung lay sâu sắc quyền lực trung ương của nhà nước.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Bayezid II qua đời trên đường đến Didymoteicho", "c46e98c9"], "d": ["Sau khi thoái vị, vị cựu sultan rời Istanbul để đến Didymoteicho, thành phố nơi ông sinh ra; khi đang đi trên chiếc kiệu mỗi ngày chỉ được 5-6 km, ông trở bệnh tại làng Abalar gần Çorlu và qua đời ngày 25 Rabi' I năm 918 (10 tháng 6 năm 1512). Bách khoa toàn thư Hồi giáo TDV cho rằng nguyên nhân cái chết rất đáng ngờ; một số nguồn trong nước và nước ngoài nêu khả năng ông đã bị đầu độc. Như vậy vị sultan thứ tám thuộc dòng dõi Osman Gazi đã qua đời sau ba mươi mốt năm trị vì.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Hoàng tử Ahmed bị xử tử theo lệnh Selim I \"Nghiêm Khắc\"", "65abb2f2"], "d": ["Theo mục từ Selim I của Bách khoa toàn thư Hồi giáo TDV, hoàng tử Ahmed, người được cha là Bayezid II sủng ái và là đối thủ chính tranh ngôi, đã bị đánh tan trên đồng bằng Yenişehir trong cuộc tranh đấu mà ông phát động sau khi em trai Selim lên ngôi, rồi bị bắt và giết khi đang chạy khỏi chiến trường. Với sự kiện này, Selim về cơ bản đã chấm dứt cuộc tranh ngôi giữa các anh em và cháu mình.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Pasha được bổ nhiệm làm đại tể tướng", "9c94c1e3"], "d": ["Theo mục từ İbrâhîm Pasha, Makbul (\"người được sủng ái\") của Bách khoa toàn thư Hồi giáo TDV, İbrahim Pasha, từ chức trưởng thị tòng nội cung (has odabaşı) được thăng làm beylerbey Rumelia và ngay trong ngày lên chức đại tể tướng, đã trở thành đại tể tướng ngày 13 Sha'ban 929 (27 tháng 6 năm 1523). Đây là cuộc bổ nhiệm chưa từng có, chuyển thẳng từ việc hầu cận trong cung lên chức đại tể tướng, cho thấy İbrahim Pasha gần gũi phi thường với Suleiman Nhà Lập pháp.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hayreddin Pasha được bổ nhiệm làm kapudan pasha (đô đốc hạm đội)", "a0ff6bab"], "d": ["Theo mục từ Barbaros Hayreddin Pasha của Bách khoa toàn thư Hồi giáo TDV, Hayreddin Pasha, nổi tiếng với những thành công ở Algiers, được triệu về Istanbul ngày 6 tháng 4 năm 1534 và được giao chức kapudan pasha cùng chức beylerbey tỉnh Quần đảo Địa Trung Hải (Cezayir-i Bahr-i Sefîd). Việc bổ nhiệm này được coi là khởi đầu cho việc tổ chức lại hạm đội Ottoman và thể chế hóa sức mạnh trên biển ở Địa Trung Hải.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pasha lần đầu làm đại tể tướng", "ddfcc014"], "d": ["Theo mục từ Rüstem Pasha của Bách khoa toàn thư Hồi giáo TDV, sau khi Hadım Süleyman Pasha bị cách chức do bất hòa với một vezir, Rüstem Pasha được bổ nhiệm làm đại tể tướng ngày 17 Ramadan 951 (2 tháng 12 năm 1544). Nhờ cuộc hôn nhân với công chúa Mihrimah, Rüstem Pasha ngày càng gần gũi với hoàng cung, và với chức vụ này ông trở thành một trong những chính khách có ảnh hưởng nhất thời Suleiman Nhà Lập pháp.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi trở thành shaykh al-Islam", "11ed04f8"], "d": ["Theo mục từ Ebüssuûd Efendi của Bách khoa toàn thư Hồi giáo TDV, sau tám năm làm kazasker (quan tòa quân sự tối cao) Rumelia, Ebüssuûd Efendi được đưa lên chức shaykh al-Islam vào Sha'ban 952 (tháng 10 năm 1545) và giữ chức này hai mươi tám năm mười một tháng. Nổi tiếng với các fatwa làm cho bộ luật của Suleiman Nhà Lập pháp hòa hợp với luật Sharia, Ebüssuûd Efendi đóng vai trò quyết định trong việc định hình các thiết chế luật pháp và giáo dục đương thời.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Barbaros Hayreddin Pasha qua đời", "3378a0bf"], "d": ["Theo mục từ Barbaros Hayreddin Pasha của Bách khoa toàn thư Hồi giáo TDV, sau một trận bệnh ngắn, ông qua đời tại Istanbul ngày 6 Jumada I 953 (5 tháng 7 năm 1546). Barbaros được an táng trong lăng liền kề madrasa do chính ông xây ở Beşiktaş; cái chết của ông được xem là sự khép lại một thời kỳ trong ưu thế trên Địa Trung Hải mà hạm đội Ottoman đã tạo dựng.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Khởi công thánh đường Süleymaniye và quần thể công trình", "101ec36f"], "d": ["Theo mục từ Thánh đường và quần thể Süleymaniye của Bách khoa toàn thư Hồi giáo TDV, quần thể được đặt móng năm 1550 dưới sự chỉ đạo của tổng kiến trúc sư Mimar Sinan, được thiết kế là một quần thể xã hội lớn gồm, bên cạnh thánh đường, các madrasa, bệnh viện, bếp phát chẩn và thư viện. Công trình là một trong những chương trình xây dựng lớn nhất, tượng trưng cho sức mạnh triều đại Suleiman Nhà Lập pháp và công cuộc kiến thiết Istanbul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Một đợt dịch hạch mới bùng lên ở Istanbul và vùng phụ cận", "547d6bf6"], "d": ["Theo mục từ Tâun (Dịch hạch) của Bách khoa toàn thư Hồi giáo TDV, một trong các đợt dịch thế kỷ 16 ảnh hưởng đến thế giới Hồi giáo diễn ra trong giai đoạn 1552-1566 và đặc biệt tác động đến Istanbul, Anatolia, Rumelia, Ai Cập cùng Bắc Phi. Mạng lưới thương mại mở rộng và việc di chuyển dân cư gia tăng được kể trong số những yếu tố tạo thuận lợi cho dịch bệnh lan truyền vào thời kỳ đế quốc hùng mạnh nhất.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Pasha được bổ nhiệm làm đại tể tướng", "a7d7748e"], "d": ["Theo mục từ Kara Ahmed Pasha của Bách khoa toàn thư Hồi giáo TDV, Kara Ahmed Pasha, đang giữ chức vezir thứ hai, được thăng làm đại tể tướng ngày 27 Shawwal 960 (5 tháng 10 năm 1553) sau khi đại tể tướng đương nhiệm bị cách chức đột ngột. Sự thay đổi này đánh dấu một giai đoạn cán cân quyền lực trong cung đổi chủ nhanh chóng, trùng với những ngày hoàng tử Mustafa bị xử tử.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Đô đốc Piri Reis bị xử tử", "3b2ad7a0"], "d": ["Theo mục từ Pîrî Reis của Bách khoa toàn thư Hồi giáo TDV, khi những lời cáo buộc rằng ông nhận hối lộ để giải vây Hormuz, cướp bóc tài sản của người Hồi giáo và bỏ mặc quân đội trên chiến trường truyền đến Ai Cập, nhà hàng hải và bản đồ học lừng danh bị xử tử tại Cairo vào cuối năm 960 (cuối 1553). Cái chết của Piri Reis, người bị tịch biên gia sản, được đánh giá là hệ quả của sự cạnh tranh giữa các pasha trong chính sách hàng hải đương thời ở Basra và Ấn Độ Dương.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pasha bị xử tử, Rüstem Pasha lại làm đại tể tướng", "9a85076a"], "d": ["Theo các mục từ Rüstem Pasha và Kara Ahmed Pasha của Bách khoa toàn thư Hồi giáo TDV, ngày 13 Dhu'l-Qa'da 962 (29 tháng 9 năm 1555), Kara Ahmed Pasha bị xử tử đột ngột giữa phiên họp divan, và nhờ sự ủng hộ của Hürrem Sultan và công chúa Mihrimah, Rüstem Pasha được đưa lên làm đại tể tướng lần thứ hai ngay trong ngày. Hậu trường của vụ việc được các nguồn bỏ ngỏ và được đánh giá là kết quả của những mưu đồ trong cung.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Hürrem Sultan qua đời", "1ae998b5"], "d": ["Theo mục từ Hürrem Sultan của Bách khoa toàn thư Hồi giáo TDV, Hürrem Sultan, người nhiều năm có thế lực lớn trong cung với tư cách haseki sultan (sủng phi chính) của Suleiman Nhà Lập pháp, qua đời tại Istanbul ngày 26 Jumada II 965 (15 tháng 4 năm 1558) và được an táng trong lăng của bà tại quần thể thánh đường Süleymaniye. Sau khi thái hậu Hafsa qua đời năm 1534, Hürrem Sultan đã củng cố quyền uy đối với hậu cung; cái chết của bà cũng xóa bỏ ảnh hưởng giữ thế cân bằng trước cuộc tranh ngôi giữa hai con trai Bayezid và Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokollu Mehmed Pasha lên chức đại tể tướng", "896391a2"], "d": ["Theo mục từ Sokollu Mehmed Pasha của Bách khoa toàn thư Hồi giáo TDV, khi Semiz Ali Pasha qua đời ngày 30 Dhu'l-Qa'da 972 (29 tháng 6 năm 1565), Sokollu Mehmed Pasha lên làm đại tể tướng; ông là đại tể tướng cuối cùng của Suleiman Nhà Lập pháp và tiếp tục giữ chức này dưới thời Selim II và Murad III sau đó, trở thành một trong những đại tể tướng tại chức lâu nhất trong lịch sử Ottoman.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II đến Istanbul và lên ngôi", "0289ef97"], "d": ["Sau khi Sultan Suleiman Nhà Lập pháp qua đời tại Szigetvár, Sokollu Mehmed Pasha giấu tin này suốt nhiều tuần để không làm rối loạn trật tự. Theo Bách khoa toàn thư Hồi giáo TDV, Selânikî ghi ngày Selim đến Istanbul là 15 Rabi' I 974 (30 tháng 9 năm 1566), còn đa số sử gia đương thời coi ngày 9 Rabi' I (24 tháng 9) là đúng. Mãi đến ngày 24-25 tháng 10 năm 1566, cái chết của Suleiman mới được chính thức công bố tại Belgrade.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Hạm đội do Kılıç Ali Pasha đóng lại được hạ thủy", "d0fc9f48"], "d": ["Sau thất bại nặng nề tại Lepanto (7 tháng 10 năm 1571), các xưởng đóng tàu đóng thuyền suốt cả mùa đông. Theo Bách khoa toàn thư Hồi giáo TDV, ngày 1 Safar 980 (13 tháng 6 năm 1572), hạm đội mới gồm 250 chiến thuyền galley và khoảng 300 thuyền chèo của các thuyền trưởng tình nguyện được hạ thủy trong một cuộc phô trương lực lượng.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokollu Mehmed Pasha bị ám sát", "6ffa8dec"], "d": ["Sokollu Mehmed Pasha, đại tể tướng suốt mười bốn năm qua ba đời sultan, bị một tu sĩ dervish giả vờ dâng đơn tiến đến đâm chết bằng dao găm tại phiên divan buổi xế chiều ở dinh của ông ngày 20 Sha'ban 987 (12 tháng 10 năm 1579). Theo Bách khoa toàn thư Hồi giáo TDV, người ta tranh luận liệu vụ ám sát có liên quan đến việc trả thù cho Hamza Bali, giáo trưởng dòng Hamzaviyya bị hành quyết.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Hiệp ước thương mại đầu tiên với Anh — người Anh được cấp đặc quyền (capitulation)", "59c8e3ee"], "d": ["William Harborne, đại diện Anh được phái đến Istanbul tháng 10 năm 1578, nhờ sự ủng hộ của Sokollu Mehmed Pasha và Hoca Sadeddin Efendi đã nhận được từ Murad III một ahidname (văn bản cam kết) đề năm 1580. Với văn bản này, thương nhân Anh được hưởng ở mức tương đương những đặc quyền thương mại (capitulation) trước đó đã cấp cho người Pháp và người Venice. Thư từ được trao đổi giữa Nữ hoàng Elizabeth I và Murad III, và quan hệ chính thức giữa hai nước cũng được thiết lập. Ngay sau các đặc quyền này, năm 1581 Công ty Levant được thành lập tại London; người Anh buôn bán trong khu vực qua công ty này cho đến năm 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Đài thiên văn Istanbul bị phá theo thánh chỉ của sultan", "3bc0c78c"], "d": ["Dưới tác động của một fatwa cho rằng đài thiên văn mang điềm gở đến cho đất nước cùng sự chống đối trong cung, theo thánh chỉ ngày 4 Dhu'l-Hijja 987 (22 tháng 1 năm 1580), Đài thiên văn Istanbul bị phá bỏ cùng toàn bộ dụng cụ bên trong. Theo Bách khoa toàn thư Hồi giáo TDV, đây là kết cục chóng vánh của cơ sở do Taqi al-Din nhà thiên văn (Takıyyüddin er-Râsıd) lập ra.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Đại lễ cắt bao quy đầu của hoàng tử Mehmed tại quảng trường Atmeydanı bắt đầu", "c2926d5d"], "d": ["Hoàng tử Mehmed, con trai Murad III, được làm lễ cắt bao quy đầu trong những nghi lễ lộng lẫy bắt đầu ngày 6 Jumada I 990 (29 tháng 5 năm 1582) và kéo dài năm mươi sáu đến năm mươi bảy ngày. Theo Bách khoa toàn thư Hồi giáo TDV, hội hè tổ chức tại quảng trường Atmeydanı (trường đua Hippodrome) là một trong những lễ mừng cung đình nguy nga nhất đương thời.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Thái hậu Nurbanu qua đời", "77d0a577"], "d": ["Nurbanu Sultan, mẹ của Murad III, qua đời ngày 22 Dhu'l-Qa'da 991 (7 tháng 12 năm 1583). Theo Bách khoa toàn thư Hồi giáo TDV, trên cương vị thái hậu (valide sultan), bà đã trao đổi thư từ với triều đình Venice và Pháp; cũng trong năm đó, viện nguyên lão Venice đã chấp thuận gửi tặng bà món quà trị giá 2000 đồng vàng Venice để đáp lại những đóng góp của bà.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Đồng akçe bị pha tạp làm bùng nổ Sự biến Beylerbeyi", "db2f2e61"], "d": ["Khi nhà nước thanh toán bằng đồng akçe đã bị giảm tỷ lệ bạc, kỵ binh sipahi và quân Janissary vây hãm hoàng cung, gây ra một cuộc nổi loạn đẫm máu đi vào lịch sử với tên Sự biến Beylerbeyi. Theo mục từ Abdülkadir Şeyhî Efendi trong Bách khoa toàn thư Hồi giáo TDV, shaykh al-Islam bị bãi chức vì sự việc này.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III lên ngôi, mười chín hoàng tử bị siết cổ", "2cd9a8c5"], "d": ["Khi cha là Murad III qua đời, Mehmed III đến Istanbul và lên ngôi vào thứ Sáu ngày 16 Jumada I 1003 (27 tháng 1 năm 1595). Theo Bách khoa toàn thư Hồi giáo TDV, ngay đêm đó mười chín hoàng tử, trong đó bốn người đã trưởng thành (Mustafa, Bayezid, Osman và Abdullah), bị siết cổ chết; đây là vụ giết anh em đông người nhất trong lịch sử Ottoman.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan có thế lực với tư cách thái hậu", "000bec21"], "d": ["Safiye Sultan, vợ của Murad III và mẹ của Mehmed III, khi con trai lên ngôi đã vươn lên vị trí quyết định trong chính trị cung đình với tước vị thái hậu. Theo Bách khoa toàn thư Hồi giáo TDV, trong giai đoạn này thế lực xuất phát từ hậu cung đã đạt tới mức can thiệp trực tiếp vào công việc nhà nước.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Dưới sức ép của quân Janissary, Mehmed III thân chinh xuất quân", "d3c50656"], "d": ["Mặc cho đại tể tướng Damad İbrahim Pasha phản đối, dưới sức ép của quân Janissary, Mehmed III rời Istanbul xuất quân ngày 20 tháng 6 năm 1596, trở thành vị sultan đầu tiên sau Sultan Suleiman Nhà Lập pháp đích thân cầm quân. Theo Bách khoa toàn thư Hồi giáo TDV, điều này có nghĩa là làm sống lại truyền thống thánh chiến (gaza) xưa.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Dịch hạch khởi phát từ những năm 1570 vẫn tiếp tục hoành hành ở Istanbul", "eb4ca37a"], "d": ["Theo mục từ tâun (dịch hạch) trong Bách khoa toàn thư Hồi giáo TDV, trận dịch khởi phát từ những năm 1570 tiếp tục gây ảnh hưởng đến đầu thế kỷ XVII và giáng xuống trước hết là Istanbul, cùng Anatolia, Balkan, Ai Cập và Bắc Phi. Các đợt dịch là mối đe dọa kinh niên thường xuyên làm gián đoạn đời sống cung đình và đô thị.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim chết, phong trào nổi dậy suy yếu", "876ca7a6"], "d": ["Sau thất bại nặng nề tại Sepetli gần Elbistan ngày 12 tháng 8 năm 1601, Karayazıcı Abdülhalim rút lui trong tình trạng bị thương và chết vào năm 1010 (1602). Theo Bách khoa toàn thư Hồi giáo TDV, tin ông chết đến Istanbul vào tháng Ramadan năm 1010 (tháng 2-3 năm 1602); các nguồn cho biết việc ông chết do vết thương hay do chính người của mình sát hại còn là điều tranh cãi.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Tục giết anh em trên thực tế chấm dứt", "9046c607"], "d": ["Khi lên ngôi, khác với các sultan trước, Ahmed I không sai giết em trai là hoàng tử Mustafa mà tha mạng cho người này; quyết định ấy được coi là khởi đầu cho việc trên thực tế áp dụng nguyên tắc ekber-erşed (người cao tuổi và chín chắn nhất kế vị) trong hệ thống kế vị Ottoman. Mục từ \"Mustafa I\" của Bách khoa toàn thư Hồi giáo TDV cho biết từ đó Mustafa sống cách biệt trong cung. Cách làm này trên thực tế chấm dứt những vụ sát hại khi đăng quang kéo dài nhiều thế kỷ.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Đặt móng thánh đường Sultanahmet", "1683262f"], "d": ["Theo lệnh của Ahmed I, lễ đặt móng thánh đường do kiến trúc sư Sedefkâr Mehmed Agha xây dựng tại quảng trường Atmeydanı đã được cử hành. Theo mục từ \"Thánh đường và quần thể Sultan Ahmed\" của Bách khoa toàn thư Hồi giáo TDV, công trình cũng bị người đương thời chỉ trích vì là đại thánh đường của sultan đầu tiên được xây trực tiếp bằng ngân khố mà không gắn với một chiến thắng chinh phục. Quần thể được thiết kế gồm thánh đường cùng madrasa, bếp phát chẩn và lăng mộ.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Osman II \"Trẻ\" bị quân Janissary sát hại (Hâile-i Osmâniye)", "324f6582"], "d": ["Nổi dậy vì những tin đồn rằng sultan định lấy cớ hành hương để rời Istanbul rồi giải tán quân đoàn Janissary, quân Janissary và kỵ binh sipahi phế truất Osman II và cho siết cổ ông trong ngục Yedikule. Theo mục từ \"Osman II\" của Bách khoa toàn thư Hồi giáo TDV, đây là trường hợp đầu tiên trong lịch sử Ottoman một sultan bị sát hại công khai bởi một cuộc binh biến, tạo ra vết rạn nứt sâu sắc trong quan hệ giữa vương triều và quân đội. Những giờ cuối cùng của ông diễn ra như sau: khi nỗ lực ẩn náu tại dinh của agha quân Janissary là Ali Agha không thành, sultan, theo lời TDV, 'một cách bi thảm, đầu trần, áo quần rách nát', bị đặt lên một con ngựa thồ và giữa những lời sỉ nhục nặng nề bị đưa trước hết đến thánh đường Orta Cami, nơi Mustafa I đang ở, rồi chiều cùng ngày đến Yedikule; theo một số sử gia, để chứng minh ông đã chết, tai và mũi ông bị cắt và đem trình mẹ của Mustafa I. Sau sự việc, Mustafa I được đưa lên ngôi lần thứ hai. Sự kiện được gọi là 'Hâile-i Osmâniye' (thảm kịch của Osman) đã làm đảo lộn lâu dài cán cân giữa cung đình và quân đoàn, mở ra những tranh luận về tính chính danh kéo dài suốt thế kỷ.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Mustafa I được đưa lên ngôi lần thứ hai", "34a0b29a"], "d": ["Sau khi quân Janissary sát hại Osman II, vì vương triều không còn thành viên nam trưởng thành nào khác, Mustafa I được đưa lên ngôi lần thứ hai. Theo mục từ \"Mustafa I\" của Bách khoa toàn thư Hồi giáo TDV, triều đại thứ hai này cũng không khác lần trước, ông trên thực tế không thể điều hành việc nước, và việc quản trị nằm trong tay các vezir và thái hậu. Giai đoạn kéo dài mười bốn tháng này kết thúc khi Murad IV lên ngôi năm 1623.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Hỏa hoạn Cibali", "3e42fb08"], "d": ["Đám cháy bùng lên ở Cibali và lan nhanh theo gió đã thiêu rụi một phần lớn Istanbul; theo mục từ \"Istanbul\" của Bách khoa toàn thư Hồi giáo TDV, các nguồn đương thời cho biết hàng nghìn nhà đã cháy. Việc gắn hỏa hoạn với kết cấu nhà gỗ và thói hút thuốc lá trở thành lý do trực tiếp cho lệnh cấm nghiêm ngặt thuốc lá và quán cà phê mà Murad IV sắp ban hành. Thảm họa này chỉ là một trong những đại hỏa hoạn liên tiếp ở Istanbul đương thời.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Lệnh cấm thuốc lá và quán cà phê của Murad IV", "5dd71297"], "d": ["Sau hỏa hoạn Cibali, vì lo ngại cháy nổ và trật tự trị an, Murad IV cấm hút thuốc lá và cấm quán cà phê; người vi phạm bị phạt nặng, kể cả tử hình. Theo mục từ \"Murad IV\" của Bách khoa toàn thư Hồi giáo TDV, sultan theo đuổi chính sách kỷ luật nội bộ chặt chẽ đến mức tự cải trang đi khắp phố phường để giám sát lệnh cấm. Những biện pháp cứng rắn này được đánh giá là một phần nỗ lực của Murad IV nhằm tái lập quyền lực trung ương.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Dịch hạch ở Istanbul", "f33f58c5"], "d": ["Dưới thời Murad IV, Istanbul rúng động vì một trận dịch hạch nặng ảnh hưởng đến một bộ phận đáng kể dân cư; buôn bán trong thành và sinh hoạt thường ngày bị đình trệ nhiều tháng. Mục từ \"Istanbul\" của Bách khoa toàn thư Hồi giáo TDV ghi nhận rằng các đợt dịch tái diễn trong thế kỷ XVII đã tác động nghiêm trọng đến cân bằng dân số của thành phố. Trong thời gian dịch, hoàng cung và tầng lớp thượng lưu đã tạm dời ra các khu vườn và biệt điện ngoài thành.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Chuyến bay bằng đôi cánh của Hezarfen Ahmed Çelebi (theo truyền thuyết)", "df474c04"], "d": ["Theo giai thoại do Evliya Çelebi thuật lại, Hezarfen Ahmed Çelebi đã nhảy từ tháp Galata với đôi cánh tự chế và lượn được đến tận Üsküdar; tuy tính xác thực lịch sử còn gây tranh cãi, câu chuyện đã trở thành biểu tượng của trí tưởng tượng kỹ thuật. Sultan ban đầu ban thưởng cho Hezarfen, nhưng sau đó, vì tiếng vang mà sự việc gây ra, đã đày ông đến Algiers.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Cinci Hoca Hüseyin Efendi có thế lực trong cung", "41d21572"], "d": ["Hüseyin Efendi, một thầy bùa chú được gọi vào cung để chữa những rối loạn tinh thần của sultan Ibrahim, chẳng bao lâu đã giành được lòng tin của nhà vua và thăng tiến đến chức kazasker Anatolia. Theo mục từ \"Hüseyin Efendi, Cinci Hoca\" (thầy trừ tà) của Bách khoa toàn thư Hồi giáo TDV, ông dùng thế lực này để tích lũy của cải và can thiệp vào các sự kiện chính trị đương thời. Sau khi Ibrahim chết, ông bị tước mọi chức vụ và bị xử tử năm 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Kemankeş Mustafa Pasha bị xử tử", "0ecc8030"], "d": ["Kemankeş Mustafa Pasha, đại tể tướng từ thời Murad IV và là người đã đem lại cho ngân khố một khoản thặng dư đáng kể nhờ các cải cách tài chính, bị siết cổ xử tử khi các đối thủ trong cung tác động đến Ibrahim và buộc tội ông kích động một cuộc nổi loạn của quân Janissary. Theo mục từ \"Kemankeş Mustafa Pasha\" của Bách khoa toàn thư Hồi giáo TDV, cuộc hành quyết diễn ra ngày 21 Dhu'l-Qa'da 1053 / 31 tháng 1 năm 1644: Kemankeş Kara Mustafa Pasha bị đao phủ Kara Ali siết cổ tại chợ Hocapaşa và được chôn trong lăng của chính ông ở Çarşıkapı. Cái chết của ông được nhắc đến như một ví dụ nổi bật về sự bất ổn của chức đại tể tướng đương thời, và nó chấm dứt thời kỳ cải cách chặt chẽ ngắn ngủi.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Divan quyết định chiến dịch Crete và hạm đội lên đường", "9076827e"], "d": ["Hội đồng Hoàng gia (Divan-ı Hümayun) quyết định mở một chiến dịch quy mô lớn đánh đảo Crete thuộc Venice, và hạm đội Ottoman dưới quyền kapudan pasha rời Istanbul tiến về Crete. Theo mục từ \"Crete\" của Bách khoa toàn thư Hồi giáo TDV, quyết định này là khởi điểm chính trị của một thời kỳ vây hãm và chiến tranh dài kéo dài khoảng hai mươi lăm năm. Là sáng kiến đối ngoại lớn nhất thời Ibrahim, việc mở chiến dịch đã gây tranh luận rộng rãi trong giới đại thần.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Mehmed IV lên ngôi lúc bảy tuổi", "a197a3bc"], "d": ["Ngay sau khi Ibrahim bị phế truất, con trai ông là Mehmed, mới bảy tuổi, được đưa lên ngôi, trở thành sultan với hiệu Mehmed IV. Theo mục từ \"Mehmed IV\" của Bách khoa toàn thư Hồi giáo TDV, việc lên ngôi khi còn nhỏ như vậy làm gay gắt cuộc tranh giành thế lực trong cung giữa bà nội là Kösem Sultan và mẹ là Turhan Sultan. Cuộc đấu quyền lực này sẽ kết thúc bằng việc Kösem Sultan bị sát hại năm 1651.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Cải cách ngân sách cân bằng của Tarhuncu Ahmed Pasha", "376fc7f2"], "d": ["Để vượt qua cuộc khủng hoảng tài chính do những năm chiến tranh dài gây ra, đại tể tướng Tarhuncu Ahmed Pasha thực hiện một chương trình tiết kiệm khắc nghiệt bao gồm cả chi phí cung đình và lập ra ngân sách cân bằng đầu tiên được biết đến trong lịch sử Ottoman (bản đề án của Tarhuncu). Theo mục từ \"Tarhuncu Ahmed Pasha\" của Bách khoa toàn thư Hồi giáo TDV, cải cách này đem lại cho ngân khố một khoản thặng dư đáng kể nhưng gây bất mãn rộng khắp trong giới cung đình và quan lại cấp cao. Sự bất mãn này một năm sau đã dẫn đến việc ông bị xử tử.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Sự biến Cây Tiêu huyền (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Theo mục từ Çınar Vak'ası (Sự biến Cây Tiêu huyền) của Bách khoa toàn thư Hồi giáo TDV, quân Janissary và sipahi trở về từ chiến dịch Crete mà không được trả lương đã nổi dậy ở Istanbul, đòi xử tử các quan chức mà họ buộc tội tham nhũng. Đề nghị tịch biên và lưu đày của đại tể tướng Zurnazen Mustafa Pasha không được chấp nhận; trước hết ba viên chức, rồi gần ba mươi quan chức bị xử tử và xác bị treo lên các cây tiêu huyền ở quảng trường Sultanahmet. Vì thế sự việc được gọi là Sự biến Cây Tiêu huyền.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Köprülü Mehmed Pasha được bổ nhiệm làm đại tể tướng với điều kiện", "3a6b7f8f"], "d": ["Theo mục từ Köprülü Mehmed Pasha của Bách khoa toàn thư Hồi giáo TDV, Köprülü Mehmed Pasha, gần tám mươi tuổi, chỉ nhận con ấn sau khi thái hậu Turhan Sultan và Mehmed IV chấp nhận những điều kiện nặng nề của ông, gồm không can thiệp vào việc bổ nhiệm và không tin những lời nói chống lại ông. Ông thay Boynueğri Mehmed Pasha nhậm chức ngày 26 Dhu'l-Qa'da 1066 và bắt tay tái lập kỷ cương nhà nước một cách cứng rắn.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Köprülü Mehmed Pasha trấn áp phong trào Kadizadeli", "5ec3ce84"], "d": ["Theo mục từ Kadızâdeliler của Bách khoa toàn thư Hồi giáo TDV, ngay khi nhậm chức, Köprülü Mehmed Pasha đã giải quyết cuộc xung đột tôn giáo giữa phe quanh Kadızâde Mehmed Efendi và những người theo các dòng tu Sufi. Sau khi hỏi ý kiến giới ulema, ông xin được sắc lệnh tử hình đối với các thủ lĩnh phong trào là Üstüvânî Mehmed Efendi, Türk Ahmed và Divâne Mustafa, nhưng án này được đổi thành lưu đày và cả ba bị đưa đến Síp; như vậy giai đoạn thứ hai của phong trào kết thúc.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Đại hỏa hoạn ở Istanbul: dinh Ağakapısı bị cháy", "b9253b66"], "d": ["Theo mục từ Ağakapısı của Bách khoa toàn thư Hồi giáo TDV, trong trận đại hỏa hoạn bùng phát tháng 7 năm 1660 dưới thời Mehmed IV, Ağakapısı, tổng hành dinh chính thức của agha quân Janissary, bị cháy rụi và sau đó được xây lại. Đây là một trong những đại hỏa hoạn đô thị liên tiếp giáng xuống Istanbul đương thời.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Köprülüzade Fazıl Ahmed Pasha được bổ nhiệm làm đại tể tướng", "c1999b5c"], "d": ["Theo mục từ Köprülüzâde Fâzıl Ahmed Pasha của Bách khoa toàn thư Hồi giáo TDV, khi cha là Köprülü Mehmed Pasha qua đời, ông được đưa lên làm đại tể tướng ngày 8 Rabi' I 1072 (1 tháng 11 năm 1661). Khác với cha, Fazıl Ahmed Pasha nổi tiếng là người ôn hòa, sùng đạo, bảo trợ học giả và nghệ sĩ; trong hơn mười lăm năm làm đại tể tướng, ông cho lập các thư viện và cơ sở từ thiện ở Istanbul cùng những vùng đất mới chinh phục.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Vani Mehmed Efendi được bổ nhiệm làm giảng sư thánh đường Yeni Cami và thầy dạy của sultan", "7ea6aaae"], "d": ["Theo mục từ Mehmed Efendi, Vânî của Bách khoa toàn thư Hồi giáo TDV, khi Köprülüzade Fazıl Ahmed Pasha làm đại tể tướng, Vani Mehmed Efendi được mời đến Istanbul, ra mắt Mehmed IV và chẳng bao lâu được sultan đặc biệt quan tâm. Năm 1665, ông được cử làm giảng sư (vaiz) của thánh đường Yeni Cami và thầy dạy của sultan, trở thành một trong những giáo sĩ có ảnh hưởng nhất trong cung.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Merzifonlu Kara Mustafa Pasha được bổ nhiệm làm đại tể tướng", "3d1e836c"], "d": ["Theo mục từ Merzifonlu Kara Mustafa Pasha của Bách khoa toàn thư Hồi giáo TDV, khi Fazıl Ahmed Pasha qua đời, ông được đưa lên làm đại tể tướng ngày 28 Sha'ban 1087 (5 tháng 11 năm 1676). Là con rể và người được gia tộc Köprülü đào tạo, có kinh nghiệm quản trị nhà nước lâu năm, Merzifonlu trở thành một trong những đại tể tướng mạnh và có ảnh hưởng nhất của Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Vani Mehmed Efendi qua đời nơi lưu đày", "cda714aa"], "d": ["Theo mục từ Mehmed Efendi, Vânî của Bách khoa toàn thư Hồi giáo TDV, Vani Mehmed Efendi, được coi là một trong những người chủ chốt thuyết phục sultan chấp thuận chiến dịch Vienna, sau khi chiến dịch kết thúc bằng thảm bại đã mất sủng ái do sức ép dư luận và bị đày đến thị trấn Kestel thuộc Bursa. Ông qua đời tại đây ngày 14 Dhu'l-Qa'da 1096 (12 tháng 10 năm 1685) và được an táng ở lối vào thánh đường do chính ông xây.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Köprülüzade Fazıl Mustafa Pasha được bổ nhiệm làm đại tể tướng và các cải cách tài chính", "b048570e"], "d": ["Theo mục từ Köprülüzâde Fâzıl Mustafa Pasha của Bách khoa toàn thư Hồi giáo TDV, được đưa lên làm đại tể tướng ngày 11 Muharram 1101 (25 tháng 10 năm 1689), Fazıl Mustafa Pasha tổ chức lại cách thu thuế jizya theo các nguyên tắc Sharia, chống lạm phát đồng mangır và củng cố ngân khố bằng cách chuyển nguồn lực từ các cơ quan trong cung. Ông còn tăng cường bộ máy địa phương bằng những viên chức đáng tin cậy và cho lập các hội đồng địa phương tương tự divan trung ương.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Chế độ malikâne (bao thuế trọn đời) được áp dụng", "316b8426"], "d": ["Theo mục từ Mâlikâne của Bách khoa toàn thư Hồi giáo TDV, trong phần tư cuối thế kỷ XVII, chi phí chiến tranh tăng và nguồn thu giảm do mất đất đã đẩy ngân khố vào khủng hoảng tài chính nghiêm trọng. Chế độ malikâne được áp dụng năm 1106 (1695) cấp cho người bao thuế quyền thu một khoản thuế cố định trọn đời, nhờ đó khuyến khích bảo vệ sản xuất thay vì bóc lột ngắn hạn.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Mustafa II lên ngôi", "b53656c7"], "d": ["Theo mục từ Mustafa II của Bách khoa toàn thư Hồi giáo TDV, Mustafa II lên ngôi lúc ba mươi mốt tuổi, tuyên bố triều đại của mình mà không đợi đại tể tướng và shaykh al-Islam chuẩn thuận; lễ đeo gươm được cử hành vài ngày sau tại thánh đường Eski Cami. Lên ngôi trong thời kỳ chiến tranh trên nhiều mặt trận còn tiếp diễn sau thảm bại Vienna, ông là vị sultan cuối cùng trong lịch sử Ottoman đích thân xuất chinh.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Feyzullah Efendi lần thứ hai được bổ nhiệm làm shaykh al-Islam", "1cf14cff"], "d": ["Theo mục từ Feyzullah Efendi, Seyyid của Bách khoa toàn thư Hồi giáo TDV, sau khi Mustafa II lên ngôi, ông được đưa lên chức shaykh al-Islam lần thứ hai ngày 11 Shawwal 1106 (25 tháng 5 năm 1695). Ảnh hưởng của ông đối với sultan ngày càng tăng trong nhiệm kỳ kéo dài hơn tám năm này.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi đưa các con trai lên chức cao và sự phẫn nộ tích tụ", "a6398280"], "d": ["Theo mục từ Feyzullah Efendi, Seyyid của Bách khoa toàn thư Hồi giáo TDV, vị shaykh al-Islam đã nhận được từ Mustafa II một sắc lệnh chưa từng có quy định con trai ông là Fethullah Efendi sẽ kế nhiệm ông làm shaykh al-Islam, và ông đưa thân thích còn trẻ vào các chức vụ cao. Những việc làm này gây bất mãn rộng khắp trong giới ulema, quân đội và dân chúng Istanbul; kết hợp với tin đồn thủ đô sẽ dời về Edirne, chúng dọn đường cho Sự biến Edirne năm 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Sự biến Edirne bắt đầu", "5a106458"], "d": ["Theo mục từ \"Sự biến Edirne\" của TDV, phong trào khởi đầu bằng cuộc nổi dậy của binh lính không được trả lương đã nhanh chóng biến thành cuộc nổi loạn rộng lớn với sự tham gia của quân Janissary, học sinh madrasa, thợ thủ công, tiểu thương và dân chúng. Mục tiêu chính của cuộc nổi loạn là shaykh al-Islam Feyzullah Efendi, người bị cho là can thiệp quá mức vào việc nước. Một đám đông khoảng 60.000 người đã tiến từ Istanbul đến Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Nevşehirli Damad İbrahim Pasha làm đại tể tướng", "8d627a6f"], "d": ["Theo mục từ \"Damad İbrâhim Pasha, Nevşehirli\" của TDV, giữa lúc đang đàm phán hòa bình với Áo, ông được đưa lên chức đại tể tướng ngày 8 Jumada II 1130 (9 tháng 5 năm 1718) và vừa được bổ nhiệm đã hướng tới các cuộc đàm phán kết thúc chiến tranh; hai tháng sau, Hiệp ước Passarowitz được ký (21 tháng 7 năm 1718). Theo lời TDV, ông 'muốn giải quyết các vấn đề xã hội và tài chính, khao khát một thời kỳ hòa bình làm người ta quên đi những cuộc chiến nhiều năm toàn kết thúc bằng thất bại'. Ông cải cách tài chính, giảm lương quân lính và tạo ra khoản thặng dư đáng kể cho ngân khố. Nhiệm kỳ đại tể tướng kéo dài mười hai năm của ông là khung chính trị của thời kỳ mang tên đó (Thời đại Hoa Tulip).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Thành lập đội cứu hỏa Tulumbacı", "f58b0d97"], "d": ["Theo mục từ \"Tulumbacı\" của TDV, do Gerçek Dâvud, người trở về từ chiến dịch Morea 1715, đã lập thành tích dập lửa bằng máy bơm trong các vụ cháy ở Istanbul, đại tể tướng Nevşehirli Damad İbrahim Pasha giao cho ông lập một đội cứu hỏa chính thức. Đội được thành lập tại doanh trại Acemi Oğlanlar (lính tân binh) với sáu sĩ quan và năm mươi lính, đạt 150 người năm 1724 và 461 người năm 1755. Dâvud đứng đầu đội cho đến khi qua đời năm 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Xây dựng biệt điện Sâdâbâd", "aec9c65e"], "d": ["Theo mục từ \"Sâdâbâd\" của TDV, bên bờ suối Kağıthane đã dựng lên một quần thể vui chơi và dạo cảnh rộng lớn gồm biệt điện, kênh đào, đài phun nước và các lầu nghỉ, lấy cảm hứng từ kiến trúc cung đình Pháp. Trở thành chốn vui chơi được ưa chuộng nhất đương thời, Sâdâbâd được bất tử hóa trong thơ của thi sĩ Nedim. Quần thể bị phá hủy phần lớn trong cuộc nổi loạn Patrona Halil năm 1730.", "2698478e"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["İbrahim Müteferrika được phép lập nhà in", "0659dd0a"], "d": ["Theo mục từ \"İbrâhim Müteferrika\" của TDV, bằng sắc lệnh của Ahmed III và fatwa của shaykh al-Islam Yenişehirli Abdullah Efendi, việc lập nhà in tiếng Thổ đầu tiên được cho phép. Nhà in đi vào hoạt động tại khu Yavuzselim ở Istanbul. Cho đến khi qua đời năm 1747, Müteferrika đã in mười bảy tác phẩm gồm hai mươi ba tập.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Hoàn thành cuốn sách in đầu tiên, từ điển Vankulu", "684700e8"], "d": ["Theo mục từ \"İbrâhim Müteferrika\" của TDV, tác phẩm đầu tiên của nhà in, bản dịch tiếng Thổ của bộ Sihah của al-Jawhari (Từ điển Vankulu), được hoàn thành đầu năm 1729. Đây là cuốn sách đầu tiên in bằng chữ Ả Rập trên lãnh thổ Ottoman và được coi là khởi đầu của lịch sử in ấn Thổ Nhĩ Kỳ.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Nevşehirli Damad İbrahim Pasha bị xử tử", "50c64341"], "d": ["Theo mục từ \"Damad İbrâhim Pasha, Nevşehirli\" của TDV, thi thể vị đại tể tướng bị giết trong hoàng cung giữa cuộc nổi loạn Patrona Halil bị kéo lê trên đường phố Istanbul rồi bỏ gần đài phun nước Ahmed III ở quảng trường Sultanahmet. Nhiệm kỳ đại tể tướng mười hai năm của ông và Thời đại Hoa Tulip như vậy kết thúc trong máu.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Ahmed III thoái vị, Mahmud I lên ngôi", "a43f5d40"], "d": ["Theo mục từ \"Mahmud I\" của TDV, trước sức ép của quân nổi loạn, Ahmed III thoái vị sau khi nhận được sự bảo đảm cho bản thân và các con, rồi đích thân đưa cháu trai là hoàng tử Mahmud lên ngôi. Ngồi lên ngai với lời khuyên của người bác \"hãy tự nắm lấy việc nước, đừng tin ai\", Mahmud I việc đầu tiên bắt tay vào là bẻ gãy ảnh hưởng của nhóm nổi loạn đã đưa mình lên ngôi.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Humbaracı Ahmed Pasha cải tổ binh chủng pháo binh", "ea3a7c64"], "d": ["Theo mục từ \"Humbaracı\" (lính súng cối) của TDV, Ahmed Pasha, sĩ quan gốc Pháp cải sang đạo Hồi, dưới thời đại tể tướng Hekimoğlu Ali Pasha đã bắt tay cải tổ tổ chức lính súng cối hưởng lương theo kiểu châu Âu. Ông lập một cơ cấu mới gồm 601 người trực thuộc đại tể tướng, trong đó 300 người hưởng lương và 301 người hưởng thái ấp timar. Bằng công nghệ đương thời, ông cho sản xuất 100 khẩu súng cối và 50.000 quả đạn.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Lập Hendesehâne (hình mẫu đầu tiên của trường kỹ thuật)", "a77ed1f3"], "d": ["Theo mục từ \"Mahmud I\" của TDV, Humbaracı Ahmed Pasha lập tại Üsküdar trường Hendesehâne (còn gọi là Humbarahâne) và dạy cho các học viên được chọn trong số người hầu cận cung đình và lính bostancı một nền quân sự học dựa trên toán và hình học. Cơ sở này được coi là hình mẫu đầu tiên của các trường kỹ thuật phát triển về sau.", "84b5af85"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Dịch hạch bùng phát ở Istanbul", "9fa82b56"], "d": ["Theo mục từ \"Tâun\" của TDV, trận dịch hạch hoành hành tại vùng đất Hồi giáo trong giai đoạn 1739-1743 cũng giáng xuống Istanbul vào thời gian này. Mục từ nêu rằng các đợt dịch thế kỷ 18 diễn biến tương đối nhẹ hơn so với các thế kỷ trước. Trong số các đợt dịch còn kể đến những năm 1713, 1719, 1728-1729 và 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Hỏa hoạn Hocapaşa", "321c7d0d"], "d": ["Theo mục từ \"Thánh đường Fatma Sultan\" của TDV, đám cháy Hocapaşa bùng lên trong đêm đã tàn phá Bâb-ı Âli và vùng quanh đó; người ta cho rằng thánh đường Fatma Sultan trong khu vực cũng bị hư hại vì đám cháy này. Là một trong những đại hỏa hoạn giáng xuống Istanbul dưới thời Osman III, thảm họa gây tàn phá nặng nề tại trung tâm thương mại và hành chính của thành phố.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Koca Ragıp Mehmed Pasha làm đại tể tướng", "a1846910"], "d": ["Nổi tiếng là nhà thơ và nhà ngoại giao, Ragıp Pasha được Osman III đưa lên chức đại tể tướng (khi Osman III qua đời vào tháng 10 năm 1757, ông tiếp tục tại chức và nhận con ấn mới từ Mustafa III). Trong lúc Chiến tranh Bảy năm diễn ra, ông theo đuổi chính sách đối ngoại cân bằng, giữ Đế quốc Ottoman đứng ngoài các cuộc xung đột ở châu Âu. Trong sáu năm làm đại tể tướng, ông cũng chú trọng các hoạt động văn hóa như lập thư viện.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Ragıp Pasha qua đời", "6bc19323"], "d": ["Ragıp Pasha qua đời sau sáu năm làm đại tể tướng. Cái chết của ông chấm dứt nhiệm kỳ đại tể tướng lâu dài và cân bằng nhất dưới thời Mustafa III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Đại động đất Istanbul và thánh đường Fatih sụp đổ", "2475b4dc"], "d": ["Theo mục từ \"Thánh đường và quần thể Fatih\" của TDV, trong trận đại động đất năm 1766, mái vòm chính của thánh đường sụp đổ hoàn toàn, các bức tường hư hại đến mức không thể sửa chữa. Theo lệnh của Mustafa III, công cuộc xây lại bắt đầu năm 1767 dưới sự chỉ đạo của các kiến trúc sư Sarım İbrahim Efendi và İzzet Mehmed Bey, hoàn thành năm 1771 với thiết kế mới khác bản cũ.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Thử nghiệm chóng vánh về trường pháo binh do Baron de Tott dẫn dắt", "4192260c"], "d": ["Theo mục từ \"Mühendishâne-i Bahrî-i Hümâyun\" (Trường Kỹ thuật Hải quân Hoàng gia) của TDV, những thất bại trong chiến tranh Ottoman–Nga 1768 cho thấy nhu cầu đào tạo kỹ thuật quân sự; trường pháo binh chóng tàn được mở với sự góp sức của sĩ quan Pháp Baron de Tott đã đi vào hoạt động tháng 10 năm 1772 nhưng không mang lại hiệu quả. Thử nghiệm này được coi là tiền thân của Trường Kỹ thuật Hải quân Hoàng gia được lập năm 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III lên ngôi", "00d046d9"], "d": ["Khi Abdülhamid I qua đời, cháu trai ông là Selim III lên ngôi. Theo mục từ Selim III trong Bách khoa toàn thư Hồi giáo TDV, vị sultan mới, từ thời còn là hoàng tử đã quan tâm đến việc cải tổ quân đội theo kiểu châu Âu, ít lâu sau khi lên ngôi bắt đầu cho soạn một chương trình đổi mới triệt để. Vài năm sau, chương trình này được gọi là Nizam-ı Cedid (Trật tự Mới).", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Bắt đầu soạn chương trình cải cách Nizam-ı Cedid", "eff78a68"], "d": ["Selim III cho soạn một chương trình đổi mới toàn diện dựa trên các bản tấu trình mà ông yêu cầu từ các đại thần và chuyên gia nước ngoài. Theo mục từ Nizâm-ı Cedîd trong Bách khoa toàn thư Hồi giáo TDV, chương trình này không chỉ giới hạn ở việc lập một quân đội mới mà trở thành phong trào cải cách rộng lớn bao gồm cả tài chính, cai trị địa phương và ngoại giao. Trong mười lăm năm sau đó, chương trình vừa có người ủng hộ vừa có người chống đối.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Lập đại sứ quán thường trú tại các thủ đô châu Âu", "2e9dc8a1"], "d": ["Lần đầu tiên trong lịch sử Đế quốc Ottoman, Selim III phái các đại sứ thường trú đến những trung tâm lớn của châu Âu. Theo mục từ Elçi (Sứ thần) trong Bách khoa toàn thư Hồi giáo TDV, bước đi này đem lại một bộ máy thường trực cho nền ngoại giao Ottoman vốn đến lúc đó chỉ được tiến hành qua các phái bộ tạm thời, đi một lần. Nhiệm vụ chính của các đại sứ quán mới là báo cáo đều đặn về Istanbul những diễn biến chính trị và quân sự ở châu Âu.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Lập ngân khố İrad-ı Cedid (Nguồn thu Mới)", "ae5c8ce2"], "d": ["Một ngân khố riêng được lập để trang trải chi phí cho quân đội Nizam-ı Cedid và chương trình cải cách. Theo mục từ Esham trong Bách khoa toàn thư Hồi giáo TDV, nguồn thu của ngân khố mới gồm việc nhà nước trực tiếp khai thác một số nguồn thu bao thầu (mukataa) và việc kiểm soát việc bán esham (cổ phần trái quyền thu nhập). Quy định này là một nỗ lực tạo nguồn lực mới ngoài hệ thống tài chính truyền thống.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Cuộc nổi loạn Kabakçı Mustafa bắt đầu", "b98eee17"], "d": ["Sự bất mãn tích tụ đối với Nizam-ı Cedid bùng nổ qua cuộc nổi dậy của lính yamak (phụ trợ) do Kabakçı Mustafa cầm đầu. Theo mục từ Cuộc nổi loạn Kabakçı trong Bách khoa toàn thư Hồi giáo TDV, quân nổi loạn nhanh chóng nắm quyền kiểm soát Istanbul và đòi đầu các đại thần ủng hộ Nizam-ı Cedid. Chỉ sau vài ngày, cuộc nổi dậy kết thúc bằng việc Selim III bị phế truất.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III bị phế truất", "ff2c30ec"], "d": ["Dưới sức ép của cuộc nổi loạn Kabakçı Mustafa, với fatwa lấy từ shaykh al-Islam, Selim III bị phế truất. Theo mục từ Selim III trong Bách khoa toàn thư Hồi giáo TDV, quyết định này đánh dấu thời điểm thời kỳ cải cách kéo dài mười tám năm trên thực tế chấm dứt; quân đội Nizam-ı Cedid cũng sớm bị giải tán. Selim bị quản thúc tại Cung điện Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV lên ngôi", "8f1ac86c"], "d": ["Ngay sau khi Selim III bị phế truất, cháu họ ông là Mustafa IV được tôn làm sultan. Theo mục từ Mustafa IV trong Bách khoa toàn thư Hồi giáo TDV, vị sultan mới khởi đầu triều đại dưới ảnh hưởng của các giới chống Nizam-ı Cedid vốn ủng hộ cuộc nổi loạn. Giai đoạn ngắn ngủi này là một thời kỳ bất ổn, quyền lực trung ương suy yếu trầm trọng.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pasha đem quân tiến vào Istanbul", "0cad3dea"], "d": ["Alemdar Mustafa Pasha, ayan (hào trưởng địa phương) xứ Ruse, đem quân đến trước Istanbul nhằm đưa Selim III trở lại ngôi. Theo mục từ Alemdar Mustafa Pasha trong Bách khoa toàn thư Hồi giáo TDV, chính Mustafa IV đã đón ông khi ông vào thành; nhưng chỉ trong vài ngày, cán cân quyền lực trong cung sẽ thay đổi hoàn toàn. Việc tiến vào này khởi đầu một chuỗi sự kiện kết thúc bằng cái chết của Selim và một cuộc lên ngôi mới.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III bị sát hại", "e452f5f6"], "d": ["Ngày Alemdar Mustafa Pasha chiếm Bâb-ı Âli, Selim III bị giết trong cung theo lệnh Mustafa IV. Theo mục từ Selim III trong Bách khoa toàn thư Hồi giáo TDV, đây là quyết định được đưa ra nhằm ngăn chặn nỗ lực đưa một sultan đã bị phế truất trở lại ngôi. Cái chết của Selim dẫn đến việc Mahmud lên ngôi ngay trong ngày.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II lên ngôi", "661c1974"], "d": ["Sau khi Selim III bị sát hại, Mahmud, người nam duy nhất còn lại của vương triều, lên ngôi nhờ sự ủng hộ của Alemdar Mustafa Pasha. Theo mục từ Mahmud II trong Bách khoa toàn thư Hồi giáo TDV, vị sultan mới trải qua những tháng đầu của triều đại dưới sự giám hộ của Alemdar, người đã đưa ông lên ngôi, trong nỗ lực tái lập cân bằng giữa các ayan và trung ương. Giai đoạn này mở đầu cho quá trình cải cách triệt để trong hai mươi năm sau đó.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Lập quân đội Sekban-ı Cedid (Sekban Mới)", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasha cho lập một quân đội mới trang bị theo kiểu châu Âu thay cho Nizam-ı Cedid đã bị giải tán. Theo mục từ Sekbân-ı Cedîd trong Bách khoa toàn thư Hồi giáo TDV, lực lượng gồm ba trung đoàn này bị quân Janissary coi là mối đe dọa trực tiếp và chỉ vài tháng sau khi thành lập đã bị xóa sổ trong một cuộc nổi loạn của quân Janissary.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Brăila thất thủ — lỗ hổng lớn đầu tiên trên phòng tuyến sông Danube", "ee519321"], "d": ["Trong chiến tranh với Nga khởi phát năm 1806, pháo đài Brăila trên bờ bắc sông Danube bị quân Nga dưới quyền Bá tước Kamenski vây hãm và nã pháo. Bên trong có 4100 bộ binh, 1100 kỵ binh và 260 khẩu pháo; vì thiếu lương thực, pháo đài đầu hàng Tướng Essen. Như vậy đầu phía bắc của phòng tuyến Danube bị mở toang.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Ruse đầu hàng — bờ nam sông Danube cũng dần mất", "084062e8"], "d": ["Ruse chống cự cuộc vây hãm dài và đẫm máu của quân Nga dưới quyền Bá tước Kamenski; thành đầu hàng với điều kiện đội đồn trú và dân thường được rời đi an toàn. Việc thành trì kiên cố nhất trên bờ nam sông Danube thất thủ đã xoay cục diện chiến tranh có lợi cho Nga.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Lập đội Eşkinci (Eşkinci Ocağı)", "67c56759"], "d": ["Mahmud II cho lập một đơn vị mới gồm lính được tuyển từ trong quân đoàn Janissary để được thao luyện theo kiểu châu Âu. Theo mục từ Eşkinci Ocağı trong Bách khoa toàn thư Hồi giáo TDV, đơn vị bắt đầu thao luyện ngày 12 tháng 6 năm 1826, nhưng quân Janissary xem đó là dấu chấm hết cho quân đoàn của mình. Cuộc nổi loạn bùng nổ ba ngày sau cũng kết thúc đời tồn tại ngắn ngủi của đội Eşkinci.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Lập quân đội Asakir-i Mansure-i Muhammediyye (Đạo quân Chiến thắng của Muhammad)", "14b84a7e"], "d": ["Ngay sau khi bãi bỏ quân đoàn Janissary, Mahmud II cho lập một quân đội mới, chính quy và được huấn luyện theo kiểu châu Âu để thay thế. Theo mục từ Asâkir-i Mansûre-i Muhammediyye trong Bách khoa toàn thư Hồi giáo TDV, khác với các thử nghiệm trước, quân đội này với hệ thống cấp bậc, chương trình huấn luyện và chế độ lương của mình đã trở thành một thiết chế lâu dài. Về sau, nó chuyển thành quân đội Nizamiye của thời Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Dòng tu Bektashi bị đóng cửa", "f7d9a367"], "d": ["Cùng lúc với việc bãi bỏ quân đoàn Janissary, dòng tu Bektashi, vốn được biết là có liên hệ tôn giáo với quân đoàn này, cũng bị cấm. Theo mục từ Bektaşîlik trong Bách khoa toàn thư Hồi giáo TDV, một số trưởng lão của các tu viện nhỏ bị xử tử, còn trưởng lão tu viện Hacı Bektaş bị đày đến Amasya và các tu viện được giao cho dòng Naqshbandi quản lý. Dù chịu đòn nặng nề này, dòng tu vẫn bí mật duy trì tổ chức.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Vụ chiếc quạt — cái cớ để chiếm đóng", "e949001e"], "d": ["Trong cuộc tiếp kiến căng thẳng vì Pháp không trả món nợ lúa mì cũ đối với Algiers, Dey Hüseyin dùng chiếc quạt cầm tay đánh lãnh sự Pháp Deval. Vụ việc phát sinh từ tranh chấp nợ nần này trở thành cái cớ chính thức cho cuộc chiếm đóng bắt đầu ba năm sau.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Pháp phong tỏa bờ biển Algeria — cuộc vây khốn kéo dài ba năm", "d0ba97a5"], "d": ["Sau vụ chiếc quạt, Pháp phong tỏa bờ biển Algeria. Cuộc phong tỏa kéo dài ba năm; thương mại đường biển và các nguồn thu của Ocak bị cạn kiệt, sức kháng cự bị bào mòn trước cả khi cuộc chiếm đóng bắt đầu.", "79d27be2"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Brăila thất thủ lần thứ hai — Sa hoàng Nikolai trước pháo đài", "eb6a8741"], "d": ["Brăila, được trả lại cho Ottoman năm 1812 và được gia cố lại trong những năm 1817-1818, bị vây vào tháng 4 khi bên trong có 4000 lính phòng thủ và 278 khẩu pháo. Chỉ huy giữ thành Ebubekir Pasha lập một phòng tuyến mới; cuối tháng 5, Sa hoàng Nikolai I đích thân đến trước pháo đài. Thành phố bị Nga chiếm đóng, nhưng theo Hiệp ước Edirne (Adrianople) sẽ được trả lại và để cho thân vương quốc Wallachia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Mũ fez được quy định là mũ đội đầu chính thức", "f55be4eb"], "d": ["Thay đổi triệt để trang phục của viên chức và binh lính, Mahmud II quy định mũ fez thay khăn xếp làm mũ đội đầu chính thức. Theo mục từ Fes trong Bách khoa toàn thư Hồi giáo TDV, quyết định này được công bố bằng một thánh chỉ và được thi hành cùng với các cải cách kiểu phương Tây của Asakir-i Mansure-i Muhammediyye. Sự thay đổi cũng có nghĩa là chấm dứt hệ thống thứ bậc trang phục truyền thống.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Akhaltsikhe bị nhượng cho Nga — mất trung tâm của tỉnh Çıldır", "e2e00b2a"], "d": ["Akhaltsikhe, thuộc quyền cai trị của Ottoman từ trận Çıldır năm 1578 và là trung tâm của tỉnh Çıldır, đã bị nhượng cho Nga theo Hiệp ước Edirne (Adrianople) ký khi chiến tranh 1828-1829 kết thúc. Việc mất thành phố gây nỗi đau sâu sắc trong dân chúng và trở thành đề tài của nhiều bài ai ca. Với sự kiện này, Akhalkalaki, Zazalo và Ts'q'altbila (vùng Akhaltsikhe–Akhalkalaki) chuyển sang Nga.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Cuộc đổ bộ Sidi Fredj — quân Pháp trên đất Algeria", "33327553"], "d": ["Sau ba năm phong tỏa, đạo quân đổ bộ Pháp do Bá tước de Bourmont chỉ huy đổ quân lên vịnh Sidi Fredj ở phía tây Algiers. Lực lượng tiến về thành phố, trong ba tuần đã phá vỡ phòng tuyến; ngày 4 tháng 7, pháo đài Hoàng đế khống chế thành phố thất thủ, và hôm sau Dey Hüseyin đầu hàng.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Dey Hüseyin bị lưu đày — Ocak Algiers trên thực tế cáo chung", "e122403b"], "d": ["Theo điều kiện đầu hàng, Hüseyin, dey cuối cùng của Algiers, bị đưa ra khỏi thành cùng gia đình và tài sản, rồi được đưa đến Napoli. Như vậy chấm dứt chế độ cai quản của Ocak, vốn quy phục Selim I \"Nghiêm Khắc\" năm 1519 và suốt ba trăm năm là căn cứ hải quân mạnh nhất của Ottoman ở Địa Trung Hải.", "bf7169cf"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Lập tổ chức Redif-i Asakir-i Mansure (quân dự bị)", "15947493"], "d": ["Tổ chức Redif, một lực lượng dự bị hỗ trợ Asakir-i Mansure-i Muhammediyye, được lập theo điều lệ ngày 8 tháng 7 năm 1834. Theo mục từ Redif trong Bách khoa toàn thư Hồi giáo TDV, dưới sự điều hành của serasker (tổng tư lệnh) Koca Hüsrev Pasha, các tiểu đoàn khoảng một nghìn bốn trăm người mỗi đơn vị được lập tại các kazâ ở địa phương. Tổ chức này được thiết kế để hỗ trợ cả an ninh địa phương mà không phải nhập ngũ thường trực.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Lập Bộ Ngoại giao", "750c6c7d"], "d": ["Mahmud II bãi bỏ chức Reisülküttab (chánh thư lại), vốn phụ trách đối ngoại, và thay bằng Bộ Ngoại giao. Theo mục từ Hariciye Nezâreti trong Bách khoa toàn thư Hồi giáo TDV, Mehmed Akif Pasha được cử làm bộ trưởng đầu tiên của bộ mới, và cơ quan bắt đầu hoạt động tại dinh của Rıfat Bey, đại sứ tại Vienna. Quy định này mở đầu cho việc tiến hành chính sách đối ngoại Ottoman trên cơ sở bộ hiện đại.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Lập Hội đồng Tối cao về Pháp chế (Meclis-i Vâlâ-yı Ahkâm-ı Adliyye)", "69db056e"], "d": ["Mahmud II cho lập Meclis-i Vâlâ-yı Ahkâm-ı Adliyye, một hội đồng cấp cao để bàn thảo các đạo luật và điều lệ sắp soạn. Theo mục từ Meclis-i Vâlâ-yı Ahkâm-ı Adliyye trong Bách khoa toàn thư Hồi giáo TDV, hội đồng thực sự bắt đầu làm việc ngày 31 tháng 3 năm 1838, và gần như toàn bộ các cải cách Tanzimat sau này đều được soạn thảo và giám sát qua cơ quan này. Nó trở thành một trong những trung tâm quan trọng nhất của bộ máy quan liêu Ottoman hiện đại.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Cuộc tập kích Sinop", "5947e93f"], "d": ["Hạm đội Biển Đen của Nga dưới quyền Đô đốc Nakhimov tập kích hạm đội Ottoman đang neo tại cảng Sinop mà không tuyên chiến; mười hai chiến thuyền bị đánh chìm, hơn hai nghìn binh sĩ tử trận và chỉ huy hạm đội Osman Pasha bị bắt làm tù binh. Theo mục từ Sinop trong Bách khoa toàn thư Hồi giáo TDV, trong cuộc tập kích, tại thành phố cũng có bảy nhà nguyện, hai trường học, 247 ngôi nhà và 170 cửa hiệu bị cháy, năm dân thường Hồi giáo và mười sáu dân thường Kitô giáo thiệt mạng. Sự kiện, vang dội trong dư luận châu Âu với tên 'thảm kịch Sinop', là ngòi nổ trực tiếp khiến Anh và Pháp trong vài tháng tham chiến về phe Ottoman.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Tờ Tasvir-i Efkar ra mắt", "506c98e2"], "d": ["Tờ Tasvir-i Efkar do Şinasi xuất bản bắt đầu phát hành, là tờ báo tiếng Thổ thứ tư sau Takvim-i Vekayi, Ceride-i Havadis và Tercüman-ı Ahval. Theo mục từ \"Tasvîr-i Efkâr\" của TDV, tờ báo trở thành tiếng nói của phong trào Người Ottoman Trẻ trong thời kỳ Namık Kemal, người sau này đảm nhiệm vị trí chủ bút.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Thành lập Hội Người Ottoman Trẻ", "335fb02d"], "d": ["Dưới sự dẫn đầu của Mustafa Fazıl Pasha, các trí thức Ottoman chạy sang châu Âu tổ chức lại dưới tên Thổ Nhĩ Kỳ Trẻ với một điều lệ mười ba điều. Theo mục từ \"Yeni Osmanlılar Cemiyeti\" của TDV, nhóm xuất bản các tờ báo như Muhbir và Hürriyet tại Paris, London và Geneva, truyền bá yêu cầu về chế độ lập hiến.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Lập Hội đồng Nhà nước (Şura-yı Devlet)", "b863b306"], "d": ["Meclis-i Ahkâm-ı Adliyye được tách đôi, lập ra Hội đồng Nhà nước (Şura-yı Devlet) lo công việc hành chính và Divan-ı Ahkâm-ı Adliyye phụ trách việc xét xử. Theo mục từ \"Şûrâ-yı Devlet\" của TDV, cơ quan này phỏng theo Conseil d'État của Pháp, với Midhat Pasha làm chủ tịch đầu tiên; mục đích là phân tách lập pháp, hành pháp và tư pháp.", "6a4ac9ed"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Chiếm Köprühisar và chuẩn bị lập Yenişehir", "39abff03"], "d": ["Bằng việc hạ các pháo đài canh đèo giữa Bursa và Iznik, nền móng được đặt cho bản doanh tiền phương sẽ đưa hai thành phố vào vòng vây hãm.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Thành lập Yenişehir", "d3275837"], "d": ["Khu định cư đồn trú chính quy đầu tiên của Ottoman được lập ra để điều hành các cuộc vây hãm Bursa và Iznik; Orhan Gazi sinh ra tại đây.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Cuộc vây hãm Iznik lần đầu và chinh phục Marmaracık", "cdca2349"], "d": ["Iznik bị vây hãm lần đầu nhưng không thể hạ được (chinh phục dứt khoát vào năm 1331); pháo đài Marmaracık ở gần đó bị chiếm trong thời gian này.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Cuộc viễn chinh Anatolia của đội quân Catalan", "4fd940d5"], "d": ["Đội lính đánh thuê Catalan mà Byzantium thuê để chặn bước tiến của người Thổ tuy giành được những thắng lợi tạm thời nhưng không thể trụ lâu; khi họ rút đi, bước tiến của các công quốc biên thùy càng nhanh hơn.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal cải theo Hồi giáo và gia nhập Ottoman", "ca0d86e1"], "d": ["Köse Mihal, tekfur (lãnh chúa Byzantium) của Harmankaya, cải theo Hồi giáo và quy phục Osman Gazi cùng pháo đài và thuộc hạ của mình; ông trở thành chỉ huy Ottoman gốc Byzantium đầu tiên.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey nắm quyền điều hành trên thực tế", "6dadbefc"], "d": ["Do Osman Gazi tuổi cao và đau yếu, việc chỉ huy và điều hành trên thực tế cuộc vây hãm Bursa cùng các chiến dịch chuyển sang con trai ông là Orhan Bey (lễ đăng quang chính thức diễn ra năm 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Chiếm Mudanya", "0a623368"], "d": ["Khi Mudanya, hải cảng của Bursa, bị chiếm, đường liên lạc của thành phố với biển bị cắt đứt; cuộc vây hãm Bursa bước vào giai đoạn bóp nghẹt.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Akyazı và đảo İmralı rơi vào tay Ottoman (nguồn không cho biết niên đại)", "380c60ce"], "d": ["Akyazı trở thành mục tiêu tập kích của Ottoman dưới thời Osman Bey (trong những năm sau chiến dịch 1305); không rõ năm chính xác bị chiếm. Không nguồn nào cho biết đảo İmralı bị chiếm khi nào. Đường ranh năm 1324 trên bản đồ chỉ là giá trị tạm điền.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca chiếm Kandıra và vùng phụ cận", "341bb97e"], "d": ["Akça Koca, một trong các tướng biên thùy của Orhan Gazi, trong khi từ bản doanh phía tây hồ Sapanca tập kích vùng Izmit, đã chiếm Kandıra và vùng phụ cận vào khoảng năm 1326. Izmit khi ấy vẫn trong tay Byzantium; thành phố chỉ thất thủ vào năm 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Sáp nhập Yalova và Karamürsel", "133cb07a"], "d": ["Yalova và vùng phụ cận ở bờ nam vịnh Izmit rơi vào tay người Thổ trong năm này; dải ven biển được Orhan Bey ban làm timar cho Karamürsel Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca chiếm Aydos và đồn Samandıra", "ce4daa8a"], "d": ["Sau khi chiếm Kandıra, Akça Koca cùng Konuralp và Gazi Abdurrahman chiếm pháo đài Aydos gần Kartal, rồi đến đồn Samandıra ở phía bắc; vùng Samandıra được ban cho ông làm tài sản riêng. Akça Koca qua đời gần Kandıra năm 1328; quyền cai quản biên thùy vùng này được giao cho Hoàng tử Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Liên minh Ottoman – Aydın – Saruhan", "9df6bb74"], "d": ["Ba công quốc cùng hành động chống Byzantium; hạm đội của Umur Bey nhà Aydın, với những cuộc tập kích bờ biển Thrace, đã bào mòn Byzantium từ một mặt trận thứ hai.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Chinh phục Gemlik (Kios)", "66fc4bcd"], "d": ["Thị trấn ven biển Gemlik (Kios) bên vịnh Gemlik mở ra biển Marmara rơi vào tay Ottoman. Khi Bursa đầu hàng năm 1326, tekfur của thành phố đã cùng gia đình được đưa đến Gemlik; nghĩa là năm 1326 Gemlik vẫn thuộc Byzantium. Không tìm được niên đại riêng cho Armutlu; nơi này được gắn với chuỗi của Gemlik.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Hôn nhân giữa Orhan Gazi và Theodora: liên minh với Byzantium", "9b67a590"], "d": ["Orhan Gazi, ủng hộ Kantakouzenos trong cuộc tranh giành ngôi báu Byzantium, đã cưới con gái ông là Theodora; liên minh này giúp lực lượng Ottoman hiểu rõ Rumelia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Chiếm Ankara", "49bf1f6d"], "d": ["Ankara, đang dưới quyền cai quản của hội Ahi, chuyển sang quyền quản lý của Ottoman; con đường vào Trung Anatolia được mở ra. Những nơi khác được sáp nhập cùng thời điểm này: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Bước tiến tại Thrace thời Süleyman Pasha: Malkara, İpsala và Tekirdağ", "fb31cf02"], "d": ["Sau khi lập được đầu cầu tại Gallipoli, Süleyman Pasha từ bán đảo tiến lên phía bắc và từng bước chiếm đồng bằng nằm giữa bờ biển Marmara và cửa sông Maritsa. Nhờ vậy, Malkara, İpsala và Rodosçuk (Tekirdağ) tạo thành một hành lang liền mạch nối Gallipoli với thung lũng Maritsa. Không có hành lang này thì không thể tiến đánh Edirne; bước tiến bị ngừng do cái chết đột ngột của hoàng tử năm 1357 sẽ được Lala Şahin và Hacı İlbey tiếp tục.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Hoàng tử Halil bị bắt cóc", "b52ac3d7"], "d": ["Halil, con trai út của Orhan Gazi, bị cướp biển ở Phocaea (Foça) bắt cóc; cuộc khủng hoảng tiền chuộc chiếm lấy quan hệ Ottoman – Byzantium trong nhiều năm.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Cắt đường viện binh đến Edirne: các pháo đài Çorlu, Lüleburgaz, Babaeski và Keşan", "8e8ad485"], "d": ["Hoàng tử Murad, nối lại chiến dịch chinh phục sau khi cứu được Halil, đã phái kỵ binh tập kích (akıncı) đến tận ngoại vi Constantinopolis để cô lập Edirne khỏi sự trợ giúp từ bên ngoài. Các pháo đài Çorlu, Lüleburgaz và Babaeski trên đường Constantinopolis – Edirne, cùng Keşan tại ngã đường Nam Thrace, bị chiếm. Edirne đầu hàng sau khi vòng vây này được khép lại.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Chiếm Didymoteicho — mở thung lũng Maritsa", "b59aee83"], "d": ["Didymoteicho (Dimetoka), pháo đài then chốt của thung lũng Maritsa, bị chiếm; con đường dẫn tới việc chinh phục Edirne nhờ đó được mở ra. Khi hành lang kéo dài từ Gallipoli lên phía bắc chưa hoàn thành thì không thể tiến đánh Edirne, vì thế pháo đài này đứng trước Edirne trong trình tự các cuộc chinh phục tại Rumelia. Một thời gian, thành phố là bản doanh của các sultan tại Rumelia. Lực lượng chiếm Didymoteicho sau đó đưa toàn bộ vùng Trung Maritsa vào kiểm soát, cùng với các pháo đài nhỏ như Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Mất Gallipoli (cuộc Thập tự chinh của xứ Savoy)", "00e7e415"], "d": ["Hạm đội của Amadeus xứ Savoy, anh em họ của hoàng đế Byzantium, chiếm Gallipoli và trao lại cho Byzantium; suốt mười năm, đầu cầu Ottoman tại Rumelia phải được điều hành từ bên kia eo biển. Những khu định cư khác bị mất cùng thời điểm này: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Trận Chernomen (Çirmen) — kiểm soát thung lũng Maritsa", "cd738d8d"], "d": ["Quân đội của các lãnh chúa Serbia bị đánh tan trong một cuộc tập kích đêm; các lãnh chúa địa phương Serbia và Bulgaria ở Macedonia và vùng Rhodope lần lượt bắt đầu nộp cống cho Ottoman — đây không phải khởi đầu của chinh phục trực tiếp mà là của làn sóng chư hầu hóa. Trong truyền thuyết Ottoman, trận này còn được kể dưới tên \"Sırpsındığı\" và vào năm 1364, như cuộc tập kích đêm của Hacı İlbey vào đạo quân Thập tự chinh đến giành lại Edirne; TDV cho biết niên đại đó sai và hai lời kể thuộc về cùng một trận chiến.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Chinh phục Plovdiv và Stara Zagora", "e780c9ae"], "d": ["Plovdiv ở thượng lưu thung lũng Maritsa và Stara Zagora ở phía bắc bị chiếm; Sa quốc Bulgaria trở thành nước nộp cống. Tuyến Pazardzhik – Ihtiman giữa Plovdiv và Sofia vẫn trong tay các lãnh chúa địa phương đã trở thành chư hầu sau Chernomen. Những khu định cư khác bị mất cùng thời điểm này: Haskovo, Klokotnitsa.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Byzantium chư hầu: John V trong quân đội của Murad I (hệ quả của chiến thắng Chernomen 1371)", "13ffe568"], "d": ["Theo TDV, sau chiến thắng Chernomen (Maritsa) ngày 26 tháng 9 năm 1371, Đế quốc Byzantium đã thừa nhận quyền thống trị của Ottoman và, khi chấp nhận nộp cống cùng phục vụ trong quân đội Ottoman, đã rơi vào địa vị nước chư hầu. Theo nghĩa vụ đó, Hoàng đế John V gia nhập quân đội của Murad I năm 1373; con trai ông là Andronikos IV, được ông để lại Constantinopolis vào lúc ấy, đã cùng Hoàng tử Savcı Bey ở Bursa nổi loạn chống lại cha của họ.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Thu hồi Gallipoli", "5f96c0a5"], "d": ["Andronikos IV, được Ottoman ủng hộ trong cuộc tranh giành ngôi báu Byzantium, đổi lại đã trả Gallipoli; cầu nối giữa Rumelia và Anatolia được dựng lại. Những nơi khác được sáp nhập cùng thời điểm này: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Của hồi môn Germiyan: sáp nhập Kütahya", "d6a6fe61"], "d": ["Khi Devletşah Hatun, con gái Süleyman Shah nhà Germiyan, kết hôn với Bayezid \"Sấm Sét\", Kütahya, Simav, Tavşanlı và Eğrigöz được chuyển cho Ottoman làm của hồi môn — ví dụ kinh điển về việc mở rộng lãnh thổ không qua chiến tranh. Những nơi khác được sáp nhập cùng thời điểm này: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Mua lại xứ Hamid: sáp nhập Isparta", "4a1b6047"], "d": ["Hüseyin Bey nhà Hamid bán một phần công quốc của mình (Akşehir – Beyşehir – Isparta) cho Murad I lấy tiền mặt; phần còn lại của xứ Hamid sẽ bị Yıldırım sáp nhập năm 1391. Những khu định cư khác bị mất cùng thời điểm này: İshaklı.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Chinh phục Serres", "d4d28b60"], "d": ["Serres, chìa khóa của Đông Macedonia, bị chiếm; Thessaloniki rơi vào vòng vây. Tuyến Kyustendil – Petrich – Nevrokop – Drama giữa Sofia và Serres đến thời điểm này chưa bị sáp nhập trực tiếp; lần lượt chuyển sang chế độ chư hầu từ những năm 1370 đến 1383 và sang quyền cai quản trực tiếp sau năm 1383. Những khu định cư khác bị mất cùng thời điểm này: Gevgelija, Kilkis (Avrathisar).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Chinh phục Sofia", "96d5f01f"], "d": ["Các đèo phía tây của dãy Balkan được đưa vào kiểm soát; vì đến lúc này Serres đã được nắm giữ từ năm 1383, lãnh thổ Thrace – Macedonia hợp thành một khối liền mạch.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Chinh phục Niš", "77f5d632"], "d": ["Khi chiếm được Niš, yết hầu của thung lũng Morava, Công quốc chuyên chế Serbia bị đe dọa trực tiếp.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Thessaloniki đầu hàng lần thứ nhất", "96010ee9"], "d": ["Sau thời gian dài bị phong tỏa, thành phố đầu hàng (sẽ được trả lại cho Byzantium năm 1403 và bị chinh phục dứt khoát năm 1430). Những nơi khác được sáp nhập cùng thời điểm này: Kavala. Những khu định cư khác bị mất cùng thời điểm này: Langadas, Eleftheroupoli (Praviște).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Thỏa ước (ahidname) Ottoman – Genoa — gia hạn hiệp ước 1352", "be11d17a"], "d": ["Cùng các sứ giả Genoa đến từ Pera, hiệp định thương mại năm 1352 có từ thời Orhan Gazi được gia hạn; thuế giữa hai nhà nước, cách đối xử với tù binh và tự do thương mại được quy định lại. Đây được xem là thỏa ước hữu nghị và thương mại đầu tiên được biết chính thức giữa người Ottoman và người Genoa — không phải liên minh quân sự mà là một hiệp định thuần túy thương mại.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Chiến dịch Bulgaria của Çandarlı Ali Pasha: chiếm Shumen và Ruse", "2781c3a9"], "d": ["Các pháo đài dọc sông Danube của Sa quốc Bulgaria được tiếp nhận trong một chiến dịch; không nên nhầm với thất bại ở Bileća tại Bosnia cùng năm — đây là một thành công diễn ra đồng thời trên một mặt trận khác. Tarnovo và Vidin là những trung tâm Bulgaria cuối cùng còn được giữ.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Thất bại tại Bileća", "89ba0a64"], "d": ["Đạo kỵ binh tập kích tiến vào Bosnia bị phục kích và tiêu diệt tại Bileća; thất bại lớn đầu tiên này tại Balkan đã khích lệ liên minh dẫn tới trận Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Sáp nhập các công quốc Tây Anatolia: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Ba công quốc được sáp nhập trong một lượt: trung tâm của nhà Saruhan là Manisa; trung tâm của nhà Aydın là Aydın (kể cả pháo đài Thượng của Izmir, nhưng cảng/pháo đài Hạ vẫn thuộc Hiệp sĩ Thánh John — đến năm 1402); trung tâm của nhà Menteşe là Muğla – Milas, gồm cả dải ven biển Datça – Bodrum – Marmaris – Fethiye. Lần đầu tiên bờ biển Aegea quy về một mối. Những nơi khác được sáp nhập cùng thời điểm này: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Sáp nhập xứ Teke: sáp nhập Antalya", "fdbeee5c"], "d": ["Xứ Teke bên bờ Địa Trung Hải được sáp nhập vào lãnh thổ Ottoman. Nhà Teke là một nhánh tách ra từ nhà Hamid: Feleküddin Dündar Bey đã giao Antalya mà ông chinh phục cho em trai là Yûnus Bey, và khoảng năm 1321 một công quốc riêng ra đời. Vì thế, trên bản đồ, Antalya và vùng phụ cận sau năm 1321 không được tô màu của nhà Hamid mà của nhà Teke. Công quốc được tái lập sau trận Ankara và chỉ bị thanh toán dứt điểm vào năm 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Chinh phục Skopje", "9e5a1af5"], "d": ["Trung tâm của Macedonia lưu vực sông Vardar bị chiếm; Skopje trở thành một trong những trung tâm biên thùy chính của Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Sáp nhập Kastamonu", "876330ba"], "d": ["Nhánh Kastamonu của nhà Candaroğlu bị xóa bỏ; nhánh Sinop tiếp tục tồn tại như chư hầu. Những nơi khác được sáp nhập cùng thời điểm này: Bartın, Safranbolu, Akçakoca, Devrek, Eflani, Karadeniz Ereğli, Tosya.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Tarnovo thất thủ — Bulgaria bị sáp nhập", "ff666977"], "d": ["Kinh đô của Sa quốc Bulgaria thất thủ; Bulgaria rơi vào quyền cai trị trực tiếp của Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Pleven, Lovech, Gabrovo.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Pháo đài Lovech rơi vào tay Ottoman", "a55e87a0"], "d": ["Lovech, một trong các pháo đài của Sa hoàng Bulgaria Ivan Shishman, được sáp nhập vào lãnh thổ Ottoman cùng các tỉnh khác của Shishman trong chiến dịch năm 1393 làm Tarnovo thất thủ. Nguồn không khẳng định chắc chắn: người ta \"cho rằng\" việc chinh phục diễn ra vào năm này.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Sáp nhập Dobruja", "478e36f2"], "d": ["Các vùng đất Dobruja trải đến châu thổ sông Danube được sáp nhập. Những nơi khác được sáp nhập cùng thời điểm này: Silistra, Constanța, Babadag, Balchik, Hârșova, Tulcea, Mangalia, Isaccea, Tutrakan, Măcin, Küçük Kaynarca.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Tiến xuống Thessaly", "8bec60dd"], "d": ["Đồng bằng Thessaly với trung tâm là Larissa (Yenişehir) được đưa vào quyền quản lý của Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Trikala, Lamia (İzdin).", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Trận Rovine — chiến dịch Wallachia", "343ae7a9"], "d": ["Sau trận đánh đẫm máu với Mircea, voivode xứ Wallachia, mà kết quả còn gây tranh cãi, Wallachia chấp nhận nộp cống cho Ottoman; trật tự chư hầu ở phía bắc sông Danube được thiết lập.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Chinh phục Nicopolis", "b9791717"], "d": ["Sau trận Rovine năm 1395 chống người Wallachia, Bayezid \"Sấm Sét\" chiếm pháo đài Nicopolis bên bờ sông Danube; một số biên niên sử Bulgaria khuyết danh ghi việc chinh phục diễn ra ngày 3 tháng 6 năm 1395. Niên đại chinh phục trong các nguồn không thống nhất: mục từ Trận Nicopolis trong TDV İslâm Ansiklopedisi viết rằng Bayezid chiếm Silistra và Nicopolis trong một chiến dịch sông Danube năm 1394. Pháo đài sẽ bị vây hãm trong cuộc Thập tự chinh nổi tiếng năm 1396 nhưng không thất thủ. Những nơi khác được sáp nhập cùng thời điểm này: Ohrid.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Pháo đài Nicopolis rơi vào tay Ottoman", "327012c9"], "d": ["Sau cuộc tập kích Rovine, Bayezid \"Sấm Sét\" chiếm Nicopolis; Sa hoàng Bulgaria Ivan Shishman, ngự tại đó với tư cách chư hầu Ottoman, bị loại bỏ. Trên bản đồ, Nicopolis được ghi chuyển từ Sa quốc Bulgaria sang Ottoman kể từ ngày này.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Xây dựng Anadolu Hisarı", "aa259b00"], "d": ["Để hỗ trợ việc phong tỏa Constantinopolis, Güzelcehisar (Anadolu Hisarı) được xây ở bờ phía Anatolia của eo biển Bosphorus — bước đi lâu dài đầu tiên trong việc kiểm soát eo biển.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Sáp nhập Vidin", "ee1ae44b"], "d": ["Sau chiến thắng Nicopolis, Vidin, công quốc Bulgaria cuối cùng, cũng bị sáp nhập.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Sáp nhập Karaman lần thứ nhất", "3cf07876"], "d": ["Với chiến thắng Akçay, lãnh thổ nhà Karaman lần đầu tiên được sáp nhập vào Ottoman (sẽ được tái lập trong Thời kỳ Đứt đoạn).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Sáp nhập dải bờ biển Canik: Samsun", "af9c40fa"], "d": ["Trong khoảng trống xuất hiện khi Kadı Burhâneddin bị Karayülük Osman Bey của Aq Qoyunlu bắt làm tù binh, Bayezid \"Sấm Sét\" trước hết đưa vùng Canik ven Biển Đen vào quyền quản lý của Ottoman. Như vậy, Samsun và vùng phụ cận trở thành hải cảng Biển Đen đầu tiên của hoàng tộc. Còn tuyến Sivas – Tokat – Kayseri ở nội địa sẽ được sáp nhập hai tuần sau, khi Nhà nước của Kadı Burhâneddin trên thực tế tan rã.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Chiếm Malatya", "7cb6ae16"], "d": ["Malatya ở biên giới Mamluk bị chiếm — một trong những bước làm gia tăng căng thẳng với Timur.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur chiếm Malatya rồi giao cho Karayülük Osman — Timur rút đi, nhà Dulkadir lấy lại", "ad2ce7d8"], "d": ["Bayezid \"Sấm Sét\" đã để Malatya, chiếm năm 1399, cho Nasreddin Mehmed nhà Dulkadir rồi trở về Bursa. Timur vào Anatolia năm 1400, trước hết chiếm Sivas và Elbistan, rồi đến Malatya; thành phố và vùng phụ cận bị cướp phá, việc cai quản được giao cho Karayülük Osman đang đi theo Timur. Khi Timur rời vùng này, nhà Dulkadir lại làm chủ Malatya; như vậy quyền thống trị của Ottoman chấm dứt trước trận Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Hiệp ước Süleyman Çelebi – Byzantium: trả lại Thessaloniki", "cc503cc2"], "d": ["Süleyman Çelebi, người cai trị Rumelia trong Thời kỳ Đứt đoạn, thỏa thuận với Byzantium và các nhà nước Latin, nhượng Thessaloniki cùng dải bờ Biển Đen đến tận Mesembria cho Byzantium (TDV fetret-devri: Hiệp ước Gallipoli, tháng 2 năm 1403) — trên bản đồ İğneada, Rezve và Ahtapolu chuyển sang Byzantium; trên bản đồ Thessaloniki tách khỏi Ottoman từ thời điểm này.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Hải chiến thất bại tại Gallipoli (trước Venice)", "b71d4d68"], "d": ["Hạm đội Venice giáng cho hạm đội Ottoman một thất bại nặng nề ngoài khơi Gallipoli; sự kiện cho thấy giới hạn của nghề hàng hải Ottoman thời kỳ đầu.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Cuộc nổi dậy của Mustafa \"Giả mạo\" (Düzmece Mustafa)", "0ec43138"], "d": ["Mustafa Çelebi, tự nhận là con trai của Bayezid \"Sấm Sét\", đã tuyên bố làm sultan tại Rumelia với sự hỗ trợ của Byzantium; Murad II dẹp cuộc nổi dậy năm 1422 và cho xử tử đối thủ.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Murad II vây hãm Constantinopolis", "4b9d9fba"], "d": ["Đáp trả việc Byzantium ủng hộ Mustafa \"Giả mạo\", Murad II vây hãm Constantinopolis; cuộc vây hãm được dỡ bỏ khi em trai ông là Küçük Mustafa bị xúi giục nổi dậy tại Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Thessaloniki được chuyển giao cho Venice", "bfa6c4a0"], "d": ["Viên tổng trấn Byzantium, bị Ottoman gây sức ép, đã giao thành phố cho Venice; cuộc giằng co Ottoman – Venice kéo dài bảy năm bắt đầu.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Sáp nhập lại các công quốc Tây Anatolia: Menteşe và Aydın", "aca30a48"], "d": ["Hai công quốc vùng Aegea được tái lập trong Thời kỳ Đứt đoạn đã được sáp nhập dứt khoát vào lãnh thổ Ottoman dưới thời Murad II. Theo mục từ Nhà Menteşe của TDV, Murad II chiếm xứ Menteşe năm 827 (1424) và cho giam hai anh em đứng đầu công quốc. Theo mục từ Nhà Aydın, Beylerbey xứ Anatolia là Hamza Bey đã cho bắt Cüneyd Bey, kẻ lại không chịu thần phục, rồi xử tử ông cùng gia đình (829/1425-26), và xứ Aydın chuyển sang Ottoman. Các Hiệp sĩ Thánh John, nắm giữ pháo đài cảng Izmir từ năm 1344, đã để mất nó vào tay Timur năm 1402, và vùng này trở lại dưới sự kiểm soát của nhà Aydın; qua đợt sáp nhập này, nó cũng gia nhập Ottoman. Xứ Teke (Antalya) không thuộc nội dung mục này: nhà Teke đã bị thanh toán riêng năm 1423. Còn Germiyan sẽ được sáp nhập theo di chúc vào năm 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Sáp nhập Germiyan theo di chúc", "9eb86b77"], "d": ["Yakub II, bey xứ Germiyan, qua đời không có con, đã để lại đất nước cho Ottoman theo di chúc — ví dụ kinh điển trong sách giáo khoa về việc sáp nhập không qua chiến tranh. Những nơi khác được sáp nhập cùng thời điểm này: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Chinh phục dứt khoát Thessaloniki", "bc021768"], "d": ["Thành phố do Venice cai quản bị đánh chiếm bằng cuộc công kích; hải cảng lớn thứ hai của Rumelia đã thuộc hẳn về Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Kassandra (Kesendire).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Ioannina đầu hàng", "ee45cb52"], "d": ["Ioannina, trung tâm của Epirus, đầu hàng theo thỏa ước.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Chiếm Smederevo lần đầu", "c11ca17d"], "d": ["Sau ba tháng vây hãm, kinh đô của Công quốc chuyên chế Serbia bị chiếm và Serbia bị sáp nhập lần đầu tiên (sẽ được trả lại theo Hiệp ước Edirne – Szeged năm 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Vây hãm Belgrade (thất bại)", "3e05f425"], "d": ["Cuộc vây hãm Belgrade lớn đầu tiên, kéo dài sáu tháng, không đạt kết quả; suốt tám mươi năm pháo đài vẫn là chốt chặn trước bước tiến của Ottoman.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Thất bại tại Zlatica (İzladi) — \"Chiến dịch Dài\"", "97df1466"], "d": ["Đạo quân mà Hunyadi dẫn vào Balkan giữa mùa đông đã vượt qua Niš và Sofia rồi áp sát Zlatica; phòng tuyến Ottoman trụ lại một cách khó khăn. Bầu không khí thất bại này đã đưa hòa ước Edirne – Szeged lên bàn đàm phán.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Hiệp ước Edirne – Szeged", "0aa4e0de"], "d": ["Hòa bình mười năm: Công quốc chuyên chế Serbia được khôi phục, sông Danube được công nhận là biên giới. Việc hiệp ước bị phá bỏ chỉ sau vài tháng do Giáo hoàng xúi giục đã dẫn đến thảm họa Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Hoàn trả Smederevo và các pháo đài Serbia cho Serbia", "cda3cf9e"], "d": ["Điều khoản của Hiệp ước Edirne – Szeged được thi hành: ngày 15 tháng 8 năm 1444, Murad II trả lại cho Đurađ Branković Smederevo cùng hai mươi bốn pháo đài quan trọng và các vùng đất Serbia khác đang bị chiếm đóng (TDV semendire); Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) và Priština (TDV pristine) cũng được giao cho người Serbia. Vidin không phải đất Serbia nên không nằm trong diện hoàn trả — đó là nguồn gốc của phần lãnh thổ bị mất ở phía tây bắc thấy trên bản đồ quanh thời điểm chiến thắng Varna; vài tháng sau, với thất bại tại Varna, hiệp ước đằng nào cũng mất hiệu lực.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Hoàn thành Rumeli Hisarı — \"Kẻ cắt eo biển\" (Boğazkesen)", "480e8a76"], "d": ["Với pháo đài được hoàn thành, theo các nguồn sử liệu, trong một công trình thi công cực kỳ nhanh chỉ bốn đến năm tháng, quyền kiểm soát eo biển Bosphorus hoàn toàn thuộc về Ottoman; con đường viện trợ từ Biển Đen đến Constantinopolis bị bịt kín. Đây được coi là bước đầu tiên trên thực tế của cuộc vây hãm.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Cuộc vây hãm Constantinopolis bắt đầu", "8af50742"], "d": ["Quân đội dàn trận trước tường thành; trong cuộc vây hãm kéo dài 54 ngày, lần đầu tiên đại bác khổng lồ được sử dụng một cách có hệ thống chống lại tường thành của một kinh đô.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Chiến thuyền được đưa trên đất liền xuống Sừng Vàng", "4f2ba07c"], "d": ["Khoảng 70 chiến thuyền của hạm đội, không thể vào Sừng Vàng bị chặn bằng dây xích, được kéo trên các đường trượt bôi mỡ vượt qua sườn đồi Galata và hạ xuống Sừng Vàng chỉ trong một đêm; lực lượng phòng thủ bị chia ra hai mặt trận.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Chinh phục Athens", "4f0f1bb2"], "d": ["Công quốc Athens chấm dứt; cờ Ottoman được kéo lên trên Acropolis. Những nơi khác được sáp nhập cùng thời điểm này: Thebes (İstefe), Livadeia.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Sáp nhập Serbia (Smederevo thất thủ)", "75fd0a62"], "d": ["Smederevo, kinh đô của Công quốc chuyên chế Serbia, đầu hàng; Serbia trở thành một sancak của Ottoman.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Chinh phục Morea", "7d5a3c18"], "d": ["Công quốc chuyên chế Morea bị xóa bỏ; bán đảo (trừ các pháo đài của Venice) chuyển sang quyền quản lý của Ottoman.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Sáp nhập Sinop", "e03c2739"], "d": ["Sinop của nhà Candaroğlu đầu hàng mà không giao chiến; đường mở ra cho chiến dịch Trebizond. Những nơi khác được sáp nhập cùng thời điểm này: Kastamonu, Bartın, Safranbolu. Mục từ Nhà Candaroğlu của TDV cũng kể Bolu, Eflani và Tosya trong số lãnh thổ của công quốc Candaroğlu bị sáp nhập năm 1461; trên bản đồ, cả ba nơi này cũng được ghi chuyển từ Candaroğlu sang Ottoman vào ngày này. Những khu định cư khác bị mất cùng thời điểm này: Karadeniz Ereğli, Devrek, Akçakoca (đất của Candaroğlu).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Vương quốc Bosnia sụp đổ — chiến dịch Bosnia của Nhà Chinh phục", "5362e3f2"], "d": ["Khi vị vua Bosnia cuối cùng Stjepan Tomašević (1461-1463), cậy vào sự hỗ trợ của phương Tây, từ chối nộp cống, ông bị coi là không còn là quân chủ chư hầu, và quân đội do Sultan Mehmed Nhà Chinh phục chỉ huy đã xóa bỏ Vương quốc Bosnia chỉ trong một chiến dịch. Nhà vua bị bắt và xử tử, vương quốc biến mất và sancak Bosnia được thành lập tại vùng này. Tuy vậy, việc vương quốc sụp đổ không đồng nghĩa với việc Bosnia bị chinh phục. Chính quyền Ottoman đã có mặt ở vùng đồng bằng từ mười lăm năm trước — Hodidjed và đồng bằng Saray bị chiếm năm 1448, lãnh địa biên thùy của Îsâ Bey đã được lập ngay giữa lòng vương quốc. Cuộc chinh phục cũng không kết thúc năm 1463: Foča bị chiếm năm 1465, Livno năm 1469, Công quốc Herzegovina năm 1483, banat Srebrenik năm 1512, còn Jajce và Banja Luka ở phía bắc mãi đến năm 1528, sau trận Mohács, mới bị chiếm — sau năm 1463, người Hungary đã lập ở bắc Bosnia một banat trụ vững được sáu mươi lăm năm. Nơi đổi chủ trực tiếp vào thời điểm này là Travnik; còn Jajce vào thời điểm này không chuyển sang Ottoman mà sang Hungary.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Sáp nhập dứt khoát Karaman", "f1dcecaa"], "d": ["Vùng lãnh thổ trung tâm của nhà Karaman được sáp nhập dứt khoát; các tranh chấp nội bộ kéo dài đến những năm 1470. Những nơi khác được sáp nhập cùng thời điểm này: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Chinh phục Negroponte", "5c97daf3"], "d": ["Negroponte (Eğriboz), căn cứ chính của Venice trên biển Aegea, thất thủ.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Sáp nhập Alanya, Anamur và Silifke (İçel)", "a0b9d461"], "d": ["Dải ven biển İçel phụ thuộc nhà Karaman (toàn bộ bờ Địa Trung Hải giữa Antalya và Mersin) được sáp nhập nhờ chiến dịch đường biển của Gedik Ahmed Pasha; Alanya có tầm quan trọng nhờ xưởng đóng tàu chiến lược có từ thời Seljuk.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Moskva sáp nhập Novgorod", "bed87170"], "d": ["Đại Công tước Ivan III gỡ bỏ chiếc chuông tượng trưng của hội đồng dân chúng (veche) tại Novgorod, thay các quan chức địa phương bằng các tổng trấn của mình và trên thực tế gắn thành phố vào Moskva; Novgorod không còn là một nước cộng hòa độc lập. Lãnh thổ Novgorod trải từ biển Baltic đến Biển Trắng và dãy Ural. Trên bản đồ, Novgorod được ghi chuyển từ Cộng hòa Novgorod sang Moskva kể từ ngày này.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Hiệp ước Istanbul — Albania và Shkodër", "b09652f7"], "d": ["Cuộc chiến Ottoman – Venice kéo dài 16 năm chấm dứt; Shkodër và vùng bờ biển Albania thuộc về Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Lemnos, Samos, Agios Efstratios (Bozbaba).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Đổ bộ Otranto", "7916b89d"], "d": ["Quân Ottoman đổ bộ lên bờ biển Apulia (Puglia), vây hãm và chiếm pháo đài Otranto; vì thành phố bị chiếm bằng giao chiến nên một số thân hào kháng cự bị xử tử, một số bị bắt làm tù binh. Truyền thống Giáo hội tưởng niệm những người chết là \"các vị tử đạo Otranto\", khoảng 800 người; TDV cho rằng việc phóng đại con số này là do tuyên truyền của Giáo hội. Quân Ottoman chỉ giữ được pháo đài ở mũi bán đảo Salento và vùng chật hẹp xung quanh; phần lãnh thổ còn lại của Vương quốc Napoli trên tuyến Taranto – Brindisi – Lecce không bị mất — đầu cầu mở vào Ý này chỉ tồn tại một năm.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Rút khỏi Otranto", "37371bb0"], "d": ["Sau khi Sultan Mehmed Nhà Chinh phục qua đời (3 tháng 5 năm 1481), quân đồn trú Otranto không còn hy vọng được tăng viện, đã rút khỏi pháo đài theo thỏa thuận trước cuộc vây hãm của Alfonso, thái tử Napoli; như vậy, đầu cầu duy nhất của Ottoman tại Ý đã mất sau một năm.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Chinh phục Modon và Koron", "38b608c4"], "d": ["Modon và Koron, \"đôi mắt\" của Venice tại Morea, bị chiếm.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Chinh phục Durrës", "1f231b98"], "d": ["Trong chiến tranh Ottoman – Venice 1499-1503, lực lượng dưới quyền Mehmed Bey chiếm Durrës (Draç), cảng lớn cuối cùng của Venice tại Albania bên biển Adriatic. Sau Shkodër (1479) và Vlorë (1417), với cuộc chinh phục này, toàn bộ dải ven biển Albania nằm dưới sự kiểm soát của Ottoman.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Sáp nhập Đông Anatolia", "e0cb8f8f"], "d": ["Sau Chaldiran, Diyarbakır và vùng phụ cận được sáp nhập; các công quốc người Kurd được gắn vào Ottoman nhờ bàn tay của İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Chinh phục pháo đài Petrovaradin (Varadin)", "abf392a5"], "d": ["Quân đội xuất chinh trong chiến dịch Mohács từ Belgrade tiến sang đất Hungary; trước hết các khu ngoại vi của Petrovaradin bị chiếm, sau mười bốn ngày vây hãm, pháo đài cũng thất thủ. Suleiman Nhà Lập pháp ra lệnh không đốt các làng trên đường đi, vì những nơi này từ nay được coi là đất của Ottoman.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Buda đầu hàng sau Mohács — hai vua tranh ngai vàng Hungary", "9d3568a0"], "d": ["Sau chiến thắng Mohács, quân đội Ottoman tiến về Buda và ngày 11 tháng 9 năm 1526 chìa khóa thành được dâng lên sultan; nhưng Suleiman Nhà Lập pháp không giữ Buda mà rút quân. Hungary không còn vua, giới quý tộc bầu ra hai vị vua riêng: János Szapolyai ngày 10 tháng 11 năm 1526 và Ferdinand I nhà Habsburg ngày 17 tháng 12 năm 1526. Ferdinand chiếm Buda vào tháng 8 năm 1527. Việc Szapolyai lập thân tại Buda với tư cách vị vua được Ottoman bảo hộ diễn ra trong chiến dịch 1529 (xem mục 1529), còn quyền cai trị trực tiếp của Ottoman được thiết lập năm 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai được bầu làm vua Hungary — Ottoman công nhận với điều kiện làm chư hầu", "32bc6baf"], "d": ["Ngai vàng Hungary bỏ trống sau khi nhà vua tử trận ở Mohács, một bộ phận quý tộc bầu János Szapolyai, voivode (thống đốc) xứ Transylvania; Szapolyai đăng quang tại Székesfehérvár. Người Ottoman, đã rút khỏi Buda, công nhận vương quyền của Szapolyai với điều kiện ông lệ thuộc họ, để giữ vùng này làm vùng đệm. Trên bản đồ, những nơi thuộc Szapolyai từ thời điểm này được thể hiện là chư hầu của Ottoman.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I được tuyên bố là vua Hungary — Tây và Bắc Hungary thuộc vương miện Habsburg", "b3910a2f"], "d": ["Đại Công tước Ferdinand nhà Habsburg, dựa vào cuộc hôn nhân giữa chị em gái mình với Louis II, đòi quyền kế vị ngai vàng Hungary và được một bộ phận quý tộc tuyên bố làm vua. Như vậy Hungary bị chia cho hai vua; phần phía tây và phía bắc công nhận Ferdinand. Quý tộc Croatia bầu riêng ông vào đầu năm 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Tranh chấp giữa hai vua: Esztergom thuộc quyền bảo hộ của Habsburg, Szeged theo Szapolyai", "da92dee5"], "d": ["Esztergom, từ năm 1526 đã đổi tay giữa hai vua, sau khi tổng giám mục mang kho lưu trữ và ngân khố chuyển lên phía bắc, đã thuộc quyền bảo hộ của Habsburg. Từ chính năm ấy đến năm 1541, Szeged vẫn thuộc chủ quyền của Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Dân Pécs ngả sang phía Szapolyai", "3fc4e7f2"], "d": ["Pécs, được Ferdinand ban đặc quyền năm 1528, không lâu sau ngả sang phía Szapolyai; vua János lưu lại thành phố một thời gian vào năm 1533. Khi Buda thất thủ năm 1541, thành phố quay lại phía Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Chinh phục Tripoli", "8c659986"], "d": ["Tripoli được lấy từ tay các Hiệp sĩ Thánh John; phần trung tâm bờ biển Bắc Phi trở thành đất Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Chinh phục Temesvár", "e9fd4995"], "d": ["Vùng Banat bị chiếm và Beylerbeylik Temesvár được thành lập.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Chinh phục dứt khoát Tunis", "7bbd11bc"], "d": ["Tunis, đang dưới sự kiểm soát của Tây Ban Nha và nhà Hafsid, chuyển hẳn sang quyền cai quản của Ottoman; tuyến Bắc Phi được hoàn thiện. Những nơi khác được sáp nhập cùng thời điểm này: Kairouan, Gabès, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Chinh phục Kanije", "0c7b6aa3"], "d": ["Kanije bị chiếm trong cuộc Chiến tranh Dài; năm sau, cuộc phòng thủ của Tiryâki Hasan Pasha trở thành thiên anh hùng ca.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Chiến dịch Uyvar bắt đầu — Fâzıl Ahmed Pasha từ Edirne tiến đánh Áo", "306a86db"], "d": ["Sau khi Áo tấn công Transylvania và chiếm các pháo đài Székelyhíd và Kolozsvár, Istanbul quyết định mở chiến dịch chống nhà Habsburg. Đại tể tướng Köprülüzâde Fâzıl Ahmed Pasha xuất phát từ Edirne ngày 13 tháng 4 năm 1663. Tại Belgrade, Áo đề nghị hòa bình, nhưng trong hai cuộc hội đàm tại Osijek, các điều kiện của Ottoman bị khước từ. Trong cuộc hội bàn tại Buda, mục tiêu được xác định là Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Chinh phục Uyvar", "ce289470"], "d": ["Uyvar (Nové Zámky), pháo đài then chốt ở Bắc Hungary, bị chiếm; thành ngữ \"mạnh như người Thổ trước Uyvar\" đã đi vào các ngôn ngữ châu Âu. Sau Uyvar, Nitra và Léva cũng đầu hàng sau một thời gian kháng cự ngắn; De Souches lấy lại cả hai vào mùa xuân năm 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Thu hồi Morea", "9b6460f1"], "d": ["Morea, bị giao cho Venice tại Karlowitz, được lấy lại chỉ trong một chiến dịch. Những nơi khác được sáp nhập cùng thời điểm này: Patras (Balyabadra), Lepanto (İnebahtı).", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Mất Belgrade lần thứ hai — cuộc vây hãm của Vương công Eugène", "6a194354"], "d": ["Sau thất bại ở Petrovaradin và việc mất Temesvár, Vương công Eugène vây hãm Belgrade; khi đạo quân tiếp viện đến giải vây cũng bị đánh bại, pháo đài đầu hàng. Thành phố, được lấy lại năm 1690 trước Hiệp ước Karlowitz, lại mất lần nữa và tuyến phòng thủ sông Danube sụp đổ. Mãi hai mươi hai năm sau, bằng Hiệp ước Belgrade 1739, mới thu hồi được Belgrade. Những khu định cư khác bị mất cùng thời điểm này: Smederevo. Bản đồ cũng ghi các vùng Hisarcık (Grocka) và Yagodina (Jagodina) thuộc Habsburg vào ngày này (ngày của vùng; nguồn không có ngày ở cấp từng địa điểm, ước tính đã được khai báo); còn Mehadia chuyển sang Habsburg vào ngày 27 tháng 8 năm 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Özi thất thủ", "90a67a6c"], "d": ["Özi (Ochakov), pháo đài then chốt ở phía bắc Biển Đen, rơi vào tay Nga sau một cuộc công kích đẫm máu; dân chúng trong thành bị tàn sát.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Hiệp ước Bucharest — mất Bessarabia", "932da4d6"], "d": ["Hiệp ước kết thúc chiến tranh với Nga 1806-1812 giao phần phía đông sông Prut (Bessarabia) cho Nga. Những khu định cư khác bị mất cùng thời điểm này: Akkerman, Kiliya, Khotyn, Bender, Izmail. Bản đồ cũng coi Chișinău, Bălți, Cahul và Orhei trong vùng Bessarabia chuyển từ Moldavia (chư hầu của Ottoman) sang Nga cùng ngày. Soroca cũng chuyển sang Nga cùng ngày.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Hiệp ước Edirne", "b3a8fe4c"], "d": ["Kết thúc cuộc chiến mà quân Nga tiến vào Edirne, châu thổ sông Danube bị mất; quyền tự trị/độc lập của Hy Lạp trên thực tế được chấp nhận. Những khu định cư khác bị mất cùng thời điểm này: Brăila, Anapa, Akhaltsikhe. Dù hiệp ước trả lại đất, việc chiếm đóng không chấm dứt ngay: Wallachia – Moldavia và Silistra vẫn nằm dưới quyền quản lý của Nga như vật thế chấp cho đến khi trả xong tiền bồi thường chiến phí — đó là lý do trên bản đồ những nơi này vẫn hiện ra là bị chiếm đóng sau năm 1829. Yêu sách của Ottoman đối với Circassia (Maykop) và bờ biển Circassia (Sochi, Tuapse) cũng chấm dứt với hiệp ước này; về sau dải bờ biển chuyển sang Nga (Sochi và Tuapse năm 1838).", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Sắc lệnh trao quyền tự trị cho Serbia — tước knez cha truyền con nối và điều kiện đồn trú", "6a5d901d"], "d": ["Chiếu chỉ hatt-ı hümâyun ban hành theo điều khoản về Serbia của Hiệp ước Edirne công nhận Miloš Obrenović là knez (vương công) cha truyền con nối và biến Serbia thành một công quốc tự trị, tự do trong nội vụ, đối ngoại phụ thuộc Ottoman. Các điều khoản: tước knez được truyền từ cha sang con, thuế hằng năm nộp theo mức khoán cố định, nghị viện Serbia tự thiết lập nội trị, giáo hội được tự trị; đổi lại, quân đồn trú Ottoman vẫn ở lại các pháo đài Belgrade, Smederevo, Šabac, Soko và Ušće (Fethülislâm). Cấu trúc kép này kéo dài đến khi quân đồn trú rút đi năm 1867. Trên bản đồ, thành phố Belgrade nhập vào Serbia tự trị từ thời điểm này; pháo đài Kalemegdan được thể hiện là có quân đồn trú Ottoman cho đến năm 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Síp được giao cho Anh cai quản", "423da3ee"], "d": ["Đổi lấy một liên minh chống mối đe dọa từ Nga, quyền cai quản đảo Síp được chuyển cho Anh; về pháp lý đảo vẫn là đất Ottoman. Những khu định cư khác bị mất cùng thời điểm này: Nicosia, Famagusta, Kyrenia, Limassol, Larnaca (Tuzla), Paphos, Morphou, Akrotiri, Episkopi, Dhekelia; tức là toàn bộ hòn đảo.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Thessaly được giao cho Hy Lạp", "ac614d24"], "d": ["Theo các quyết định của Đại hội Berlin, Thessaly và vùng quanh Arta được chuyển cho Hy Lạp. Những khu định cư khác bị mất cùng thời điểm này: Arta, Larissa, Trikala, Lamia. Qua đợt chuyển giao này, Volos, Kalambaka và Karditsa (Thessaly) chuyển sang Hy Lạp.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Đông Rumelia sáp nhập vào Bulgaria", "ee43f137"], "d": ["Tỉnh tự trị Đông Rumelia được sáp nhập vào Bulgaria qua một cuộc chính biến; Bâb-ı Âli (Sublime Porte) chấp nhận sự đã rồi. Với cuộc hợp nhất này, toàn bộ Đông Rumelia (Stara Zagora, Pazardzhik, Sliven, Haskovo, Burgas, Aytos, Elhovo) chuyển sang Công quốc Bulgaria.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Trận Domokos", "9c6f29a5"], "d": ["Trong Chiến tranh Ottoman – Hy Lạp năm 1897, quân đội giành thắng lợi quyết định tại Domokos; do áp lực ngoại giao, thành quả lãnh thổ vẫn bị hạn chế.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Crete được tự trị", "2e764881"], "d": ["Mặc dù Chiến tranh Ottoman – Hy Lạp kết thúc với thắng lợi của Ottoman, ngày 18 tháng 12 năm 1897, Anh, Nga, Pháp và Ý tuyên bố Crete tự trị; hòn đảo sẽ là một tỉnh trung lập và tự trị dưới chủ quyền Ottoman. Sau ngày 6 tháng 11 năm 1898, cờ Thổ Nhĩ Kỳ không còn được kéo lên ở Candia và Kisamos; khi Hoàng tử George, con trai vua Hy Lạp, nhậm chức cao ủy đặc biệt ngày 22 tháng 12 năm 1898, Crete trên thực tế đã thoát khỏi quyền cai quản của Ottoman (chính thức tách ra năm 1913). Những khu định cư khác bị mất cùng thời điểm này: Candia (Crete), Chania (Hanya).", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Bulgaria độc lập và Bosnia bị sáp nhập", "393feaa4"], "d": ["Giữa sự hỗn loạn của thời lập hiến, Bulgaria tuyên bố độc lập, còn Áo – Hung sáp nhập Bosnia-Herzegovina. Với tuyên bố này, toàn bộ lãnh thổ của Công quốc Bulgaria (Varna, Shumen, Ruse, Burgas, Sliven và các nơi khác) trở thành Vương quốc Bulgaria độc lập.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Thu hồi Edirne", "536e5599"], "d": ["Trong Chiến tranh Balkan lần thứ hai, quân đội vượt sông Maritsa và lấy lại Edirne mà không phải giao chiến. Những nơi khác được sáp nhập cùng thời điểm này: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Chiến thắng Kut al-Amara", "98b972bc"], "d": ["Chỉ huy sư đoàn Anh bị vây tại Kut đầu hàng cùng 13 nghìn binh sĩ — một trong những chiến thắng lớn nhất của Ottoman trong Chiến tranh thế giới thứ nhất.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Mất Baghdad", "2c18a816"], "d": ["Baghdad, thuộc Ottoman suốt 383 năm, rơi vào tay quân Anh. Những khu định cư khác bị mất cùng thời điểm này: Karbala, Kızılrubat.", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Mất Jerusalem", "94067617"], "d": ["Jerusalem, thuộc Ottoman suốt 401 năm, được giao nộp mà không được phòng thủ.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Mất Damascus", "ed177b68"], "d": ["Khi mặt trận Palestine sụp đổ, Damascus bị bỏ trống; bốn thế kỷ cai trị của Ottoman tại Syria chấm dứt. Những khu định cư khác bị mất cùng thời điểm này: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Medina đầu hàng", "76b505f6"], "d": ["72 ngày sau hiệp định đình chiến, cuộc kháng cự của Fahreddin Pasha, \"Con Hổ Sa mạc\", chấm dứt theo ý chỉ của sultan; đơn vị Ottoman cuối cùng tại Hejaz hạ vũ khí.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Izmir bị chiếm đóng", "e32e5e77"], "d": ["Quân Hy Lạp đổ bộ lên Izmir; cuộc kháng cự khởi đầu bằng phát súng đầu tiên đã châm ngòi cho cuộc Đấu tranh Dân tộc. Còn Aydın bị chiếm ngày 27 tháng 5 năm 1919 (mục riêng).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Istanbul chính thức bị chiếm đóng", "a8e98ada"], "d": ["Lực lượng phe Hiệp ước (Entente) chính thức chiếm đóng Istanbul, Meclis-i Meb'ûsan bị giải tán; các nghị sĩ hướng về Ankara.", "09ed005b"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Lực lượng Saud–Wahhabi chiếm tiểu vương quốc Ha'il — quyền cai quản thuộc dòng họ Ibn Ali của chi tộc Abda", "2d29ceb9"], "d": ["Khi lực lượng của Nhà nước Saud thứ nhất chiếm tiểu vương quốc Ha'il, quyền cai quản thành phố nằm trong tay dòng họ Ibn Ali thuộc chi tộc Abda của bộ lạc Shammar. Dòng họ này cai quản Ha'il cho đến năm 1835, khi Abdullah ibn Rashid giành lấy tiểu vương quốc; triều đại Al Rashid chỉ được lập từ thời điểm đó. Trong atlas, cho đến nay Ha'il vẫn hiển thị là vô chủ đến năm 1836, trong khi nguồn sử liệu nêu đích danh emir của thành phố vào năm 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Quần đảo Kvarner chuyển sang Vương quốc Ý của Napoléon, vịnh Kotor chuyển sang quyền cai quản của Nga", "c5e411c8"], "d": ["Sau Hiệp ước Pressburg, quần đảo Kvarner — khác với Dalmatia — không được sáp nhập trực tiếp vào Pháp mà vào Vương quốc Ý của Napoléon; mãi đến năm 1809 mới nhập vào các Tỉnh Illyria. Còn tại vịnh Kotor, quyền cai trị của Áo chấm dứt và trong giai đoạn 1806-1807 quyền cai trị của Nga được thiết lập; vịnh Kotor chỉ chuyển sang Pháp năm 1807. Hai sự khác biệt này không thể gói gọn trong một khung 'Pháp' duy nhất của atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Dalmatia chuyển sang quyền cai quản của Pháp — thi hành Hiệp ước Pressburg (Bratislava)", "00bfe4f6"], "d": ["Hiệp ước Pressburg (Bratislava) ngày 26 tháng 12 năm 1805 buộc Áo phải từ bỏ Istria, Dalmatia và toàn bộ các đảo trên biển Adriatic. Pháp thực tế tiếp quản quyền cai quản vào tháng 2 năm 1806; Zadar vẫn là trụ sở của tổng giám quản (provveditore generale), và trong giai đoạn 1806-1810 chức vụ này do Vicenzo Dandolo người Venice đảm nhiệm. Sau Hiệp ước Schönbrunn năm 1809, Dalmatia được sáp nhập vào các Tỉnh Illyria. Như vậy chấm dứt thời kỳ cai trị đầu tiên của Áo kéo dài từ năm 1797 — cho đến nay trong atlas, giai đoạn này vẫn hiển thị là thuộc Áo liên tục.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Áo lấy lại các Tỉnh Illyria và Dalmatia — chấm dứt sự cai trị của Napoléon", "1b2ac942"], "d": ["Cuối năm 1813, quân Habsburg lấy lại vùng đất phía nam sông Sava và tổ chức biên phòng cũ được tái lập; quân đội Áo tiến vào Istria tháng 10 năm 1813. Từ đó Karlovac là một phần của Vương quốc Illyria thuộc Áo. Giai đoạn cai trị của Pháp ở Dalmatia cũng khép lại năm 1813. Việc vùng này thuộc về Áo được chính thức phê chuẩn bằng các quyết định của Hòa ước Paris 1814 và Đại hội Vienna 1815. Với chiến dịch này, Villach, Tarvis, Görz, Gradisca và Pula (Các Tỉnh Illyria) trở về với Áo vào cuối năm 1813.", "bf1e49a8"]}
});
